import React, { useState, useCallback, useEffect } from 'react';
import { StoryForm } from './components/StoryForm';
import { StoryPreview } from './components/StoryPreview';
import { LoadingIndicator } from './components/LoadingIndicator';
import { MagicWandIcon } from './components/icons/MagicWandIcon';
import { BookOpenIcon } from './components/icons/BookOpenIcon';
import { FormData, Story } from './types';
import { generateStoryWorkflow } from './services/geminiService';
import { saveStoryToDB, getAllStoriesFromDB, deleteStoryFromDB } from './services/storageService';
import { StoryArchive } from './components/StoryArchive';

type AppView = 'create' | 'archive' | 'view-story';

const App: React.FC = () => {
    const [view, setView] = useState<AppView>('create');
    const [story, setStory] = useState<Story | null>(null);
    const [archive, setArchive] = useState<Story[]>([]);
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [loadingStep, setLoadingStep] = useState<string>('');
    const [error, setError] = useState<string | null>(null);

    // Load archive on mount
    useEffect(() => {
        loadArchive();
    }, []);

    const loadArchive = async () => {
        try {
            const stories = await getAllStoriesFromDB();
            setArchive(stories);
        } catch (err) {
            console.error("Failed to load archive", err);
        }
    };

    const handleStoryGeneration = useCallback(async (formData: FormData, imageData: { data: string; mimeType: string; }) => {
        setIsLoading(true);
        setError(null);
        setStory(null);

        const updateStep = (step: string) => {
            setLoadingStep(step);
        };

        try {
            const generatedStory = await generateStoryWorkflow(formData, imageData, updateStep);

            // Add metadata for storage
            const storyToSave: Story = {
                ...generatedStory,
                id: crypto.randomUUID(),
                timestamp: Date.now()
            };

            // Save to DB
            await saveStoryToDB(storyToSave);

            setStory(storyToSave);
            setView('view-story');
            loadArchive(); // Refresh archive list
        } catch (err: any) {
            console.error('Error generating story:', err);
            let errorMessage = 'حدث خطأ غير متوقع أثناء إنشاء القصة. يرجى المحاولة مرة أخرى.';
            if (err?.message?.includes('429')) {
                errorMessage = 'لقد تجاوزت الحد المسموح للاستخدام المجاني حالياً. يرجى الانتظار دقيقة والمحاولة مرة أخرى.';
            }
            setError(errorMessage);
        } finally {
            setIsLoading(false);
            setLoadingStep('');
        }
    }, []);

    const handleViewStory = (selectedStory: Story) => {
        setStory(selectedStory);
        setView('view-story');
    };

    const handleDeleteFromArchive = async (id: string) => {
        try {
            await deleteStoryFromDB(id);
            setArchive(prev => prev.filter(s => s.id !== id));
            if (story?.id === id) {
                setStory(null);
                setView('archive');
            }
        } catch (err) {
            alert("فشل حذف القصة من الأرشيف.");
        }
    };

    return (
        <div className="min-h-screen bg-rose-50 text-gray-800 pb-12" dir="rtl">
            <header className="bg-white shadow-md sticky top-0 z-40">
                <div className="container mx-auto px-4 py-3 flex flex-col sm:flex-row items-center justify-between gap-4">
                    <div 
                        className="flex items-center gap-3 cursor-pointer" 
                        onClick={() => setView('create')}
                    >
                        <MagicWandIcon className="h-8 w-8 text-rose-500" />
                        <h1 className="text-xl md:text-2xl font-bold text-rose-800">صانع قصص الأطفال</h1>
                    </div>

                    <nav className="flex items-center bg-rose-50 p-1 rounded-xl border border-rose-100">
                        <button 
                            onClick={() => setView('create')}
                            className={`px-6 py-2 rounded-lg font-bold transition flex items-center gap-2 ${view === 'create' || view === 'view-story' ? 'bg-white text-rose-600 shadow-sm' : 'text-gray-500 hover:text-rose-600'}`}
                        >
                            <MagicWandIcon className="h-4 w-4" />
                            <span>إنشاء قصة</span>
                        </button>
                        <button 
                            onClick={() => setView('archive')}
                            className={`px-6 py-2 rounded-lg font-bold transition flex items-center gap-2 ${view === 'archive' ? 'bg-white text-rose-600 shadow-sm' : 'text-gray-500 hover:text-rose-600'}`}
                        >
                            <BookOpenIcon className="h-4 w-4" />
                            <span>أرشيفي ({archive.length})</span>
                        </button>
                    </nav>
                </div>
            </header>

            <main className="container mx-auto p-4 md:p-8">
                {view === 'archive' ? (
                    <div className="max-w-4xl mx-auto">
                        <div className="flex items-center gap-3 mb-8">
                            <BookOpenIcon className="h-8 w-8 text-rose-500" />
                            <h2 className="text-3xl font-bold text-rose-800 font-storybook">أرشيف مغامراتي</h2>
                        </div>
                        <StoryArchive 
                            stories={archive} 
                            onViewStory={handleViewStory}
                            onDeleteStory={handleDeleteFromArchive}
                        />
                    </div>
                ) : (
                    <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                        <div className="lg:col-span-4">
                            <StoryForm onSubmit={handleStoryGeneration} isLoading={isLoading} />
                        </div>
                        <div className="lg:col-span-8">
                            {isLoading && <LoadingIndicator step={loadingStep} />}
                            {error && (
                                <div className="bg-red-50 border-l-4 border-red-500 text-red-700 p-6 rounded-lg shadow-sm" role="alert">
                                    <div className="flex items-center gap-3 mb-2">
                                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                                        </svg>
                                        <p className="font-bold text-lg">عذراً، حدث خطأ</p>
                                    </div>
                                    <p className="text-base">{error}</p>
                                </div>
                            )}
                            {story && !isLoading && (
                                <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
                                    <StoryPreview story={story} />
                                </div>
                            )}
                            {!story && !isLoading && !error && (
                                 <div className="flex flex-col items-center justify-center h-full bg-white rounded-2xl p-8 shadow-lg border-2 border-dashed border-rose-200 min-h-[400px]">
                                    <img src="https://picsum.photos/seed/storybook/400/300" alt="قصص الأطفال" className="rounded-lg mb-6 w-full max-w-sm shadow-inner opacity-80"/>
                                    <h2 className="text-2xl font-bold text-rose-700 mb-2 text-center">قصتك المخصصة تبدأ هنا!</h2>
                                    <p className="text-center text-gray-600 max-w-md">
                                        املأ النموذج على الجانب الأيمن، ارفع صورة لطفلك، ودع الذكاء الاصطناعي ينسج حكاية سحرية ويحفظها لك في أرشيفك الخاص.
                                    </p>
                                </div>
                            )}
                        </div>
                    </div>
                )}
            </main>
        </div>
    );
};

export default App;

import React from 'react';
import { createRoot } from 'react-dom/client';
import { Story } from '../types';
import { getStoryPages, PageData } from './storyHelper';
import { StoryPage } from '../components/StoryPage';

declare const html2canvas: any;

// Reduced to 1080p for better compatibility and performance on mobile devices
const VIDEO_WIDTH = 1080; 
const VIDEO_HEIGHT = 1920;
const FPS = 30;
const TRANSITION_DURATION_S = 0.6;
const POST_AUDIO_DELAY_S = 0.3;

const getSupportedMimeType = () => {
    // Standard webm/vp8 or vp9 is often more stable for MediaRecorder than mp4 in many browsers
    const types = [
        'video/webm;codecs=vp9,opus',
        'video/webm;codecs=vp8,opus',
        'video/mp4;codecs=avc1', 
        'video/webm',
        'video/mp4'
    ];
    for (const type of types) {
        if (MediaRecorder.isTypeSupported(type)) return type;
    }
    return '';
};

const easeOutCubic = (t: number): number => 1 - Math.pow(1 - t, 3);

const setupBackgroundMusic = (audioContext: AudioContext, destination: AudioNode) => {
    const mainGain = audioContext.createGain();
    mainGain.gain.value = 0.08; 
    mainGain.connect(destination);

    const playNote = (freq: number, startTime: number) => {
        try {
            const osc = audioContext.createOscillator();
            const g = audioContext.createGain();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(freq, startTime);
            g.gain.setValueAtTime(0, startTime);
            g.gain.linearRampToValueAtTime(0.4, startTime + 1);
            g.gain.exponentialRampToValueAtTime(0.001, startTime + 4);
            osc.connect(g);
            g.connect(mainGain);
            osc.start(startTime);
            osc.stop(startTime + 4);
        } catch (e) {
            console.warn("Audio note failed", e);
        }
    };

    const melody = [440, 554, 659, 880, 659, 554];
    let time = audioContext.currentTime;
    for (let i = 0; i < 30; i++) {
        melody.forEach((note, idx) => {
            playNote(note, time + (i * 6) + (idx * 1));
        });
    }
};

const createTurnSoundBuffer = (audioContext: AudioContext): AudioBuffer => {
    const duration = 0.4;
    const buffer = audioContext.createBuffer(1, Math.max(1, audioContext.sampleRate * duration), audioContext.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < buffer.length; i++) {
        data[i] = (Math.random() * 2 - 1) * 0.15 * (1 - i / buffer.length);
    }
    return buffer;
};

const loadAudio = async (url: string, audioContext: AudioContext): Promise<AudioBuffer> => {
    if (!url) return audioContext.createBuffer(1, audioContext.sampleRate, audioContext.sampleRate);
    try {
        const response = await fetch(url);
        const arrayBuffer = await response.arrayBuffer();
        return await audioContext.decodeAudioData(arrayBuffer);
    } catch (e) {
        console.error("Audio decode failed", e);
        return audioContext.createBuffer(1, audioContext.sampleRate, audioContext.sampleRate);
    }
};

const renderPageToImage = async (page: PageData, index: number, total: number, container: HTMLElement, root: any): Promise<HTMLImageElement> => {
    return new Promise(async (resolve, reject) => {
        try {
            root.render(
                <div style={{ width: VIDEO_WIDTH, height: VIDEO_HEIGHT, backgroundColor: '#F9F5EF' }}>
                    <StoryPage page={page} pageIndex={index} totalPages={total} />
                </div>
            );

            // Allow more time for complex components to render
            await new Promise(r => setTimeout(r, 800));

            const canvas = await html2canvas(container, {
                scale: 1, 
                width: VIDEO_WIDTH,
                height: VIDEO_HEIGHT,
                backgroundColor: '#F9F5EF',
                useCORS: true,
                logging: false,
                removeContainer: true
            });

            const img = new Image();
            img.src = canvas.toDataURL('image/jpeg', 0.85); // 0.85 quality is plenty for video
            img.onload = () => resolve(img);
            img.onerror = (e) => reject(e);
        } catch (err) {
            reject(err);
        }
    });
};

export const generateStoryVideo = async (story: Story, onProgress: (msg: string) => void): Promise<void> => {
    onProgress("بدء تحضير الفيديو...");

    const container = document.createElement('div');
    container.style.position = 'fixed';
    container.style.left = '-10000px'; 
    container.style.top = '0';
    container.style.width = `${VIDEO_WIDTH}px`;
    container.style.height = `${VIDEO_HEIGHT}px`;
    document.body.appendChild(container);
    const root = createRoot(container);

    const canvas = document.createElement('canvas');
    canvas.width = VIDEO_WIDTH;
    canvas.height = VIDEO_HEIGHT;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) {
        alert("متصفحك لا يدعم تقنية الرسوميات المطلوبة.");
        return;
    }

    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
    const dest = audioContext.createMediaStreamDestination();

    setupBackgroundMusic(audioContext, dest);
    const turnSound = createTurnSoundBuffer(audioContext);

    const videoStream = canvas.captureStream(FPS);
    const combinedStream = new MediaStream([
        ...videoStream.getVideoTracks(),
        ...dest.stream.getAudioTracks()
    ]);

    const mimeType = getSupportedMimeType();
    if (!mimeType) {
        alert("متصفحك لا يدعم تسجيل الفيديو.");
        return;
    }

    // Use 10Mbps - high quality but stable for 1080p
    const recorder = new MediaRecorder(combinedStream, { 
        mimeType, 
        videoBitsPerSecond: 10000000 
    }); 

    const chunks: Blob[] = [];
    recorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunks.push(e.data);
    };

    recorder.start();

    try {
        const pages = getStoryPages(story);
        let currentImg = await renderPageToImage(pages[0], 0, pages.length, container, root);

        for (let i = 0; i < pages.length; i++) {
            const isLast = i === pages.length - 1;
            onProgress(`تسجيل الصفحة ${i + 1} من ${pages.length}...`);

            const audioBuf = await loadAudio(pages[i].audioUrl || '', audioContext);
            const source = audioContext.createBufferSource();
            source.buffer = audioBuf;
            source.connect(dest);
            source.start();

            // Record while audio plays
            const startTime = Date.now();
            const durationMs = (audioBuf.duration + POST_AUDIO_DELAY_S) * 1000;

            while (Date.now() - startTime < durationMs) {
                ctx.drawImage(currentImg, 0, 0, VIDEO_WIDTH, VIDEO_HEIGHT);
                await new Promise(r => setTimeout(r, 1000 / FPS));
            }

            if (!isLast) {
                const nextImg = await renderPageToImage(pages[i + 1], i + 1, pages.length, container, root);

                const turnSource = audioContext.createBufferSource();
                turnSource.buffer = turnSound;
                turnSource.connect(dest);
                turnSource.start();

                const transFrames = Math.ceil(TRANSITION_DURATION_S * FPS);
                for (let t = 0; t <= transFrames; t++) {
                    const p = t / transFrames;
                    const easeP = easeOutCubic(p);

                    ctx.fillStyle = '#F9F5EF';
                    ctx.fillRect(0, 0, VIDEO_WIDTH, VIDEO_HEIGHT);

                    const nextWidth = VIDEO_WIDTH * easeP;
                    const nextX = VIDEO_WIDTH - nextWidth;

                    const brightness = 0.95 + (easeP * 0.05);
                    ctx.filter = `brightness(${brightness})`;
                    ctx.drawImage(nextImg, nextX, 0, nextWidth, VIDEO_HEIGHT);
                    ctx.filter = 'none';

                    // Shadow for depth
                    const shadowAlpha = (1 - easeP) * 0.25;
                    ctx.fillStyle = `rgba(0,0,0,${shadowAlpha})`;
                    ctx.fillRect(nextX - 10, 0, 10, VIDEO_HEIGHT);

                    await new Promise(r => setTimeout(r, 1000 / FPS));
                }
                currentImg = nextImg;
            }
        }

        onProgress("جارٍ إنهاء وحفظ الفيديو...");

        // Finalize recorder with a timeout safety
        return new Promise<void>((resolve) => {
            recorder.onstop = () => {
                const blob = new Blob(chunks, { type: mimeType });
                const url = URL.createObjectURL(blob);
                const ext = mimeType.includes('mp4') ? 'mp4' : 'webm';

                const a = document.createElement('a');
                a.href = url;
                a.download = `Story_${story.title.replace(/\s+/g, '_')}.${ext}`;
                a.click();

                audioContext.close();
                root.unmount();
                if (document.body.contains(container)) document.body.removeChild(container);
                resolve();
            };

            if (recorder.state !== 'inactive') {
                recorder.stop();
            } else {
                recorder.onstop(new Event('stop') as any);
            }
        });

    } catch (e) {
        console.error("Video Gen Error:", e);
        if (recorder.state !== 'inactive') recorder.stop();
        alert("حدث خطأ أثناء إنشاء الفيديو. يرجى المحاولة مرة أخرى.");
        root.unmount();
        if (document.body.contains(container)) document.body.removeChild(container);
    }
};

