const SCALE_FACTOR = VIDEO_WIDTH / BASE_DESIGN_WIDTH; // 1080 / 600 = 1.8
const BASE_DESIGN_HEIGHT = VIDEO_HEIGHT / SCALE_FACTOR; // 1920 / 1.8 = 1066.6

