export const generateStoryVideo = async (story: Story, onProgress: (msg: string) => void): Promise<void> => {
    onProgress("بدء تحضير الفيديو...");

    const container = document.createElement('div');
    container.style.position = 'fixed';
    container.style.left = '-10000px'; 
    container.style.top = '0';
    // Use design dimensions for the capture container
    container.style.width = `${BASE_DESIGN_WIDTH}px`;
    container.style.height = `${BASE_DESIGN_HEIGHT}px`;
    document.body.appendChild(container);
    const root = createRoot(container);

    const canvas = document.createElement('canvas');
    canvas.width = VIDEO_WIDTH;
    canvas.height = VIDEO_HEIGHT;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) {
        alert("متصفحك لا يدعم تقنية الرسوميات المطلوبة.");
        return;
    }

    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
    const dest = audioContext.createMediaStreamDestination();

    setupBackgroundMusic(audioContext, dest);
    const turnSound = createTurnSoundBuffer(audioContext);

    const videoStream = canvas.captureStream(FPS);
    const combinedStream = new MediaStream([
        ...videoStream.getVideoTracks(),
        ...dest.stream.getAudioTracks()
    ]);

    const mimeType = getSupportedMimeType();
    if (!mimeType) {
        alert("متصفحك لا يدعم تسجيل الفيديو.");
        return;
    }

    const recorder = new MediaRecorder(combinedStream, { 
        mimeType, 
        videoBitsPerSecond: 10000000 
    }); 

    const chunks: Blob[] = [];
    recorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunks.push(e.data);
    };

    recorder.start();

    try {
        const pages = getStoryPages(story);
        let currentImg = await renderPageToImage(pages[0], 0, pages.length, container, root);

        for (let i = 0; i < pages.length; i++) {
            const isLast = i === pages.length - 1;
            onProgress(`تسجيل الصفحة ${i + 1} من ${pages.length}...`);

            const audioBuf = await loadAudio(pages[i].audioUrl || '', audioContext);
            const source = audioContext.createBufferSource();
            source.buffer = audioBuf;
            source.connect(dest);
            source.start();

            const startTime = Date.now();
            const durationMs = (audioBuf.duration + POST_AUDIO_DELAY_S) * 1000;

            while (Date.now() - startTime < durationMs) {
                ctx.drawImage(currentImg, 0, 0, VIDEO_WIDTH, VIDEO_HEIGHT);
                await new Promise(r => setTimeout(r, 1000 / FPS));
            }

            if (!isLast) {
                const nextImg = await renderPageToImage(pages[i + 1], i + 1, pages.length, container, root);

                const turnSource = audioContext.createBufferSource();
                turnSource.buffer = turnSound;
                turnSource.connect(dest);
                turnSource.start();

                const transFrames = Math.ceil(TRANSITION_DURATION_S * FPS);
                for (let t = 0; t <= transFrames; t++) {
                    const p = t / transFrames;
                    const easeP = easeOutCubic(p);

                    ctx.fillStyle = '#F9F5EF';
                    ctx.fillRect(0, 0, VIDEO_WIDTH, VIDEO_HEIGHT);

                    const nextWidth = VIDEO_WIDTH * easeP;
                    const nextX = VIDEO_WIDTH - nextWidth;

                    const brightness = 0.95 + (easeP * 0.05);
                    ctx.filter = `brightness(${brightness})`;
                    ctx.drawImage(nextImg, nextX, 0, nextWidth, VIDEO_HEIGHT);
                    ctx.filter = 'none';

                    const shadowAlpha = (1 - easeP) * 0.25;
                    ctx.fillStyle = `rgba(0,0,0,${shadowAlpha})`;
                    ctx.fillRect(nextX - 10, 0, 10, VIDEO_HEIGHT);

                    await new Promise(r => setTimeout(r, 1000 / FPS));
                }
                currentImg = nextImg;
            }
        }

        onProgress("جارٍ إنهاء وحفظ الفيديو...");

        return new Promise<void>((resolve) => {
            recorder.onstop = () => {
                const blob = new Blob(chunks, { type: mimeType });
                const url = URL.createObjectURL(blob);
                const ext = mimeType.includes('mp4') ? 'mp4' : 'webm';

                const a = document.createElement('a');
                a.href = url;
                a.download = `Story_${story.title.replace(/\s+/g, '_')}.${ext}`;
                a.click();

                audioContext.close();
                root.unmount();
                if (document.body.contains(container)) document.body.removeChild(container);
                resolve();
            };

            if (recorder.state !== 'inactive') {
                recorder.stop();
            } else {
                recorder.onstop(new Event('stop') as any);
            }
        });

    } catch (e) {
        console.error("Video Gen Error:", e);
        if (recorder.state !== 'inactive') recorder.stop();
        alert("حدث خطأ أثناء إنشاء الفيديو. يرجى المحاولة مرة أخرى.");
        root.unmount();
        if (document.body.contains(container)) document.body.removeChild(container);
    }
};

