    // Priority list for TikTok/Social Media compatibility
    const types = [
        'video/mp4;codecs=avc1,mp4a.40.2', // H.264 + AAC (Perfect for TikTok)
        'video/mp4;codecs=avc1',
        'video/mp4',
        'video/webm;codecs=vp9,opus',
