// Helper to process, resize, and compress image before sending to API
const processImage = (file: File): Promise<{ data: string; mimeType: string; }> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = (e) => {
            const img = new Image();
            img.src = e.target?.result as string;
            img.onload = () => {
                // Resize logic: Max dimension 1536px (good for GenAI analysis)
                const MAX_SIZE = 1536; 
                let width = img.width;
                let height = img.height;

                if (width > MAX_SIZE || height > MAX_SIZE) {
                    if (width > height) {
                        height = Math.round((height * MAX_SIZE) / width);
                        width = MAX_SIZE;
                    } else {
                        width = Math.round((width * MAX_SIZE) / height);
                        height = MAX_SIZE;
                    }
                }

                const canvas = document.createElement('canvas');
                canvas.width = width;
                canvas.height = height;
                const ctx = canvas.getContext('2d');
                if (!ctx) {
                    reject(new Error("Could not get canvas context"));
                    return;
                }

                // Draw image to canvas
                ctx.drawImage(img, 0, 0, width, height);

                // Convert to JPEG with 0.85 quality (efficient compression)
                const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
                const base64Data = dataUrl.split(',')[1]; // Remove header
                resolve({ data: base64Data, mimeType: 'image/jpeg' });
            };
            img.onerror = () => reject(new Error("Could not load image."));
        };
        reader.onerror = (error) => reject(error);
    });
};


