import { GoogleGenAI, Modality, Type } from "@google/genai";
import { FormData, Story, Scene, Chapter } from '../types';
import { base64ToWav } from '../utils/audioHelper';

if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable not set");
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// --- Helper Functions for Retry & Throttling ---

const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

async function retryOperation<T>(
    operation: () => Promise<T>,
    retries: number = 4, // Increased retries
    initialDelay: number = 6000, // Increased start delay to 6s
    operationName: string = "Operation"
): Promise<T> {
    let currentDelay = initialDelay;
    for (let i = 0; i < retries; i++) {
        try {
            return await operation();
        } catch (error: any) {
            // Check for Rate Limit (429) or Server Errors (5xx)
            const isRateLimit = 
                error?.status === 429 || 
                error?.code === 429 || 
                error?.status === 'RESOURCE_EXHAUSTED' ||
                (error?.message && (
                    error.message.includes('429') || 
                    error.message.includes('quota') || 
                    error.message.includes('RESOURCE_EXHAUSTED')
                ));

            const isServerError = error?.status >= 500 && error?.status < 600;

            if (isRateLimit) {
                console.warn(`${operationName} hit rate limit (429). Pausing for ${currentDelay/1000}s before retry ${i + 1}/${retries}...`);
                await wait(currentDelay);
                currentDelay *= 1.5; // Exponential backoff
                continue;
            }

            if (isServerError && i < retries - 1) {
                console.warn(`${operationName} server error. Retrying in 2s...`);
                await wait(2000);
                continue;
            }

            if (i === retries - 1) {
                 console.warn(`${operationName} failed after ${retries} attempts. Error:`, error);
            }
            throw error;
        }
    }
    throw new Error(`${operationName} failed after max retries`);
}

