const generateStoryText = async (formData: FormData, characterDescription: string): Promise<Story> => {
    const { age, language, storyPrompt, numChapters, scenesPerChapter, childName } = formData;

    const prompt = `
        Create a story for a ${age}-year-old child named "${childName}" in ${language}.
        The story idea is: "${storyPrompt}".
        The main character is described as: "${characterDescription}".
        The story should have a fun, imaginative, and positive tone with a simple moral value.

        Generate a story with exactly ${numChapters} chapters.
        Each chapter must have its own title.
        Each chapter must have exactly ${scenesPerChapter} scenes.

        Return the response in JSON format according to the provided schema. Ensure the JSON is well-formed.
        The entire response must be a single JSON object.
    `;

    return retryOperation(async () => {
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        title: {
                            type: Type.STRING,
                            description: `A creative and short story title in ${language}`
                        },
                        chapters: {
                            type: Type.ARRAY,
                            description: `An array of exactly ${numChapters} chapters.`,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    chapter_number: { type: Type.INTEGER },
                                    title: {
                                        type: Type.STRING,
                                        description: `A creative title for this chapter in ${language}`
                                    },
                                    scenes: {
                                        type: Type.ARRAY,
                                        description: `An array of exactly ${scenesPerChapter} scenes for this chapter.`,
                                        items: {
                                            type: Type.OBJECT,
                                            properties: {
                                                scene_number: { type: Type.INTEGER },
                                                text: {
                                                    type: Type.STRING,
                                                    description: `The text for this scene in ${language}, simple and easy to understand for a child.`
                                                },
                                                image_prompt: {
                                                    type: Type.STRING,
                                                    description: `A concise prompt for editing an existing image of the main character ('${characterDescription}') to fit this scene. Describe the new background, actions, and any additional characters or objects. Example: 'The child is now in a magical forest, holding a glowing lantern.' Do not describe the child's appearance again, as it's in the base image.`
                                                },
                                            },
                                            required: ["scene_number", "text", "image_prompt"]
                                        },
                                    },
                                },
                                required: ["chapter_number", "title", "scenes"]
                            },
                        },
                    },
                    required: ["title", "chapters"]
                },
            },
        });

        try {
            const text = response.text;
            if (!text) throw new Error("Empty response from AI model");
            const storyData = JSON.parse(text);
            return storyData as Story;
        } catch(e) {
            console.error("Failed to parse story JSON:", response.text);
            throw new Error("The model returned an invalid story structure.");
        }
    }, 3, 5000, "Generate Story Text");
};

const generateImageForScene = async (
    imagePrompt: string, 
    baseImageBase64: string, 
    mimeType: string,
    characterDescription: string
): Promise<string> => {
    try {
        // Attempt 1: Reference Image
        return await retryOperation(async () => {
            const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash-image',
                contents: {
                    parts: [
                        {
                            inlineData: {
                                data: baseImageBase64,
                                mimeType: mimeType,
                            },
                        },
                        {
                            text: imagePrompt,
                        },
                    ],
                },
                config: {
                    responseModalities: [Modality.IMAGE],
                },
            });

            const firstPart = response.candidates?.[0]?.content?.parts?.[0];
            if (firstPart && firstPart.inlineData) {
                return `data:${firstPart.inlineData.mimeType};base64,${firstPart.inlineData.data}`;
            }
            throw new Error("No image data in response");
        }, 3, 8000, "Generate Image (Reference)"); 
    } catch (error) {
        console.warn("Primary image generation failed. Attempting text-only fallback.", error);

        // Attempt 2: Text Only Fallback
        return await retryOperation(async () => {
            const fallbackPrompt = `Digital illustration for a children's book. Character description: ${characterDescription}. Scene description: ${imagePrompt}. Style: Colorful 3D cartoon style.`;

            const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash-image',
                contents: {
                    parts: [{ text: fallbackPrompt }]
                },
                config: {
                    responseModalities: [Modality.IMAGE],
                },
            });

            const firstPart = response.candidates?.[0]?.content?.parts?.[0];
            if (firstPart && firstPart.inlineData) {
                return `data:${firstPart.inlineData.mimeType};base64,${firstPart.inlineData.data}`;
            }
            throw new Error("No image data in fallback response");
        }, 3, 8000, "Generate Image (Fallback)");
    }
};

const generateAudioSegment = async (text: string, voiceName: string): Promise<string | undefined> => {
    if (!text || text.trim().length === 0) return undefined;

    try {
        return await retryOperation(async () => {
            const response = await ai.models.generateContent({
                model: "gemini-2.5-flash-preview-tts",
                contents: {
                    parts: [{ text: text }]
                },
                config: {
                    responseModalities: [Modality.AUDIO],
                    speechConfig: {
                        voiceConfig: {
                            prebuiltVoiceConfig: { voiceName: voiceName },
                        },
                    },
                },
            });

            const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
            if (!base64Audio) throw new Error("Audio gen failed - no data");
            const wavBlob = base64ToWav(base64Audio, 24000);
            return URL.createObjectURL(wavBlob);
        }, 1, 3000, "Generate Audio"); 
    } catch (e) {
        console.warn("Audio generation failed for this segment. Continuing without audio.");
        return undefined;
    }
};

export const generateStoryWorkflow = async (
    formData: FormData,
    imageData: { data: string; mimeType: string; },
    updateStep: (step: string) => void
): Promise<Story> => {
    const { data: imageBase64, mimeType } = imageData;
    const { voiceName } = formData;

    updateStep("تحليل ملامح الطفل من الصورة...");
    const characterDescription = await analyzeChildImage(imageBase64, mimeType);

    // Safety delay
    await wait(3000);

    updateStep("كتابة نص القصة السحرية...");
    const story = await generateStoryText(formData, characterDescription);

    const chaptersWithAssets: Chapter[] = [];
    const totalScenes = story.chapters.reduce((sum, chapter) => sum + chapter.scenes.length, 0);
    let sceneCounter = 0;

    // Circuit breaker for audio to prevent spamming if quota is dead
    let audioQuotaExceeded = false;

    // 1. Generate Title Audio
    updateStep("تسجيل عنوان القصة...");
    let titleAudioUrl: string | undefined = undefined;

    if (!audioQuotaExceeded) {
         titleAudioUrl = await generateAudioSegment(`قصتنا باسم ${story.title}. ${formData.childName}.`, voiceName);
         if (!titleAudioUrl) audioQuotaExceeded = true; 
    }

    // 2. Process Chapters
    for (const chapter of story.chapters) {
        await wait(6000);

        // Chapter Title Audio
        let chapterAudioUrl: string | undefined = undefined;
        if (!audioQuotaExceeded) {
            chapterAudioUrl = await generateAudioSegment(chapter.title, voiceName);
            if (!chapterAudioUrl) audioQuotaExceeded = true;
        }

        const scenesWithAssets: Scene[] = [];
        for (const scene of chapter.scenes) {
            sceneCounter++;
            updateStep(`رسم وتسجيل المشهد ${sceneCounter} من ${totalScenes}...`);

            let imageUrl = "https://via.placeholder.com/1024x1024.png?text=Image+Unavailable"; 
            try {
                await wait(6000);
                imageUrl = await generateImageForScene(
                    scene.image_prompt, 
                    imageBase64, 
                    mimeType, 
                    characterDescription 
                );
            } catch (e) {
                console.error("Image generation failed for scene", scene.scene_number, e);
            }

            let audioUrl: string | undefined = undefined;
            if (!audioQuotaExceeded) {
                await wait(3000); 
                audioUrl = await generateAudioSegment(scene.text, voiceName);
                if (!audioUrl) {
                    console.warn("Audio quota likely hit. Disabling audio for remainder of story.");
                    audioQuotaExceeded = true;
                }
            }

            scenesWithAssets.push({ ...scene, imageUrl, audioUrl });
        }
        chaptersWithAssets.push({ ...chapter, scenes: scenesWithAssets, audioUrl: chapterAudioUrl });
    }

    // 3. Generate Outro Audio
    let outroAudioUrl: string | undefined = undefined;
    if (!audioQuotaExceeded) {
        updateStep("تسجيل الخاتمة...");
        const outroText = "وأنتم، هل تريدون قصص نجاح وبطولات ومغامرات باسم أولادكم وبناتكم؟ تواصلوا معنا الآن.";
        outroAudioUrl = await generateAudioSegment(outroText, voiceName);
    }

    updateStep("تجميع القصة...");

    return { ...story, chapters: chaptersWithAssets, titleAudioUrl, outroAudioUrl };
};

import React from 'react';
import { createRoot } from 'react-dom/client';
import { Story } from '../types';
import { getStoryPages, PageData } from './storyHelper';
import { StoryPage } from '../components/StoryPage';

declare const html2canvas: any;

const VIDEO_WIDTH = 1080; 
const VIDEO_HEIGHT = 1920;
const FPS = 30;
const TRANSITION_DURATION_S = 0.8; // زيادة طفيفة لوقت الانتقال ليكون أكثر نعومة
const POST_AUDIO_DELAY_S = 0.3;
const ZOOM_FACTOR = 0.12; // زيادة تأثير الزووم ليكون أكثر وضوحاً

const BASE_DESIGN_WIDTH = 600;
const SCALE_FACTOR = VIDEO_WIDTH / BASE_DESIGN_WIDTH; 
const BASE_DESIGN_HEIGHT = VIDEO_HEIGHT / SCALE_FACTOR;

const getSupportedMimeType = () => {
    const types = [
        'video/mp4;codecs=avc1,mp4a.40.2', 
        'video/mp4;codecs=avc1',           
        'video/mp4',
        'video/x-matroska;codecs=avc1',
        'video/webm;codecs=h264',
        'video/webm;codecs=vp9,opus',      
        'video/webm'                       
    ];

    for (const type of types) {
        if (MediaRecorder.isTypeSupported(type)) {
            return type;
        }
    }
    return 'video/webm';
};

// وظائف التخفيف (Easing Functions) لحركة أكثر طبيعية
const easeInOutCubic = (t: number): number => t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;

const setupBackgroundMusic = (audioContext: AudioContext, destination: AudioNode) => {
    const mainGain = audioContext.createGain();
    mainGain.gain.value = 0.05; 
    mainGain.connect(destination);

    const playNote = (freq: number, startTime: number) => {
        try {
            const osc = audioContext.createOscillator();
            const g = audioContext.createGain();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(freq, startTime);
            g.gain.setValueAtTime(0, startTime);
            g.gain.linearRampToValueAtTime(0.2, startTime + 1);
            g.gain.exponentialRampToValueAtTime(0.001, startTime + 4);
            osc.connect(g);
            g.connect(mainGain);
            osc.start(startTime);
            osc.stop(startTime + 4);
        } catch (e) {}
    };

    const melody = [440, 554, 659, 880, 659, 554];
    let time = audioContext.currentTime;
    for (let i = 0; i < 30; i++) {
        melody.forEach((note, idx) => {
            playNote(note, time + (i * 6) + (idx * 1));
        });
    }
};

const createTurnSoundBuffer = (audioContext: AudioContext): AudioBuffer => {
    const duration = 0.5;
    const buffer = audioContext.createBuffer(1, Math.max(1, audioContext.sampleRate * duration), audioContext.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < buffer.length; i++) {
        data[i] = (Math.random() * 2 - 1) * 0.08 * (1 - i / buffer.length);
    }
    return buffer;
};

const loadAudio = async (url: string, audioContext: AudioContext): Promise<AudioBuffer> => {
    if (!url) return audioContext.createBuffer(1, audioContext.sampleRate, audioContext.sampleRate);
    try {
        const response = await fetch(url);
        const arrayBuffer = await response.arrayBuffer();
        return await audioContext.decodeAudioData(arrayBuffer);
    } catch (e) {
        return audioContext.createBuffer(1, audioContext.sampleRate, audioContext.sampleRate);
    }
};

const renderPageToImage = async (page: PageData, index: number, total: number, container: HTMLElement, root: any): Promise<HTMLImageElement> => {
    return new Promise(async (resolve, reject) => {
        try {
            root.render(
                <div style={{ width: BASE_DESIGN_WIDTH, height: BASE_DESIGN_HEIGHT, backgroundColor: '#F9F5EF' }}>
                    <StoryPage page={page} pageIndex={index} totalPages={total} />
                </div>
            );
            await new Promise(r => setTimeout(r, 800));
            const canvas = await html2canvas(container, {
                scale: SCALE_FACTOR, 
                width: BASE_DESIGN_WIDTH,
                height: BASE_DESIGN_HEIGHT,
                backgroundColor: '#F9F5EF',
                useCORS: true,
                logging: false,
                removeContainer: true
            });
            const img = new Image();
            img.src = canvas.toDataURL('image/jpeg', 0.9);
            img.onload = () => resolve(img);
            img.onerror = (e) => reject(e);
        } catch (err) {
            reject(err);
        }
    });
};

export const generateStoryVideo = async (story: Story, onProgress: (msg: string, percent: number) => void): Promise<void> => {
    const mimeType = getSupportedMimeType();
    const isMP4 = mimeType.includes('mp4');

    onProgress(isMP4 ? "جاري البدء..." : "جاري تحسين الجودة لمتصفح أوبرا...", 5);

    const container = document.createElement('div');
    container.style.position = 'fixed';
    container.style.left = '-10000px'; 
    container.style.top = '0';
    container.style.width = `${BASE_DESIGN_WIDTH}px`;
    container.style.height = `${BASE_DESIGN_HEIGHT}px`;
    document.body.appendChild(container);
    const root = createRoot(container);

    const canvas = document.createElement('canvas');
    canvas.width = VIDEO_WIDTH;
    canvas.height = VIDEO_HEIGHT;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
    const dest = audioContext.createMediaStreamDestination();
    setupBackgroundMusic(audioContext, dest);
    const turnSound = createTurnSoundBuffer(audioContext);

    const videoStream = canvas.captureStream(FPS);
    const combinedStream = new MediaStream([
        ...videoStream.getVideoTracks(),
        ...dest.stream.getAudioTracks()
    ]);

    const recorder = new MediaRecorder(combinedStream, { 
        mimeType, 
        videoBitsPerSecond: 20000000 // جودة فائقة
    }); 

    const chunks: Blob[] = [];
    recorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunks.push(e.data);
    };

    recorder.start();

    try {
        const pages = getStoryPages(story);
        let currentImg = await renderPageToImage(pages[0], 0, pages.length, container, root);

        for (let i = 0; i < pages.length; i++) {
            const isLast = i === pages.length - 1;
            const progressPercent = 10 + Math.floor((i / pages.length) * 80);
            onProgress(`تسجيل المشهد ${i + 1}...`, progressPercent);

            const audioBuf = await loadAudio(pages[i].audioUrl || '', audioContext);
            const source = audioContext.createBufferSource();
            source.buffer = audioBuf;
            source.connect(dest);
            source.start();

            const startTime = Date.now();
            const durationMs = (audioBuf.duration + POST_AUDIO_DELAY_S) * 1000;

            // تسجيل المشهد الثابت مع الزووم
            while (Date.now() - startTime < durationMs) {
                const elapsed = Date.now() - startTime;
                const progress = Math.min(elapsed / durationMs, 1.0);
                const currentScale = 1 + (progress * ZOOM_FACTOR);

                const dw = VIDEO_WIDTH * currentScale;
                const dh = VIDEO_HEIGHT * currentScale;
                const dx = (VIDEO_WIDTH - dw) / 2;
                const dy = (VIDEO_HEIGHT - dh) / 2;

                ctx.fillStyle = '#F9F5EF';
                ctx.fillRect(0, 0, VIDEO_WIDTH, VIDEO_HEIGHT);
                ctx.drawImage(currentImg, dx, dy, dw, dh);

                await new Promise(r => setTimeout(r, 1000 / FPS));
            }

            // تنفيذ الانتقال للمشهد التالي
            if (!isLast) {
                const nextImg = await renderPageToImage(pages[i + 1], i + 1, pages.length, container, root);
                const turnSource = audioContext.createBufferSource();
                turnSource.buffer = turnSound;
                turnSource.connect(dest);
                turnSource.start();

                const transFrames = Math.ceil(TRANSITION_DURATION_S * FPS);
                for (let t = 0; t <= transFrames; t++) {
                    const p = t / transFrames;
                    const easeP = easeInOutCubic(p);

                    ctx.fillStyle = '#F9F5EF';
                    ctx.fillRect(0, 0, VIDEO_WIDTH, VIDEO_HEIGHT);

                    // المشهد القديم ينسحب لليسار ويتلاشى
                    ctx.globalAlpha = 1 - easeP;
                    const oldScale = 1 + ZOOM_FACTOR + (easeP * 0.05); // استمرار الزووم قليلاً
                    const oldW = VIDEO_WIDTH * oldScale;
                    const oldH = VIDEO_HEIGHT * oldScale;
                    const oldX = ((VIDEO_WIDTH - oldW) / 2) - (easeP * 300); // إزاحة لليسار
                    const oldY = (VIDEO_HEIGHT - oldH) / 2;
                    ctx.drawImage(currentImg, oldX, oldY, oldW, oldH);

                    // المشهد الجديد يظهر بتداخل مع حركة دفع من اليمين
                    ctx.globalAlpha = easeP;
                    const nextScale = 1.1 - (easeP * 0.1); // يبدأ أكبر قليلاً ويصغر للحجم الطبيعي
                    const nextW = VIDEO_WIDTH * nextScale;
                    const nextH = VIDEO_HEIGHT * nextScale;
                    const nextX = ((VIDEO_WIDTH - nextW) / 2) + ((1 - easeP) * 300); // دفع من اليمين
                    const nextY = (VIDEO_HEIGHT - nextH) / 2;
                    ctx.drawImage(nextImg, nextX, nextY, nextW, nextH);

                    ctx.globalAlpha = 1.0;
                    await new Promise(r => setTimeout(r, 1000 / FPS));
                }
                currentImg = nextImg;
            }
        }

        onProgress("تم التسجيل! جاري الحفظ...", 95);

        return new Promise<void>((resolve) => {
            recorder.onstop = () => {
                const finalBlob = new Blob(chunks, { type: mimeType });
                const url = URL.createObjectURL(finalBlob);
                const extension = isMP4 ? 'mp4' : 'webm';

                const a = document.createElement('a');
                a.href = url;
                const cleanTitle = story.title.replace(/[^\u0600-\u06FFa-zA-Z0-9]/g, '_');
                a.download = `Story_${cleanTitle}.${extension}`;
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);

                audioContext.close();
                root.unmount();
                if (document.body.contains(container)) document.body.removeChild(container);
                onProgress("اكتمل بنجاح!", 100);
                resolve();
            };
            recorder.stop();
        });

    } catch (e) {
        if (recorder.state !== 'inactive') recorder.stop();
        root.unmount();
        if (document.body.contains(container)) document.body.removeChild(container);
    }
};

import React, { useState, useEffect, useRef } from 'react';
import { Story } from '../types';
import { getStoryPages, PageData } from '../utils/storyHelper';
import { StoryPage } from './StoryPage';

interface BookReaderProps {
    story: Story;
    onClose: () => void;
}

export const BookReader: React.FC<BookReaderProps> = ({ story, onClose }) => {
    const [pages, setPages] = useState<PageData[]>([]);
    const [currentPage, setCurrentPage] = useState(0);
    const [prevPage, setPrevPage] = useState<number | null>(null);
    const [isPlaying, setIsPlaying] = useState(false);

    const audioRef = useRef<HTMLAudioElement | null>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const isFirstRender = useRef(true);

    // Flatten story structure into linear pages
    useEffect(() => {
        setPages(getStoryPages(story));
    }, [story]);

    // Initialize AudioContext for SFX
    useEffect(() => {
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        audioContextRef.current = new AudioContextClass();
        return () => {
            if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
                audioContextRef.current.close();
            }
        };
    }, []);

    // Sound Effect Generator
    const playSound = (type: 'click' | 'turn') => {
        const ctx = audioContextRef.current;
        if (!ctx) return;

        // Ensure context is running (browsers might suspend it)
        if (ctx.state === 'suspended') {
            ctx.resume().catch(() => {});
        }

        const t = ctx.currentTime;

        if (type === 'click') {
            // Short high-pitch blip for UI interaction
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.type = 'sine';
            osc.frequency.setValueAtTime(800, t);
            osc.frequency.exponentialRampToValueAtTime(400, t + 0.1);

            gain.gain.setValueAtTime(0.05, t);
            gain.gain.exponentialRampToValueAtTime(0.001, t + 0.1);

            osc.start(t);
            osc.stop(t + 0.1);

        } else if (type === 'turn') {
            // Filtered noise to simulate paper slide
            const bufferSize = ctx.sampleRate * 0.4; // 400ms
            const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
            const data = buffer.getChannelData(0);

            // Fill with soft noise
            for (let i = 0; i < bufferSize; i++) {
                data[i] = (Math.random() * 2 - 1) * 0.5;
            }

            const noise = ctx.createBufferSource();
            noise.buffer = buffer;

            // Lowpass filter sweeping down
            const filter = ctx.createBiquadFilter();
            filter.type = 'lowpass';
            filter.frequency.setValueAtTime(1200, t);
            filter.frequency.exponentialRampToValueAtTime(200, t + 0.3);

            // Envelope
            const gain = ctx.createGain();
            gain.gain.setValueAtTime(0, t);
            gain.gain.linearRampToValueAtTime(0.2, t + 0.05); // Attack
            gain.gain.exponentialRampToValueAtTime(0.001, t + 0.35); // Decay

            noise.connect(filter);
            filter.connect(gain);
            gain.connect(ctx.destination);

            noise.start(t);
        }
    };

    // Play page turn sound when currentPage changes (skip initial render)
    useEffect(() => {
        if (isFirstRender.current) {
            isFirstRender.current = false;
        } else {
            playSound('turn');
        }
    }, [currentPage]);

    // Handle Audio Playback & Auto-turn
    useEffect(() => {
        if (!isPlaying) {
            if (audioRef.current) {
                audioRef.current.pause();
            }
            return;
        }

        const currentPageData = pages[currentPage];

        if (currentPageData?.audioUrl) {
            if (audioRef.current) {
                audioRef.current.src = currentPageData.audioUrl;
                audioRef.current.play().catch(e => console.error("Playback failed", e));

                const handleEnded = () => {
                    if (currentPage < pages.length - 1) {
                        // Delay slightly for effect before flipping
                        setTimeout(() => {
                            setPrevPage(currentPage);
                            setCurrentPage(prev => prev + 1);
                        }, 1000);
                    } else {
                        setIsPlaying(false); // Stop at end
                    }
                };

                audioRef.current.onended = handleEnded;

                return () => {
                    if(audioRef.current) {
                        audioRef.current.onended = null;
                        audioRef.current.pause();
                    }
                };
            }
        } else {
            // If page has no audio (e.g. End page), wait a bit then stop or move on
            const timer = setTimeout(() => {
                if (currentPage < pages.length - 1) {
                   setPrevPage(currentPage);
                   setCurrentPage(prev => prev + 1);
                } else {
                    setIsPlaying(false);
                }
            }, 3000);
            return () => clearTimeout(timer);
        }
    }, [currentPage, isPlaying, pages]);

    const handleNext = () => {
        if (currentPage < pages.length - 1) {
            playSound('click');
            setPrevPage(currentPage);
            setCurrentPage(p => p + 1);
        }
    };

    const handlePrev = () => {
        if (currentPage > 0) {
            playSound('click');
            setPrevPage(currentPage);
            setCurrentPage(p => p - 1);
        }
    };

    const togglePlay = () => {
        playSound('click');
        setIsPlaying(!isPlaying);
    };

    const handleClose = () => {
        playSound('click');
        onClose();
    };

    return (
        <div className="fixed inset-0 z-50 bg-black/95 flex flex-col items-center justify-center p-2 sm:p-4 overflow-hidden">
            <audio ref={audioRef} className="hidden" />

            {/* Top Bar */}
            <div className="w-full max-w-lg flex justify-between items-center mb-4 text-white px-2 z-10">
                <button onClick={handleClose} className="hover:text-rose-400 transition p-2 bg-white/10 rounded-full">
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
                </button>
                <div className="flex gap-4">
                    <button onClick={togglePlay} className={`rounded-full p-3 transition shadow-lg ${isPlaying ? 'bg-rose-500 hover:bg-rose-600' : 'bg-emerald-500 hover:bg-emerald-600'}`}>
                        {isPlaying ? (
                            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="white" stroke="currentColor" strokeWidth="0"><rect x="6" y="4" width="4" height="16"></rect><rect x="14" y="4" width="4" height="16"></rect></svg>
                        ) : (
                            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="white" stroke="currentColor" strokeWidth="0"><polygon points="5 3 19 12 5 21 5 3"></polygon></svg>
                        )}
                    </button>
                </div>
            </div>

            {/* Book Container - 9:16 Aspect Ratio with Perspective */}
            <div className="relative w-full h-full max-h-[75vh] md:max-h-[85vh] aspect-[9/16] max-w-md perspective-2000 group">
                {/* Book Spine (Right side for RTL) */}
                <div className="absolute right-[-4px] top-[2%] bottom-[2%] w-4 bg-rose-900/40 rounded-r-lg blur-[2px] z-0"></div>

                <div className="relative w-full h-full transform-style-3d">

                    {/* Previous Page (Backing) - shows static underneath while the new one flips */}
                    {prevPage !== null && pages[prevPage] && (
                        <div className="absolute inset-0 bg-[#F9F5EF] rounded-xl shadow-inner overflow-hidden opacity-40 grayscale-[0.2]">
                             <StoryPage 
                                page={pages[prevPage]} 
                                pageIndex={prevPage} 
                                totalPages={pages.length} 
                            />
                        </div>
                    )}

                    {/* Current Page - Flipping In */}
                    {pages[currentPage] && (
                        <div 
                            key={currentPage} 
                            className="absolute inset-0 bg-white rounded-xl shadow-2xl overflow-hidden animate-page-flip origin-right-spine"
                            style={{ 
                                backfaceVisibility: 'hidden',
                                transformStyle: 'preserve-3d',
                            }}
                        >
                            {/* Inner Page Shadow to enhance 3D feel during the flip */}
                            <div className="absolute inset-0 z-50 pointer-events-none bg-gradient-to-l from-black/20 via-transparent to-transparent opacity-0 animate-page-inner-shadow"></div>

                            <StoryPage 
                                page={pages[currentPage]} 
                                pageIndex={currentPage} 
                                totalPages={pages.length} 
                            />

                            {/* Close button inside end page specifically */}
                            {pages[currentPage].type === 'end' && (
                                <div className="absolute bottom-10 left-0 right-0 flex justify-center z-50">
                                     <button onClick={handleClose} className="px-8 py-3 bg-rose-600 text-white rounded-full font-bold hover:bg-rose-700 transition shadow-lg">
                                        إغلاق الكتاب
                                    </button>
                                </div>
                            )}
                        </div>
                    )}
                </div>
            </div>

             {/* Navigation Controls */}
             <div className="w-full max-w-lg flex justify-between items-center mt-6 px-4 z-10">
                 <button 
                    onClick={handlePrev} 
                    disabled={currentPage === 0}
                    className="text-white bg-white/10 rounded-full p-2 disabled:opacity-20 hover:bg-white/20 transition-all active:scale-95"
                 >
                     <svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 18 9 12 15 6"></polyline></svg>
                 </button>

                 <div className="bg-white/10 px-4 py-1 rounded-full text-white/80 text-sm font-medium backdrop-blur-md border border-white/5">
                     {currentPage + 1} / {pages.length}
                 </div>

                 <button 
                    onClick={handleNext} 
                    disabled={currentPage === pages.length - 1}
                    className="text-white bg-white/10 rounded-full p-2 disabled:opacity-20 hover:bg-white/20 transition-all active:scale-95"
                 >
                    <svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="9 18 15 12 9 6"></polyline></svg>
                 </button>
             </div>

             <style>{`
                .perspective-2000 { perspective: 2000px; }
                .transform-style-3d { transform-style: preserve-3d; }
                .origin-right-spine { transform-origin: right center; }

                @keyframes pageFlip {
                    0% { 
                        transform: rotateY(110deg); 
                        filter: brightness(0.6);
                        box-shadow: 0 0 0 rgba(0,0,0,0);
                    }
                    100% { 
                        transform: rotateY(0deg); 
                        filter: brightness(1);
                        box-shadow: -10px 10px 30px rgba(0,0,0,0.3);
                    }
                }

                .animate-page-flip {
                    animation: pageFlip 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
                }

                @keyframes innerShadow {
                    0% { opacity: 0.8; }
                    50% { opacity: 0.3; }
                    100% { opacity: 0; }
                }

                .animate-page-inner-shadow {
                    animation: innerShadow 0.8s ease-out forwards;
                }

                /* Smooth hide effect for the underlying prev page */
                @keyframes fadeUnder {
                    0% { opacity: 0.4; }
