                                <div className="space-y-4">
                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 mb-2">جودة الفيديو (Bitrate)</label>
                                        <select 
                                            value={videoQuality}
                                            onChange={(e) => setVideoQuality(Number(e.target.value))}
                                            className="w-full text-sm border border-gray-200 rounded p-1.5 focus:ring-1 focus:ring-rose-400 outline-none"
                                        >
                                            <option value={20000000}>فائقة (20Mbps)</option>
                                            <option value={10000000}>عالية (10Mbps)</option>
                                            <option value={5000000}>متوسطة (5Mbps)</option>
                                            <option value={2000000}>منخفضة (2Mbps)</option>
                                        </select>
                                    </div>

                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 mb-2">معدل الإطارات (FPS)</label>
                                        <select 
                                            value={frameRate}
                                            onChange={(e) => setFrameRate(Number(e.target.value))}
                                            className="w-full text-sm border border-gray-200 rounded p-1.5 focus:ring-1 focus:ring-rose-400 outline-none"
                                        >
                                            <option value={60}>60 إطار (سلاسة تامة)</option>
                                            <option value={30}>30 إطار (قياسي)</option>
                                            <option value={24}>24 إطار (سينمائي)</option>
                                        </select>
                                    </div>

                                    <button 
                                        onClick={handleDownloadVideo}
                                        className="w-full bg-emerald-500 hover:bg-emerald-600 text-white font-bold py-2 rounded shadow-md transition-colors"
                                    >
                                        بدء الإنشاء الآن
                                    </button>
                                </div>
                            </div>
                        )}
                    </div>

                    <button
                        onClick={handleDownloadPdf}
                        disabled={isDownloadingPdf}
                        className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-green-500 text-white font-bold py-2 px-6 rounded-lg hover:bg-green-600 transition duration-300 disabled:bg-green-300"
                    >
                        <DownloadIcon className="h-5 w-5" />
                        {isDownloadingPdf ? 'جارٍ...' : 'PDF'}
                    </button>
                </div>
            </div>

            <div id="story-content" className="flex flex-col gap-10">
                {storyPages.map((page, idx) => (
                    <div 
                        key={idx} 
                        className="story-page shadow-2xl rounded-lg overflow-hidden w-full aspect-[1/1.414] max-w-[600px] mx-auto border-4 border-white"
                        style={{ height: 'auto' }}
                    >
                        <StoryPage 
                            page={page} 
                            pageIndex={idx} 
                            totalPages={storyPages.length} 
                        />
                    </div>
                ))}
            </div>

            <div className="mt-8 text-center text-gray-400 text-sm">
                تحقق من القصة أعلاه، يمكنك قراءتها بشكل تفاعلي أو تحميلها كملف PDF فاخر أو فيديو لـ تيك توك.
            </div>
        </div>
    );
};

