const analyzeChildImage = async (imageBase64: string, mimeType: string): Promise<string> => {
    try {
        return await retryOperation(async () => {
            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: {
                    parts: [
                        {
                            inlineData: {
                                mimeType: mimeType,
                                data: imageBase64,
                            },
                        },
                        {
                            text: "Describe this child's main features (hair color and style, eye color, skin tone) in a simple, descriptive style suitable for a children's book cartoon character. Be concise. Example: 'a child with curly brown hair, big green eyes, and a cheerful smile'."
                        }
                    ]
                },
            });
            return typeof response.text === 'string' ? response.text : "A happy child with a bright smile";
        }, 3, 4000, "Analyze Image");
    } catch (error) {
