};

const generateStoryText = async (formData: FormData, characterDescription: string): Promise<Story> => {
    const { age, language, storyPrompt, numChapters, scenesPerChapter, childName } = formData;

    const prompt = `
        Create a story for a ${age}-year-old child named "${childName}" in ${language}.
        The story idea is: "${storyPrompt}".
        The main character is described as: "${characterDescription}".
        The story should have a fun, imaginative, and positive tone with a simple moral value.

        Generate a story with exactly ${numChapters} chapters.
        Each chapter must have its own title.
        Each chapter must have exactly ${scenesPerChapter} scenes.

        Return the response in JSON format according to the provided schema. Ensure the JSON is well-formed.
        The entire response must be a single JSON object.
    `;

    return retryOperation(async () => {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        title: {
                            type: Type.STRING,
                            description: `A creative and short story title in ${language}`
                        },
                        chapters: {
                            type: Type.ARRAY,
                            description: `An array of exactly ${numChapters} chapters.`,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    chapter_number: { type: Type.INTEGER },
                                    title: {
                                        type: Type.STRING,
                                        description: `A creative title for this chapter in ${language}`
                                    },
                                    scenes: {
                                        type: Type.ARRAY,
                                        description: `An array of exactly ${scenesPerChapter} scenes for this chapter.`,
                                        items: {
                                            type: Type.OBJECT,
                                            properties: {
                                                scene_number: { type: Type.INTEGER },
                                                text: {
                                                    type: Type.STRING,
                                                    description: `The text for this scene in ${language}, simple and easy to understand for a child.`
                                                },
                                                image_prompt: {
                                                    type: Type.STRING,
                                                    description: `A concise prompt for editing an existing image of the main character ('${characterDescription}') to fit this scene. Describe the new background, actions, and any additional characters or objects. Example: 'The child is now in a magical forest, holding a glowing lantern.' Do not describe the child's appearance again, as it's in the base image.`
                                                },
                                            },
                                            required: ["scene_number", "text", "image_prompt"]
                                        },
                                    },
                                },
                                required: ["chapter_number", "title", "scenes"]
                            },
                        },
                    },
                    required: ["title", "chapters"]
                },
            },
        });

        try {
            const text = response.text;
            if (!text) throw new Error("Empty response from AI model");
            const storyData = JSON.parse(text);

            // Validation to prevent rendering issues
            if (typeof storyData.title !== 'string') storyData.title = String(storyData.title);

            return storyData as Story;
        } catch(e) {
            console.error("Failed to parse story JSON:", response.text);
            throw new Error("The model returned an invalid story structure.");
        }
    }, 3, 5000, "Generate Story Text");
};

const generateImageForScene = async (
    imagePrompt: string, 
    baseImageBase64: string, 
    mimeType: string,
    characterDescription: string
): Promise<string> => {
    try {
        return await retryOperation(async () => {
            const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash-image',
                contents: {
                    parts: [
                        {
                            inlineData: {
                                data: baseImageBase64,
                                mimeType: mimeType,
                            },
                        },
                        {
                            text: imagePrompt,
                        },
                    ],
                },
                config: {
                    responseModalities: [Modality.IMAGE],
                },
            });

            const firstPart = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
            if (firstPart && firstPart.inlineData) {
                return `data:${firstPart.inlineData.mimeType};base64,${firstPart.inlineData.data}`;
            }
            throw new Error("No image data in response");
        }, 3, 8000, "Generate Image (Reference)"); 
    } catch (error) {
        console.warn("Primary image generation failed. Attempting text-only fallback.", error);

        return await retryOperation(async () => {
            const fallbackPrompt = `Digital illustration for a children's book. Character description: ${characterDescription}. Scene description: ${imagePrompt}. Style: Colorful 3D cartoon style.`;

            const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash-image',
                contents: {
                    parts: [{ text: fallbackPrompt }]
                },
                config: {
                    responseModalities: [Modality.IMAGE],
                },
            });

            const firstPart = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
            if (firstPart && firstPart.inlineData) {
                return `data:${firstPart.inlineData.mimeType};base64,${firstPart.inlineData.data}`;
            }
            throw new Error("No image data in fallback response");
        }, 3, 8000, "Generate Image (Fallback)");
    }
};

const generateAudioSegment = async (text: string, voiceName: string): Promise<string | undefined> => {
    if (!text || text.trim().length === 0) return undefined;

    try {
        return await retryOperation(async () => {
            const response = await ai.models.generateContent({
                model: "gemini-2.5-flash-preview-tts",
                contents: {
                    parts: [{ text: text }]
                },
                config: {
                    responseModalities: [Modality.AUDIO],
                    speechConfig: {
                        voiceConfig: {
                            prebuiltVoiceConfig: { voiceName: voiceName },
                        },
                    },
                },
            });

            const audioPart = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
            const base64Audio = audioPart?.inlineData?.data;
            if (!base64Audio) throw new Error("Audio gen failed - no data");
            const wavBlob = base64ToWav(base64Audio, 24000);
            return URL.createObjectURL(wavBlob);
        }, 1, 3000, "Generate Audio"); 
    } catch (e) {
        console.warn("Audio generation failed for this segment. Continuing without audio.");
        return undefined;
    }
};

export const generateStoryWorkflow = async (
    formData: FormData,
    imageData: { data: string; mimeType: string; },
    updateStep: (step: string) => void
): Promise<Story> => {
    const { data: imageBase64, mimeType } = imageData;
    const { voiceName } = formData;

    updateStep("تحليل ملامح الطفل من الصورة...");
    const characterDescription = await analyzeChildImage(imageBase64, mimeType);

    await wait(2000);

    updateStep("كتابة نص القصة السحرية...");
    const story = await generateStoryText(formData, characterDescription);

    const chaptersWithAssets: Chapter[] = [];
    const totalScenes = story.chapters.reduce((sum, chapter) => sum + chapter.scenes.length, 0);
    let sceneCounter = 0;

    let audioQuotaExceeded = false;

    updateStep("تسجيل عنوان القصة...");
    let titleAudioUrl: string | undefined = undefined;

    if (!audioQuotaExceeded) {
         titleAudioUrl = await generateAudioSegment(`قصتنا اليوم بعنوان: ${story.title}. أبطالنا هم ${formData.childName}. لنبدأ!`, voiceName);
         if (!titleAudioUrl) audioQuotaExceeded = true; 
    }

    for (const chapter of story.chapters) {
        await wait(2000);

        let chapterAudioUrl: string | undefined = undefined;
        if (!audioQuotaExceeded) {
            chapterAudioUrl = await generateAudioSegment(chapter.title, voiceName);
            if (!chapterAudioUrl) audioQuotaExceeded = true;
        }

        const scenesWithAssets: Scene[] = [];
        for (const scene of chapter.scenes) {
            sceneCounter++;
            updateStep(`رسم وتسجيل المشهد ${sceneCounter} من ${totalScenes}...`);

            let imageUrl = "https://via.placeholder.com/1024x1024.png?text=Image+Unavailable"; 
            try {
                await wait(4000);
                imageUrl = await generateImageForScene(
                    scene.image_prompt, 
                    imageBase64, 
                    mimeType, 
                    characterDescription 
                );
            } catch (e) {
                console.error("Image generation failed for scene", scene.scene_number, e);
            }

            let audioUrl: string | undefined = undefined;
            if (!audioQuotaExceeded) {
                await wait(2000); 
                audioUrl = await generateAudioSegment(scene.text, voiceName);
                if (!audioUrl) {
                    audioQuotaExceeded = true;
                }
            }

            scenesWithAssets.push({ ...scene, imageUrl, audioUrl });
        }
        chaptersWithAssets.push({ ...chapter, scenes: scenesWithAssets, audioUrl: chapterAudioUrl });
    }

    let outroAudioUrl: string | undefined = undefined;
    if (!audioQuotaExceeded) {
        updateStep("تسجيل الخاتمة...");
        const outroText = "وهكذا تنتهي مغامرتنا اليوم! هل أعجبتكم القصة؟ لا تنسوا مشاركتها مع أصدقائكم.";
        outroAudioUrl = await generateAudioSegment(outroText, voiceName);
    }

    updateStep("تجميع القصة النهائية...");

    return { ...story, chapters: chaptersWithAssets, titleAudioUrl, outroAudioUrl };
};

