};

const generateStoryText = async (formData: FormData, characterDescription: string): Promise<Story> => {
    const { age, language, storyPrompt, numChapters, scenesPerChapter, childName } = formData;

    const prompt = `
        Create a story for a ${age}-year-old child named "${childName}" in ${language}.
        The story idea is: "${storyPrompt}".
        The main character is described as: "${characterDescription}".
        The story should have a fun, imaginative, and positive tone with a simple moral value.

        Generate a story with exactly ${numChapters} chapters.
        Each chapter must have its own title.
        Each chapter must have exactly ${scenesPerChapter} scenes.
        Use modern standard numerals (1, 2, 3) in the titles and text for maximum readability across all devices.

        Return the response in JSON format according to the provided schema. Ensure the JSON is well-formed.
        The entire response must be a single JSON object.
    `;

    return retryOperation(async () => {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        title: {
                            type: Type.STRING,
                            description: `A creative and short story title in ${language}`
                        },
                        chapters: {
                            type: Type.ARRAY,
                            description: `An array of exactly ${numChapters} chapters.`,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    chapter_number: { type: Type.INTEGER },
                                    title: {
                                        type: Type.STRING,
                                        description: `A creative title for this chapter in ${language}`
                                    },
                                    scenes: {
                                        type: Type.ARRAY,
                                        description: `An array of exactly ${scenesPerChapter} scenes for this chapter.`,
                                        items: {
                                            type: Type.OBJECT,
                                            properties: {
                                                scene_number: { type: Type.INTEGER },
                                                text: {
                                                    type: Type.STRING,
                                                    description: `The text for this scene in ${language}, simple and easy to understand for a child.`
                                                },
                                                image_prompt: {
                                                    type: Type.STRING,
                                                    description: `A concise prompt for editing an existing image of the main character ('${characterDescription}') to fit this scene. Describe the new background, actions, and any additional characters or objects. Example: 'The child is now in a magical forest, holding a glowing lantern.' Do not describe the child's appearance again, as it's in the base image.`
                                                },
                                            },
                                            required: ["scene_number", "text", "image_prompt"]
                                        },
                                    },
                                },
                                required: ["chapter_number", "title", "scenes"]
                            },
                        },
                    },
                    required: ["title", "chapters"]
                },
            },
        });

        try {
            const text = response.text;
            if (!text) throw new Error("Empty response from AI model");
            const storyData = JSON.parse(text);

            // Validation to prevent rendering issues
            if (typeof storyData.title !== 'string') storyData.title = String(storyData.title);

            return storyData as Story;
        } catch(e) {
            console.error("Failed to parse story JSON:", response.text);
            throw new Error("The model returned an invalid story structure.");
        }
    }, 3, 5000, "Generate Story Text");
};

const generateImageForScene = async (
    imagePrompt: string, 
    baseImageBase64: string, 
    mimeType: string,
    characterDescription: string
): Promise<string> => {
    try {
        return await retryOperation(async () => {
            const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash-image',
                contents: {
                    parts: [
                        {
                            inlineData: {
                                data: baseImageBase64,
                                mimeType: mimeType,
                            },
                        },
                        {
                            text: imagePrompt,
                        },
                    ],
                },
                config: {
                    responseModalities: [Modality.IMAGE],
                },
            });

            const firstPart = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
            if (firstPart && firstPart.inlineData) {
                return `data:${firstPart.inlineData.mimeType};base64,${firstPart.inlineData.data}`;
            }
            throw new Error("No image data in response");
        }, 3, 8000, "Generate Image (Reference)"); 
    } catch (error) {
        console.warn("Primary image generation failed. Attempting text-only fallback.", error);

        return await retryOperation(async () => {
            const fallbackPrompt = `Digital illustration for a children's book. Character description: ${characterDescription}. Scene description: ${imagePrompt}. Style: Colorful 3D cartoon style.`;

            const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash-image',
                contents: {
                    parts: [{ text: fallbackPrompt }]
                },
                config: {
                    responseModalities: [Modality.IMAGE],
                },
            });

            const firstPart = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
            if (firstPart && firstPart.inlineData) {
                return `data:${firstPart.inlineData.mimeType};base64,${firstPart.inlineData.data}`;
            }
            throw new Error("No image data in fallback response");
        }, 3, 8000, "Generate Image (Fallback)");
    }
};

const generateAudioSegment = async (text: string, voiceName: string): Promise<string | undefined> => {
    if (!text || text.trim().length === 0) return undefined;

    try {
        return await retryOperation(async () => {
            const response = await ai.models.generateContent({
                model: "gemini-2.5-flash-preview-tts",
                contents: {
                    parts: [{ text: text }]
                },
                config: {
                    responseModalities: [Modality.AUDIO],
                    speechConfig: {
                        voiceConfig: {
                            prebuiltVoiceConfig: { voiceName: voiceName },
                        },
                    },
                },
            });

            const audioPart = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
            const base64Audio = audioPart?.inlineData?.data;
            if (!base64Audio) throw new Error("Audio gen failed - no data");
            const wavBlob = base64ToWav(base64Audio, 24000);
            return URL.createObjectURL(wavBlob);
        }, 1, 3000, "Generate Audio"); 
    } catch (e) {
        console.warn("Audio generation failed for this segment. Continuing without audio.");
        return undefined;
    }
};

export const generateStoryWorkflow = async (
    formData: FormData,
    imageData: { data: string; mimeType: string; },
    updateStep: (step: string) => void
): Promise<Story> => {
    const { data: imageBase64, mimeType } = imageData;
    const { voiceName } = formData;

    updateStep("تحليل ملامح الطفل من الصورة...");
    const characterDescription = await analyzeChildImage(imageBase64, mimeType);

    await wait(2000);

    updateStep("كتابة نص القصة السحرية...");
    const story = await generateStoryText(formData, characterDescription);

    const chaptersWithAssets: Chapter[] = [];
    const totalScenes = story.chapters.reduce((sum, chapter) => sum + chapter.scenes.length, 0);
    let sceneCounter = 0;

    let audioQuotaExceeded = false;

    updateStep("تسجيل عنوان القصة...");
    let titleAudioUrl: string | undefined = undefined;

    if (!audioQuotaExceeded) {
         titleAudioUrl = await generateAudioSegment(`قصتنا اليوم بعنوان: ${story.title}. أبطالنا هم ${formData.childName}. لنبدأ!`, voiceName);
         if (!titleAudioUrl) audioQuotaExceeded = true; 
    }

    for (const chapter of story.chapters) {
        await wait(2000);

        let chapterAudioUrl: string | undefined = undefined;
        if (!audioQuotaExceeded) {
            chapterAudioUrl = await generateAudioSegment(chapter.title, voiceName);
            if (!chapterAudioUrl) audioQuotaExceeded = true;
        }

        const scenesWithAssets: Scene[] = [];
        for (const scene of chapter.scenes) {
            sceneCounter++;
            updateStep(`رسم وتسجيل المشهد ${sceneCounter} من ${totalScenes}...`);

            let imageUrl = "https://via.placeholder.com/1024x1024.png?text=Image+Unavailable"; 
            try {
                await wait(4000);
                imageUrl = await generateImageForScene(
                    scene.image_prompt, 
                    imageBase64, 
                    mimeType, 
                    characterDescription 
                );
            } catch (e) {
                console.error("Image generation failed for scene", scene.scene_number, e);
            }

            let audioUrl: string | undefined = undefined;
            if (!audioQuotaExceeded) {
                await wait(2000); 
                audioUrl = await generateAudioSegment(scene.text, voiceName);
                if (!audioUrl) {
                    audioQuotaExceeded = true;
                }
            }

            scenesWithAssets.push({ ...scene, imageUrl, audioUrl });
        }
        chaptersWithAssets.push({ ...chapter, scenes: scenesWithAssets, audioUrl: chapterAudioUrl });
    }

    let outroAudioUrl: string | undefined = undefined;
    if (!audioQuotaExceeded) {
        updateStep("تسجيل الخاتمة...");
        const outroText = "وهكذا تنتهي مغامرتنا اليوم! هل أعجبتكم القصة؟ لا تنسوا مشاركتها مع أصدقائكم.";
        outroAudioUrl = await generateAudioSegment(outroText, voiceName);
    }

    updateStep("تجميع القصة النهائية...");

    return { ...story, chapters: chaptersWithAssets, titleAudioUrl, outroAudioUrl };
};

import React from 'react';
import { createRoot } from 'react-dom/client';
import { Story } from '../types';
import { getStoryPages, PageData } from './storyHelper';
import { StoryPage } from '../components/StoryPage';

declare const html2canvas: any;

const VIDEO_WIDTH = 1080; 
const VIDEO_HEIGHT = 1920;
const TRANSITION_DURATION_S = 0.8; 
const POST_AUDIO_DELAY_S = 0.5;
const ZOOM_FACTOR = 0.12; 

const BASE_DESIGN_WIDTH = 600;
const SCALE_FACTOR = VIDEO_WIDTH / BASE_DESIGN_WIDTH; 
const BASE_DESIGN_HEIGHT = VIDEO_HEIGHT / SCALE_FACTOR;

const getSupportedMimeType = () => {
    const types = [
        'video/webm;codecs=vp9,opus',
        'video/webm;codecs=vp8,opus',
        'video/webm',
        'video/mp4;codecs=avc1',
        'video/mp4'
    ];

    for (const type of types) {
        if (MediaRecorder.isTypeSupported(type)) {
            return type;
        }
    }
    return '';
};

const easeInOutCubic = (t: number): number => t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;

const setupBackgroundMusic = (audioContext: AudioContext, destination: AudioNode) => {
    const mainGain = audioContext.createGain();
    mainGain.gain.value = 0.04; 
    mainGain.connect(destination);

    const playNote = (freq: number, startTime: number) => {
        try {
            const osc = audioContext.createOscillator();
            const g = audioContext.createGain();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(freq, startTime);
            g.gain.setValueAtTime(0, startTime);
            g.gain.linearRampToValueAtTime(0.15, startTime + 0.5);
            g.gain.exponentialRampToValueAtTime(0.001, startTime + 4);
            osc.connect(g);
            g.connect(mainGain);
            osc.start(startTime);
            osc.stop(startTime + 4);
        } catch (e) {}
    };

    const melody = [440, 554, 659, 880, 659, 554];
    let time = audioContext.currentTime;
    // Pre-schedule some background music for up to 10 minutes
    for (let i = 0; i < 100; i++) {
        melody.forEach((note, idx) => {
            playNote(note, time + (i * 6) + (idx * 1));
        });
    }
};

const createTurnSoundBuffer = (audioContext: AudioContext): AudioBuffer => {
    const duration = 0.5;
    const buffer = audioContext.createBuffer(1, Math.max(1, audioContext.sampleRate * duration), audioContext.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < buffer.length; i++) {
        data[i] = (Math.random() * 2 - 1) * 0.05 * (1 - i / buffer.length);
    }
    return buffer;
};

const loadAudio = async (url: string, audioContext: AudioContext): Promise<AudioBuffer> => {
    if (!url) return audioContext.createBuffer(1, audioContext.sampleRate, audioContext.sampleRate);
    try {
        const response = await fetch(url);
        if (!response.ok) throw new Error("Fetch failed");
        const arrayBuffer = await response.arrayBuffer();
        return await audioContext.decodeAudioData(arrayBuffer);
    } catch (e) {
        console.warn("Audio load failed for URL:", url, e);
        // Return 1 second of silence as fallback
        return audioContext.createBuffer(1, audioContext.sampleRate, audioContext.sampleRate);
    }
};

const renderPageToImage = async (
    page: PageData, 
    index: number, 
    total: number, 
    container: HTMLElement, 
    root: any,
    textFontSize?: number
): Promise<HTMLImageElement | null> => {
    try {
        root.render(
            <div style={{ width: BASE_DESIGN_WIDTH, height: BASE_DESIGN_HEIGHT, backgroundColor: '#F9F5EF' }}>
                <StoryPage page={page} pageIndex={index} totalPages={total} fontSize={textFontSize} />
            </div>
        );
        // Give React and fonts/images time to settle
        await new Promise(r => setTimeout(r, 1200));

        const canvas = await html2canvas(container, {
            scale: SCALE_FACTOR, 
            width: BASE_DESIGN_WIDTH,
            height: BASE_DESIGN_HEIGHT,
            backgroundColor: '#F9F5EF',
            useCORS: true,
            logging: false,
            allowTaint: true
        });

        return new Promise((resolve) => {
            const img = new Image();
            img.onload = () => resolve(img);
            img.onerror = () => resolve(null);
            img.src = canvas.toDataURL('image/jpeg', 0.9);
        });
    } catch (err) {
        console.error("Error rendering page to image:", err);
        return null;
    }
};

export interface VideoConfig {
    fps: number;
    bitrate: number;
    textFontSize?: number;
}

export const generateStoryVideo = async (
    story: Story, 
    onProgress: (msg: string, percent: number) => void,
    config: VideoConfig = { fps: 30, bitrate: 12000000, textFontSize: 18 }
): Promise<void> => {
    const { fps, bitrate, textFontSize } = config;
    const mimeType = getSupportedMimeType();

    if (!mimeType) {
        alert("عذراً، متصفحك لا يدعم تسجيل الفيديو.");
        return;
    }

    onProgress("بدء تجهيز المحرك السحري...", 5);

    const container = document.createElement('div');
    container.style.position = 'fixed';
    container.style.left = '-9999px'; 
    container.style.top = '0';
    container.style.width = `${BASE_DESIGN_WIDTH}px`;
    container.style.height = `${BASE_DESIGN_HEIGHT}px`;
    document.body.appendChild(container);
    const root = createRoot(container);

    const canvas = document.createElement('canvas');
    canvas.width = VIDEO_WIDTH;
    canvas.height = VIDEO_HEIGHT;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
    const dest = audioContext.createMediaStreamDestination();
    setupBackgroundMusic(audioContext, dest);
    const turnSound = createTurnSoundBuffer(audioContext);

    const videoStream = canvas.captureStream(fps);
    const combinedStream = new MediaStream([
        ...videoStream.getVideoTracks(),
        ...dest.stream.getAudioTracks()
    ]);

    const recorder = new MediaRecorder(combinedStream, { 
        mimeType, 
        videoBitsPerSecond: bitrate 
    }); 

    const chunks: Blob[] = [];
    recorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunks.push(e.data);
    };

    return new Promise<void>(async (resolve, reject) => {
        recorder.onstop = () => {
            try {
                if (chunks.length === 0) {
                    throw new Error("No video chunks were recorded.");
                }
                const finalBlob = new Blob(chunks, { type: mimeType });
                const url = URL.createObjectURL(finalBlob);
                const extension = mimeType.includes('mp4') ? 'mp4' : 'webm';

                const a = document.createElement('a');
                a.href = url;
                const cleanTitle = story.title.replace(/[^\u0600-\u06FFa-zA-Z0-9]/g, '_');
                a.download = `Story_${cleanTitle}.${extension}`;
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);

                onProgress("تم الحفظ بنجاح!", 100);
                cleanup();
                resolve();
            } catch (err) {
                console.error("Recording stop error:", err);
                cleanup();
                reject(err);
            }
        };

        const cleanup = () => {
            audioContext.close();
            root.unmount();
            if (document.body.contains(container)) document.body.removeChild(container);
        };

        recorder.start();

        try {
            const pages = getStoryPages(story);
            let currentImg = await renderPageToImage(pages[0], 0, pages.length, container, root, textFontSize);

            for (let i = 0; i < pages.length; i++) {
                const isLast = i === pages.length - 1;
                const progressPercent = 10 + Math.floor((i / pages.length) * 80);
                onProgress(`جاري تسجيل المشهد ${i + 1}...`, progressPercent);

                if (!currentImg) {
                    // Skip or use a fallback empty screen if rendering failed
                    console.warn(`Page ${i} rendering failed, skipping...`);
                    continue;
                }

                const audioBuf = await loadAudio(pages[i].audioUrl || '', audioContext);
                const source = audioContext.createBufferSource();
                source.buffer = audioBuf;
                source.connect(dest);
                source.start();

                const durationMs = (audioBuf.duration + POST_AUDIO_DELAY_S) * 1000;
                const startTime = Date.now();

                // Animation loop for current page
                while (Date.now() - startTime < durationMs) {
                    const elapsed = Date.now() - startTime;
                    const progress = Math.min(elapsed / durationMs, 1.0);
                    const currentScale = 1 + (progress * ZOOM_FACTOR);

                    const dw = VIDEO_WIDTH * currentScale;
                    const dh = VIDEO_HEIGHT * currentScale;
                    const dx = (VIDEO_WIDTH - dw) / 2;
                    const dy = (VIDEO_HEIGHT - dh) / 2;

                    ctx.fillStyle = '#F9F5EF';
                    ctx.fillRect(0, 0, VIDEO_WIDTH, VIDEO_HEIGHT);
                    ctx.drawImage(currentImg, dx, dy, dw, dh);

                    await new Promise(r => requestAnimationFrame(r));
                }

                if (!isLast) {
                    const nextImg = await renderPageToImage(pages[i + 1], i + 1, pages.length, container, root, textFontSize);
                    if (nextImg) {
                        const turnSource = audioContext.createBufferSource();
                        turnSource.buffer = turnSound;
                        turnSource.connect(dest);
                        turnSource.start();

                        const transFrames = Math.ceil(TRANSITION_DURATION_S * fps);
                        for (let t = 0; t <= transFrames; t++) {
                            const p = t / transFrames;
                            const easeP = easeInOutCubic(p);

                            ctx.fillStyle = '#F9F5EF';
                            ctx.fillRect(0, 0, VIDEO_WIDTH, VIDEO_HEIGHT);

                            ctx.globalAlpha = 1 - easeP;
                            const oldScale = 1 + ZOOM_FACTOR + (easeP * 0.05); 
                            const oldW = VIDEO_WIDTH * oldScale;
                            const oldH = VIDEO_HEIGHT * oldScale;
                            const oldX = ((VIDEO_WIDTH - oldW) / 2) - (easeP * 400); 
                            const oldY = (VIDEO_HEIGHT - oldH) / 2;
                            ctx.drawImage(currentImg, oldX, oldY, oldW, oldH);

                            ctx.globalAlpha = easeP;
                            const nextScale = 1.1 - (easeP * 0.1); 
                            const nextW = VIDEO_WIDTH * nextScale;
                            const nextH = VIDEO_HEIGHT * nextScale;
                            const nextX = ((VIDEO_WIDTH - nextW) / 2) + ((1 - easeP) * 400); 
                            const nextY = (VIDEO_HEIGHT - nextH) / 2;
                            ctx.drawImage(nextImg, nextX, nextY, nextW, nextH);

                            ctx.globalAlpha = 1.0;
                            await new Promise(r => requestAnimationFrame(r));
                        }
                        currentImg = nextImg;
                    }
                }
            }

            onProgress("تم التسجيل! جاري معالجة الملف النهائي...", 95);
            recorder.stop();

        } catch (e) {
            console.error("Video generation loop error:", e);
            if (recorder.state !== 'inactive') recorder.stop();
            cleanup();
            reject(e);
        }
    });
};

import React, { useState } from 'react';
import { Story } from '../types';
import { BookOpenIcon } from './icons/BookOpenIcon';
import { DownloadIcon } from './icons/DownloadIcon';
import { VideoIcon } from './icons/VideoIcon';
import { generatePdf } from '../utils/pdfHelper';
import { BookReader } from './BookReader';
import { generateStoryVideo } from '../utils/videoGenerator';
import { getStoryPages } from '../utils/storyHelper';
import { StoryPage } from './StoryPage';

interface StoryPreviewProps {
    story: Story;
}

export const StoryPreview: React.FC<StoryPreviewProps> = ({ story }) => {
    const [isDownloadingPdf, setIsDownloadingPdf] = useState(false);
    const [isGeneratingVideo, setIsGeneratingVideo] = useState(false);
    const [videoProgress, setVideoProgress] = useState('');
    const [videoPercent, setVideoPercent] = useState(0);
    const [isBookMode, setIsBookMode] = useState(false);
    const [showVideoOptions, setShowVideoOptions] = useState(false);

    // Video Settings
    const [videoQuality, setVideoQuality] = useState(12000000); // 12Mbps is a good balance
    const [frameRate, setFrameRate] = useState(30);
    const [videoFontSize, setVideoFontSize] = useState(18); // Default 18px

    const handleDownloadPdf = async () => {
        setIsDownloadingPdf(true);
        try {
            await generatePdf(story.title);
        } catch (error) {
            console.error("Failed to generate PDF", error);
            alert("حدث خطأ أثناء إنشاء ملف PDF.");
        } finally {
            setIsDownloadingPdf(false);
        }
    };

    const handleDownloadVideo = async () => {
        if (isGeneratingVideo) return;
        setIsGeneratingVideo(true);
        setVideoPercent(0);
        setShowVideoOptions(false);
        try {
            await generateStoryVideo(story, (msg, percent) => {
                setVideoProgress(msg);
                setVideoPercent(percent);
            }, { 
                bitrate: videoQuality, 
                fps: frameRate,
                textFontSize: videoFontSize
            });
        } catch (error) {
            console.error("Video generation error:", error);
            alert("عذراً، حدث خطأ أثناء محاولة إنشاء الفيديو. قد يكون ذلك بسبب حجم القصة أو قيود المتصفح.");
        } finally {
            setIsGeneratingVideo(false);
            setVideoProgress('');
            setVideoPercent(0);
        }
    };

    const storyPages = getStoryPages(story);

    return (
        <div className="bg-white p-4 md:p-8 rounded-2xl shadow-lg border border-rose-100">
            {isBookMode && <BookReader story={story} onClose={() => setIsBookMode(false)} />}

            {isGeneratingVideo && (
                <div className="fixed inset-0 z-[60] bg-black/80 flex flex-col items-center justify-center text-white p-6 text-center backdrop-blur-sm">
                    <div className="relative mb-8">
                        <div className="animate-spin rounded-full h-24 w-24 border-t-4 border-b-4 border-rose-500"></div>
                        <div className="absolute inset-0 flex items-center justify-center font-bold text-lg text-rose-500">
                            {videoPercent}%
                        </div>
                    </div>

                    <h2 className="text-2xl font-bold mb-4">جاري إنشاء الفيديو السحري</h2>

                    <div className="w-full max-w-md bg-white/20 h-3 rounded-full overflow-hidden mb-6">
                        <div 
                            className="bg-gradient-to-r from-rose-500 to-purple-500 h-full transition-all duration-500 ease-out"
                            style={{ width: `${videoPercent}%` }}
                        ></div>
                    </div>

                    <p className="text-lg text-gray-200 min-h-[1.5em]">{videoProgress}</p>
                    <p className="text-sm text-gray-400 mt-8 max-w-sm leading-relaxed">
                        نحن نقوم بتحويل صفحات القصة إلى فيديو عالي الجودة ليناسب منصات التواصل الاجتماعي. 
                        يرجى عدم إغلاق هذه الصفحة؛ سيتم تحميل الملف تلقائياً فور الانتهاء.
                    </p>
                </div>
            )}

            <div className="flex flex-col sm:flex-row justify-between items-center mb-6 border-b-2 border-rose-200 pb-4">
                <div className="flex items-center gap-3 mb-4 sm:mb-0">
                    <BookOpenIcon className="h-8 w-8 text-rose-500" />
                    <h2 className="text-3xl font-bold text-rose-800 font-storybook">{story.title}</h2>
                </div>
                <div className="flex flex-wrap gap-2 w-full sm:w-auto justify-center items-center">
                    <button
                        onClick={() => setIsBookMode(true)}
                        className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-gradient-to-r from-purple-500 to-rose-500 text-white font-bold py-2 px-6 rounded-lg hover:from-purple-600 hover:to-rose-600 shadow-md transition duration-300 transform hover:scale-105"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="currentColor">
                            <path d="M8 5v14l11-7z" />
                        </svg>
                        <span>قراءة</span>
                    </button>

                    <div className="relative">
                         <button
                            onClick={() => setShowVideoOptions(!showVideoOptions)}
                            disabled={isGeneratingVideo}
                            className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-blue-500 text-white font-bold py-2 px-6 rounded-lg hover:bg-blue-600 transition duration-300 disabled:bg-blue-300"
                        >
                            <VideoIcon className="h-5 w-5" />
                            <span>فيديو</span>
                            <svg className={`w-4 h-4 transition-transform ${showVideoOptions ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                        </button>

                        {showVideoOptions && (
                            <div className="absolute top-full mt-2 left-0 right-0 sm:right-auto sm:w-72 bg-white border border-rose-100 shadow-2xl rounded-xl p-5 z-50 text-right animate-in fade-in slide-in-from-top-2">
                                <h4 className="font-bold text-rose-800 mb-3 border-b pb-2">إعدادات الفيديو</h4>

                                <div className="space-y-4">
                                    <div>
                                        <div className="flex justify-between items-center mb-2">
                                            <span className="text-[10px] bg-rose-100 text-rose-600 px-1.5 py-0.5 rounded font-bold">{videoFontSize}px</span>
                                            <label className="block text-xs font-bold text-gray-500">حجم نص القصة</label>
                                        </div>
                                        <input 
                                            type="range" 
                                            min="14" 
                                            max="40" 
                                            step="1"
                                            value={videoFontSize}
                                            onChange={(e) => setVideoFontSize(Number(e.target.value))}
                                            className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-rose-500"
                                        />
                                    </div>

                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 mb-2">جودة الفيديو (Bitrate)</label>
                                        <select 
                                            value={videoQuality}
                                            onChange={(e) => setVideoQuality(Number(e.target.value))}
                                            className="w-full text-sm border border-gray-200 rounded p-1.5 focus:ring-1 focus:ring-rose-400 outline-none"
                                        >
                                            <option value={20000000}>فائقة (20Mbps)</option>
                                            <option value={12000000}>عالية (12Mbps)</option>
                                            <option value={5000000}>متوسطة (5Mbps)</option>
                                            <option value={2000000}>منخفضة (2Mbps)</option>
                                        </select>
                                    </div>

                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 mb-2">معدل الإطارات (FPS)</label>
                                        <select 
                                            value={frameRate}
                                            onChange={(e) => setFrameRate(Number(e.target.value))}
                                            className="w-full text-sm border border-gray-200 rounded p-1.5 focus:ring-1 focus:ring-rose-400 outline-none"
                                        >
                                            <option value={60}>60 إطار (سلاسة تامة)</option>
                                            <option value={30}>30 إطار (قياسي)</option>
                                            <option value={24}>24 إطار (سينمائي)</option>
                                        </select>
                                    </div>

                                    <button 
                                        onClick={handleDownloadVideo}
                                        className="w-full bg-emerald-500 hover:bg-emerald-600 text-white font-bold py-2 rounded shadow-md transition-colors"
                                    >
                                        بدء الإنشاء الآن
                                    </button>
                                </div>
                            </div>
                        )}
                    </div>

                    <button
                        onClick={handleDownloadPdf}
                        disabled={isDownloadingPdf}
                        className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-green-500 text-white font-bold py-2 px-6 rounded-lg hover:bg-green-600 transition duration-300 disabled:bg-green-300"
                    >
                        <DownloadIcon className="h-5 w-5" />
                        {isDownloadingPdf ? 'جارٍ...' : 'PDF'}
                    </button>
                </div>
            </div>

            <div id="story-content" className="flex flex-col gap-10">
                {storyPages.map((page, idx) => (
                    <div 
                        key={idx} 
                        className="story-page shadow-2xl rounded-lg overflow-hidden w-full aspect-[1/1.414] max-w-[600px] mx-auto border-4 border-white"
                        style={{ height: 'auto' }}
                    >
                        <StoryPage 
                            page={page} 
                            pageIndex={idx} 
                            totalPages={storyPages.length} 
                        />
                    </div>
                ))}
            </div>

            <div className="mt-8 text-center text-gray-400 text-sm">
                تحقق من القصة أعلاه، يمكنك قراءتها بشكل تفاعلي أو تحميلها كملف PDF فاخر أو فيديو لـ تيك توك.
            </div>
        </div>
    );
};

