import React, { useState, useEffect, useRef } from 'react';
import { Story } from '../types';
import { getStoryPages, PageData } from '../utils/storyHelper';
import { StoryPage } from './StoryPage';

interface BookReaderProps {
    story: Story;
    onClose: () => void;
}

export const BookReader: React.FC<BookReaderProps> = ({ story, onClose }) => {
    const [pages, setPages] = useState<PageData[]>([]);
    const [currentPage, setCurrentPage] = useState(0);
    const [prevPage, setPrevPage] = useState<number | null>(null);
    const [direction, setDirection] = useState<'next' | 'prev'>('next');
    const [isPlaying, setIsPlaying] = useState(false);
    const [isAnimating, setIsAnimating] = useState(false);

    const audioRef = useRef<HTMLAudioElement | null>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const navigationTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
    const narrationStartTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    useEffect(() => {
        setPages(getStoryPages(story));
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        audioContextRef.current = new AudioContextClass();

        return () => {
            stopAllAudioAndTimers();
            if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
                audioContextRef.current.close();
            }
        };
    }, [story]);

    // وظيفة صارمة لإيقاف كل شيء متعلق بالصوت والوقت
    const stopAllAudioAndTimers = () => {
        // 1. إيقاف مشغل الصوت الأساسي وتصفيره
        if (audioRef.current) {
            audioRef.current.onended = null;
            audioRef.current.pause();
            audioRef.current.src = ""; // تفريغ المصدر لمنع التداخل
            audioRef.current.load();   // إجبار المتصفح على إعادة التهيئه
        }

        // 2. إلغاء مؤقت الانتقال التلقائي
        if (navigationTimerRef.current) {
            clearTimeout(navigationTimerRef.current);
            navigationTimerRef.current = null;
        }

        // 3. إلغاء مؤقت بدء القراءة الجديد (في حال كان قيد الانتظار)
        if (narrationStartTimerRef.current) {
            clearTimeout(narrationStartTimerRef.current);
            narrationStartTimerRef.current = null;
        }
    };

    const playSoundEffect = (type: 'click' | 'turn') => {
        const ctx = audioContextRef.current;
        if (!ctx) return;
        if (ctx.state === 'suspended') ctx.resume().catch(() => {});

        const t = ctx.currentTime;
        if (type === 'click') {
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.connect(gain); gain.connect(ctx.destination);
            osc.type = 'sine'; osc.frequency.setValueAtTime(800, t);
            osc.frequency.exponentialRampToValueAtTime(400, t + 0.1);
            gain.gain.setValueAtTime(0.05, t);
            gain.gain.exponentialRampToValueAtTime(0.001, t + 0.1);
            osc.start(t); osc.stop(t + 0.1);
        } else if (type === 'turn') {
            const bufferSize = ctx.sampleRate * 0.4;
            const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
            const data = buffer.getChannelData(0);
            for (let i = 0; i < bufferSize; i++) data[i] = (Math.random() * 2 - 1) * 0.2;
            const noise = ctx.createBufferSource();
            noise.buffer = buffer;
            const filter = ctx.createBiquadFilter();
            filter.type = 'lowpass'; filter.frequency.setValueAtTime(1000, t);
            filter.frequency.exponentialRampToValueAtTime(200, t + 0.3);
            const gain = ctx.createGain();
            gain.gain.setValueAtTime(0, t); gain.gain.linearRampToValueAtTime(0.1, t + 0.05);
            gain.gain.exponentialRampToValueAtTime(0.001, t + 0.35);
            noise.connect(filter); filter.connect(gain); gain.connect(ctx.destination);
            noise.start(t);
        }
    };

    // إدارة بدء القراءة الصوتية بعد استقرار الصفحة
    useEffect(() => {
        if (!isPlaying || isAnimating) return;

        const startPageNarration = () => {
            const currentPageData = pages[currentPage];
            if (!currentPageData) return;

            if (currentPageData.audioUrl && audioRef.current) {
                // التأكد من نظافة المشغل قبل البدء
                audioRef.current.pause();
                audioRef.current.src = currentPageData.audioUrl;

                audioRef.current.play().catch(e => {
                    console.warn("Autoplay blocked or audio failed", e);
                });

                audioRef.current.onended = () => {
                    // الانتقال التلقائي فقط إذا كنا في وضع التشغيل ولم نصل للنهاية
                    if (isPlaying && currentPage < pages.length - 1) {
                        navigationTimerRef.current = setTimeout(() => {
                            navigate('next');
                        }, 1200);
                    } else if (currentPage === pages.length - 1) {
                        setIsPlaying(false);
                    }
                };
            } else {
                // إذا لم يوجد صوت (مثل صفحة العنوان أحياناً)، انتظر قليلاً ثم انتقل
                navigationTimerRef.current = setTimeout(() => {
                    if (isPlaying && currentPage < pages.length - 1) navigate('next');
                    else setIsPlaying(false);
                }, 4000);
            }
        };

        // ننتظر حتى تكتمل حركة قلب الصفحة (800ms) قبل بدء القراءة
        narrationStartTimerRef.current = setTimeout(startPageNarration, 900);

        return () => {
            if (narrationStartTimerRef.current) clearTimeout(narrationStartTimerRef.current);
        };
    }, [currentPage, isPlaying, isAnimating, pages]);

    const navigate = (dir: 'next' | 'prev') => {
        if (isAnimating) return;

        const isNext = dir === 'next';
        if (isNext && currentPage >= pages.length - 1) return;
        if (!isNext && currentPage <= 0) return;

        // خطوة حاسمة: إيقاف كل شيء قبل تغيير الدولة (State)
        stopAllAudioAndTimers();

        playSoundEffect('turn');
        setIsAnimating(true);
        setPrevPage(currentPage);
        setDirection(dir);
        setCurrentPage(prev => isNext ? prev + 1 : prev - 1);

        // إعادة تفعيل التفاعل بعد اكتمال الحركة
        setTimeout(() => {
            setIsAnimating(false);
        }, 850);
    };

    const togglePlay = () => {
        playSoundEffect('click');
        if (!isPlaying) {
            setIsPlaying(true);
        } else {
            setIsPlaying(false);
            stopAllAudioAndTimers();
        }
    };

    const handleClose = () => {
        playSoundEffect('click');
        stopAllAudioAndTimers();
        onClose();
    };

    return (
        <div className="fixed inset-0 z-50 bg-black/95 flex flex-col items-center justify-center p-2 sm:p-4 overflow-hidden" dir="rtl">
            <audio ref={audioRef} className="hidden" />

            <div className="w-full max-w-lg flex justify-between items-center mb-4 text-white px-2 z-10">
                <button onClick={handleClose} className="hover:text-rose-400 transition p-2 bg-white/10 rounded-full">
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
                </button>
                <div className="flex gap-4">
                    <button onClick={togglePlay} className={`rounded-full p-3 transition shadow-lg ${isPlaying ? 'bg-rose-500 hover:bg-rose-600' : 'bg-emerald-500 hover:bg-emerald-600'}`}>
                        {isPlaying ? (
                            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="white"><rect x="6" y="4" width="4" height="16"></rect><rect x="14" y="4" width="4" height="16"></rect></svg>
                        ) : (
                            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="white"><polygon points="5 3 19 12 5 21 5 3"></polygon></svg>
                        )}
                    </button>
                </div>
            </div>

            <div className="relative w-full h-full max-h-[75vh] md:max-h-[85vh] aspect-[9/16] max-w-md perspective-2000 group">
                <div className="absolute right-[-4px] top-[2%] bottom-[2%] w-4 bg-rose-900/40 rounded-r-lg blur-[2px] z-0"></div>

                <div className="relative w-full h-full transform-style-3d">
                    {prevPage !== null && pages[prevPage] && (
                        <div className="absolute inset-0 bg-[#F9F5EF] rounded-xl shadow-inner overflow-hidden opacity-60">
                             <StoryPage 
                                page={pages[prevPage]} 
                                pageIndex={prevPage} 
                                totalPages={pages.length} 
                            />
                        </div>
                    )}

                    {pages[currentPage] && (
                        <div 
                            key={currentPage} 
                            className={`absolute inset-0 bg-white rounded-xl shadow-2xl overflow-hidden origin-right-spine transform-style-3d ${direction === 'next' ? 'animate-page-flip-next' : 'animate-page-flip-prev'}`}
                        >
                            <div className="absolute inset-0 z-50 pointer-events-none bg-gradient-to-l from-black/10 via-transparent to-transparent opacity-0 animate-page-shadow"></div>

                            <StoryPage 
                                page={pages[currentPage]} 
                                pageIndex={currentPage} 
                                totalPages={pages.length} 
                            />

                            {pages[currentPage].type === 'end' && (
                                <div className="absolute bottom-10 left-0 right-0 flex justify-center z-50">
                                     <button onClick={handleClose} className="px-8 py-3 bg-rose-600 text-white rounded-full font-bold hover:bg-rose-700 transition shadow-lg">
                                        إغلاق الكتاب
                                    </button>
                                </div>
                            )}
                        </div>
                    )}
                </div>
            </div>

             <div className="w-full max-w-lg flex justify-between items-center mt-6 px-4 z-10">
                 <button 
                    onClick={() => navigate('prev')} 
                    disabled={currentPage === 0 || isAnimating}
                    className="text-white bg-white/10 rounded-full p-2 disabled:opacity-20 hover:bg-white/20 transition-all active:scale-95"
                 >
                     <svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 18 9 12 15 6"></polyline></svg>
                 </button>

                 <div className="bg-white/10 px-4 py-1 rounded-full text-white/80 text-sm font-medium backdrop-blur-md border border-white/5">
                     {currentPage + 1} / {pages.length}
                 </div>

                 <button 
                    onClick={() => navigate('next')} 
                    disabled={currentPage === pages.length - 1 || isAnimating}
                    className="text-white bg-white/10 rounded-full p-2 disabled:opacity-20 hover:bg-white/20 transition-all active:scale-95"
                 >
                    <svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="9 18 15 12 9 6"></polyline></svg>
                 </button>
             </div>

             <style>{`
                .perspective-2000 { perspective: 2500px; }
                .transform-style-3d { transform-style: preserve-3d; }
                .origin-right-spine { transform-origin: right center; }

                @keyframes pageFlipNext {
                    0% { 
                        transform: rotateY(95deg); 
                        filter: brightness(0.6);
                    }
                    100% { 
                        transform: rotateY(0deg); 
                        filter: brightness(1);
                    }
                }

                @keyframes pageFlipPrev {
                    0% { 
                        transform: rotateY(-95deg); 
                        filter: brightness(0.6);
                        transform-origin: left center;
                    }
                    100% { 
                        transform: rotateY(0deg); 
                        filter: brightness(1);
                        transform-origin: left center;
                    }
                }

                .animate-page-flip-next {
                    animation: pageFlipNext 0.8s cubic-bezier(0.15, 0.45, 0.35, 1.0) forwards;
