import React from 'react';
import { createRoot } from 'react-dom/client';
import { Story } from '../types';
import { getStoryPages, PageData } from './storyHelper';
import { StoryPage } from '../components/StoryPage';

declare const html2canvas: any;

const VIDEO_WIDTH = 1080; 
const VIDEO_HEIGHT = 1920;
const TRANSITION_DURATION_S = 0.8; 
const POST_AUDIO_DELAY_S = 0.5;
const ZOOM_FACTOR = 0.12; 

const BASE_DESIGN_WIDTH = 600;
const SCALE_FACTOR = VIDEO_WIDTH / BASE_DESIGN_WIDTH; 
const BASE_DESIGN_HEIGHT = VIDEO_HEIGHT / SCALE_FACTOR;

const getSupportedMimeType = () => {
    const types = [
        'video/webm;codecs=vp9,opus',
        'video/webm;codecs=vp8,opus',
        'video/webm',
        'video/mp4;codecs=avc1',
        'video/mp4'
    ];

    for (const type of types) {
        if (MediaRecorder.isTypeSupported(type)) {
            return type;
        }
    }
    return '';
};

const easeInOutCubic = (t: number): number => t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;

const setupBackgroundMusic = (audioContext: AudioContext, destination: AudioNode) => {
    const mainGain = audioContext.createGain();
    mainGain.gain.value = 0.04; 
    mainGain.connect(destination);

    const playNote = (freq: number, startTime: number) => {
        try {
            const osc = audioContext.createOscillator();
            const g = audioContext.createGain();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(freq, startTime);
            g.gain.setValueAtTime(0, startTime);
            g.gain.linearRampToValueAtTime(0.15, startTime + 0.5);
            g.gain.exponentialRampToValueAtTime(0.001, startTime + 4);
            osc.connect(g);
            g.connect(mainGain);
            osc.start(startTime);
            osc.stop(startTime + 4);
        } catch (e) {}
    };

    const melody = [440, 554, 659, 880, 659, 554];
    let time = audioContext.currentTime;
    for (let i = 0; i < 100; i++) {
        melody.forEach((note, idx) => {
            playNote(note, time + (i * 6) + (idx * 1));
        });
    }
};

const createTurnSoundBuffer = (audioContext: AudioContext): AudioBuffer => {
    const duration = 0.5;
    const buffer = audioContext.createBuffer(1, Math.max(1, audioContext.sampleRate * duration), audioContext.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < buffer.length; i++) {
        data[i] = (Math.random() * 2 - 1) * 0.05 * (1 - i / buffer.length);
    }
    return buffer;
};

const loadAudio = async (url: string, audioContext: AudioContext): Promise<AudioBuffer> => {
    if (!url) return audioContext.createBuffer(1, audioContext.sampleRate, audioContext.sampleRate);
    try {
        const response = await fetch(url);
        if (!response.ok) throw new Error("Fetch failed");
        const arrayBuffer = await response.arrayBuffer();
        return await audioContext.decodeAudioData(arrayBuffer);
    } catch (e) {
        console.warn("Audio load failed for URL:", url, e);
        return audioContext.createBuffer(1, audioContext.sampleRate, audioContext.sampleRate);
    }
};

const renderPageToImage = async (
    page: PageData, 
    index: number, 
    total: number, 
    container: HTMLElement, 
    root: any,
    textFontSize?: number
): Promise<HTMLImageElement | null> => {
    try {
        root.render(
            <div style={{ width: BASE_DESIGN_WIDTH, height: BASE_DESIGN_HEIGHT, backgroundColor: '#F9F5EF' }}>
                <StoryPage page={page} pageIndex={index} totalPages={total} fontSize={textFontSize} />
            </div>
        );
        await new Promise(r => setTimeout(r, 1500));

        const canvas = await html2canvas(container, {
            scale: SCALE_FACTOR, 
            width: BASE_DESIGN_WIDTH,
            height: BASE_DESIGN_HEIGHT,
            backgroundColor: '#F9F5EF',
            useCORS: true,
            logging: false,
            allowTaint: true
        });

        return new Promise((resolve) => {
            const img = new Image();
            img.onload = () => resolve(img);
            img.onerror = () => resolve(null);
            img.src = canvas.toDataURL('image/jpeg', 0.9);
        });
    } catch (err) {
        console.error("Error rendering page to image:", err);
        return null;
    }
};

export interface VideoConfig {
    fps: number;
    bitrate: number;
    textFontSize?: number;
    signal?: AbortSignal;
    isPaused?: () => boolean;
}

export const generateStoryVideo = async (
    story: Story, 
    onProgress: (msg: string, percent: number) => void,
    config: VideoConfig = { fps: 30, bitrate: 12000000, textFontSize: 18 }
): Promise<void> => {
    const { fps, bitrate, textFontSize, signal, isPaused } = config;
    const mimeType = getSupportedMimeType();

    if (!mimeType) {
        alert("عذراً، متصفحك لا يدعم تسجيل الفيديو.");
        return;
    }

    const checkStatus = async () => {
        if (signal?.aborted) throw new Error("CANCELLED");
        while (isPaused?.()) {
            if (signal?.aborted) throw new Error("CANCELLED");
            await new Promise(r => setTimeout(r, 200));
        }
    };

    onProgress("بدء تجهيز المحرك السحري...", 5);

    const container = document.createElement('div');
    container.style.position = 'fixed';
    container.style.left = '-9999px'; 
    container.style.top = '0';
    container.style.width = `${BASE_DESIGN_WIDTH}px`;
    container.style.height = `${BASE_DESIGN_HEIGHT}px`;
    document.body.appendChild(container);
    const root = createRoot(container);

    const canvas = document.createElement('canvas');
    canvas.width = VIDEO_WIDTH;
    canvas.height = VIDEO_HEIGHT;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
    const dest = audioContext.createMediaStreamDestination();
    setupBackgroundMusic(audioContext, dest);
    const turnSound = createTurnSoundBuffer(audioContext);

    const videoStream = canvas.captureStream(fps);
    const combinedStream = new MediaStream([
        ...videoStream.getVideoTracks(),
        ...dest.stream.getAudioTracks()
    ]);

    const recorder = new MediaRecorder(combinedStream, { 
        mimeType, 
        videoBitsPerSecond: bitrate 
    }); 

    const chunks: Blob[] = [];
    recorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunks.push(e.data);
    };

    return new Promise<void>(async (resolve, reject) => {
        recorder.onstop = () => {
            try {
                if (chunks.length === 0) {
                    throw new Error("No video chunks were recorded.");
                }
                const finalBlob = new Blob(chunks, { type: mimeType });
                const url = URL.createObjectURL(finalBlob);
                const extension = mimeType.includes('mp4') ? 'mp4' : 'webm';

                const a = document.createElement('a');
                a.href = url;
                const cleanTitle = story.title.replace(/[^\u0600-\u06FFa-zA-Z0-9]/g, '_');
                a.download = `Story_${cleanTitle}.${extension}`;
                document.body.appendChild(a);
                a.click();
                setTimeout(() => {
                    document.body.removeChild(a);
                    URL.revokeObjectURL(url);
                }, 100);

                onProgress("تم الحفظ بنجاح!", 100);
                cleanup();
                resolve();
            } catch (err) {
                console.error("Recording stop error:", err);
                cleanup();
                reject(err);
            }
        };

        const cleanup = () => {
            if (audioContext.state !== 'closed') audioContext.close();
            root.unmount();
            if (document.body.contains(container)) document.body.removeChild(container);
        };

        recorder.start();

        try {
            const pages = getStoryPages(story);
            await checkStatus();
            let currentImg = await renderPageToImage(pages[0], 0, pages.length, container, root, textFontSize);

            for (let i = 0; i < pages.length; i++) {
                await checkStatus();
                const isLast = i === pages.length - 1;
                const progressPercent = 10 + Math.floor((i / pages.length) * 80);
                onProgress(`جاري تسجيل المشهد ${i + 1}...`, progressPercent);

                if (!currentImg) {
                    console.warn(`Page ${i} rendering failed, skipping...`);
                    continue;
                }

                const audioBuf = await loadAudio(pages[i].audioUrl || '', audioContext);
                const source = audioContext.createBufferSource();
                source.buffer = audioBuf;
                source.connect(dest);
                source.start();

                const durationMs = (audioBuf.duration + POST_AUDIO_DELAY_S) * 1000;
                let elapsedMs = 0;
                let lastTime = Date.now();

                while (elapsedMs < durationMs) {
                    await checkStatus();
                    const now = Date.now();
                    elapsedMs += (now - lastTime);
                    lastTime = now;

                    const progress = Math.min(elapsedMs / durationMs, 1.0);
                    const currentScale = 1 + (progress * ZOOM_FACTOR);

                    const dw = VIDEO_WIDTH * currentScale;
                    const dh = VIDEO_HEIGHT * currentScale;
                    const dx = (VIDEO_WIDTH - dw) / 2;
                    const dy = (VIDEO_HEIGHT - dh) / 2;

                    ctx.fillStyle = '#F9F5EF';
                    ctx.fillRect(0, 0, VIDEO_WIDTH, VIDEO_HEIGHT);
                    ctx.drawImage(currentImg, dx, dy, dw, dh);

                    await new Promise(r => requestAnimationFrame(r));
                }

                if (!isLast) {
                    await checkStatus();
                    const nextImg = await renderPageToImage(pages[i + 1], i + 1, pages.length, container, root, textFontSize);
                    if (nextImg) {
                        const turnSource = audioContext.createBufferSource();
                        turnSource.buffer = turnSound;
                        turnSource.connect(dest);
                        turnSource.start();

                        const transFrames = Math.ceil(TRANSITION_DURATION_S * fps);
                        for (let t = 0; t <= transFrames; t++) {
                            await checkStatus();
                            const p = t / transFrames;
                            const easeP = easeInOutCubic(p);

                            ctx.fillStyle = '#F9F5EF';
                            ctx.fillRect(0, 0, VIDEO_WIDTH, VIDEO_HEIGHT);

                            ctx.globalAlpha = 1 - easeP;
                            const oldScale = 1 + ZOOM_FACTOR + (easeP * 0.05); 
                            const oldW = VIDEO_WIDTH * oldScale;
                            const oldH = VIDEO_HEIGHT * oldScale;
                            const oldX = ((VIDEO_WIDTH - oldW) / 2) - (easeP * 400); 
                            const oldY = (VIDEO_HEIGHT - oldH) / 2;
                            ctx.drawImage(currentImg, oldX, oldY, oldW, oldH);

                            ctx.globalAlpha = easeP;
                            const nextScale = 1.1 - (easeP * 0.1); 
                            const nextW = VIDEO_WIDTH * nextScale;
                            const nextH = VIDEO_HEIGHT * nextScale;
                            const nextX = ((VIDEO_WIDTH - nextW) / 2) + ((1 - easeP) * 400); 
                            const nextY = (VIDEO_HEIGHT - nextH) / 2;
                            ctx.drawImage(nextImg, nextX, nextY, nextW, nextH);

                            ctx.globalAlpha = 1.0;
                            await new Promise(r => requestAnimationFrame(r));
                        }
                        currentImg = nextImg;
                    }
                }
            }

            onProgress("تم التسجيل! جاري معالجة الملف النهائي...", 95);
            recorder.stop();

        } catch (e: any) {
            console.error("Video generation loop stopped:", e);
            if (recorder.state !== 'inactive') {
                recorder.stop();
            }
            cleanup();
            if (e.message === "CANCELLED") {
                onProgress("تم إلغاء العملية", 0);
                resolve();
            } else {
                reject(e);
            }
        }
    });
};

import React, { useState, useRef } from 'react';
import { Story } from '../types';
import { BookOpenIcon } from './icons/BookOpenIcon';
import { DownloadIcon } from './icons/DownloadIcon';
import { VideoIcon } from './icons/VideoIcon';
import { generatePdf } from '../utils/pdfHelper';
import { BookReader } from './BookReader';
import { generateStoryVideo } from '../utils/videoGenerator';
import { getStoryPages } from '../utils/storyHelper';
import { StoryPage } from './StoryPage';

interface StoryPreviewProps {
    story: Story;
}

export const StoryPreview: React.FC<StoryPreviewProps> = ({ story }) => {
    const [isDownloadingPdf, setIsDownloadingPdf] = useState(false);
    const [isGeneratingVideo, setIsGeneratingVideo] = useState(false);
    const [isVideoPaused, setIsVideoPaused] = useState(false);
    const [videoProgress, setVideoProgress] = useState('');
    const [videoPercent, setVideoPercent] = useState(0);
    const [isBookMode, setIsBookMode] = useState(false);
    const [showVideoOptions, setShowVideoOptions] = useState(false);

    // Video Settings
    const [videoQuality, setVideoQuality] = useState(12000000); // 12Mbps is a good balance
    const [frameRate, setFrameRate] = useState(30);
    const [videoFontSize, setVideoFontSize] = useState(18); // Default 18px

    const abortControllerRef = useRef<AbortController | null>(null);
    const isVideoPausedRef = useRef(false);

    const handleDownloadPdf = async () => {
        setIsDownloadingPdf(true);
        try {
            await generatePdf(story.title);
        } catch (error) {
            console.error("Failed to generate PDF", error);
            alert("حدث خطأ أثناء إنشاء ملف PDF.");
        } finally {
            setIsDownloadingPdf(false);
        }
    };

    const handleDownloadVideo = async () => {
        if (isGeneratingVideo) return;

        setIsGeneratingVideo(true);
        setIsVideoPaused(false);
        isVideoPausedRef.current = false;
        setVideoPercent(0);
        setShowVideoOptions(false);

        abortControllerRef.current = new AbortController();

        try {
            await generateStoryVideo(story, (msg, percent) => {
                setVideoProgress(msg);
                setVideoPercent(percent);
            }, { 
                bitrate: videoQuality, 
                fps: frameRate,
                textFontSize: videoFontSize,
                signal: abortControllerRef.current.signal,
                isPaused: () => isVideoPausedRef.current
            });
        } catch (error) {
            console.error("Video generation error:", error);
            alert("عذراً، حدث خطأ أثناء محاولة إنشاء الفيديو. قد يكون ذلك بسبب حجم القصة أو قيود المتصفح.");
        } finally {
            setIsGeneratingVideo(false);
            setVideoProgress('');
            setVideoPercent(0);
            abortControllerRef.current = null;
        }
    };

    const toggleVideoPause = () => {
        const nextState = !isVideoPaused;
        setIsVideoPaused(nextState);
        isVideoPausedRef.current = nextState;
    };

    const cancelVideoGeneration = () => {
        if (confirm('هل أنت متأكد من إلغاء عملية إنشاء الفيديو؟')) {
            abortControllerRef.current?.abort();
        }
    };

    const storyPages = getStoryPages(story);

    return (
        <div className="bg-white p-4 md:p-8 rounded-2xl shadow-lg border border-rose-100">
            {isBookMode && <BookReader story={story} onClose={() => setIsBookMode(false)} />}

            {isGeneratingVideo && (
                <div className="fixed inset-0 z-[60] bg-black/85 flex flex-col items-center justify-center text-white p-6 text-center backdrop-blur-md">
                    <div className="relative mb-8">
                        <div className={`animate-spin rounded-full h-24 w-24 border-t-4 border-b-4 border-rose-500 ${isVideoPaused ? 'paused-animation' : ''}`}></div>
                        <div className="absolute inset-0 flex items-center justify-center font-bold text-lg text-rose-500">
                            {videoPercent}%
                        </div>
                    </div>

                    <h2 className="text-2xl font-bold mb-2">جاري إنشاء الفيديو السحري</h2>
                    {isVideoPaused && <div className="text-amber-400 font-bold mb-4 animate-pulse">العملية متوقفة مؤقتاً</div>}

                    <div className="w-full max-w-md bg-white/20 h-3 rounded-full overflow-hidden mb-6">
                        <div 
                            className="bg-gradient-to-r from-rose-500 to-purple-500 h-full transition-all duration-500 ease-out"
                            style={{ width: `${videoPercent}%` }}
                        ></div>
                    </div>

                    <p className="text-lg text-gray-200 min-h-[1.5em] mb-10">{videoProgress}</p>

                    <div className="flex gap-4 mb-8">
                        <button 
                            onClick={toggleVideoPause}
                            className="px-6 py-2 bg-white/10 hover:bg-white/20 rounded-full border border-white/30 transition flex items-center gap-2"
                        >
                            {isVideoPaused ? (
                                <>
                                    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><polygon points="5 3 19 12 5 21 5 3"></polygon></svg>
                                    <span>استئناف</span>
                                </>
                            ) : (
                                <>
                                    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="4" width="4" height="16"></rect><rect x="14" y="4" width="4" height="16"></rect></svg>
                                    <span>إيقاف مؤقت</span>
                                </>
                            )}
                        </button>
                        <button 
                            onClick={cancelVideoGeneration}
                            className="px-6 py-2 bg-red-500/20 hover:bg-red-500/40 text-red-300 rounded-full border border-red-500/50 transition flex items-center gap-2"
                        >
                            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
                            <span>إلغاء</span>
                        </button>
                    </div>

                    <p className="text-sm text-gray-400 max-w-sm leading-relaxed">
                        نحن نقوم بتحويل صفحات القصة إلى فيديو عالي الجودة. 
                        يمكنك إيقاف العملية مؤقتاً إذا لزم الأمر أو إلغاؤها.
                    </p>

                    <style>{`
                        .paused-animation { animation-play-state: paused; }
                    `}</style>
                </div>
            )}

            <div className="flex flex-col sm:flex-row justify-between items-center mb-6 border-b-2 border-rose-200 pb-4">
                <div className="flex items-center gap-3 mb-4 sm:mb-0">
                    <BookOpenIcon className="h-8 w-8 text-rose-500" />
                    <h2 className="text-3xl font-bold text-rose-800 font-storybook">{story.title}</h2>
                </div>
                <div className="flex flex-wrap gap-2 w-full sm:w-auto justify-center items-center">
                    <button
                        onClick={() => setIsBookMode(true)}
                        className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-gradient-to-r from-purple-500 to-rose-500 text-white font-bold py-2 px-6 rounded-lg hover:from-purple-600 hover:to-rose-600 shadow-md transition duration-300 transform hover:scale-105"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="currentColor">
                            <path d="M8 5v14l11-7z" />
                        </svg>
                        <span>قراءة</span>
                    </button>

                    <div className="relative">
                         <button
                            onClick={() => setShowVideoOptions(!showVideoOptions)}
                            disabled={isGeneratingVideo}
                            className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-blue-500 text-white font-bold py-2 px-6 rounded-lg hover:bg-blue-600 transition duration-300 disabled:bg-blue-300"
                        >
                            <VideoIcon className="h-5 w-5" />
                            <span>فيديو</span>
                            <svg className={`w-4 h-4 transition-transform ${showVideoOptions ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                        </button>

                        {showVideoOptions && (
                            <div className="absolute top-full mt-2 left-0 right-0 sm:right-auto sm:w-72 bg-white border border-rose-100 shadow-2xl rounded-xl p-5 z-50 text-right animate-in fade-in slide-in-from-top-2">
                                <h4 className="font-bold text-rose-800 mb-3 border-b pb-2">إعدادات الفيديو</h4>

                                <div className="space-y-4">
                                    <div>
                                        <div className="flex justify-between items-center mb-2">
                                            <span className="text-[10px] bg-rose-100 text-rose-600 px-1.5 py-0.5 rounded font-bold">{videoFontSize}px</span>
                                            <label className="block text-xs font-bold text-gray-500">حجم نص القصة</label>
                                        </div>
                                        <input 
                                            type="range" 
                                            min="14" 
                                            max="40" 
                                            step="1"
                                            value={videoFontSize}
                                            onChange={(e) => setVideoFontSize(Number(e.target.value))}
                                            className="w-full h-1.5 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-rose-500"
                                        />
                                    </div>

                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 mb-2">جودة الفيديو (Bitrate)</label>
                                        <select 
                                            value={videoQuality}
                                            onChange={(e) => setVideoQuality(Number(e.target.value))}
                                            className="w-full text-sm border border-gray-200 rounded p-1.5 focus:ring-1 focus:ring-rose-400 outline-none"
                                        >
                                            <option value={20000000}>فائقة (20Mbps)</option>
                                            <option value={12000000}>عالية (12Mbps)</option>
                                            <option value={5000000}>متوسطة (5Mbps)</option>
                                            <option value={2000000}>منخفضة (2Mbps)</option>
                                        </select>
                                    </div>

                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 mb-2">معدل الإطارات (FPS)</label>
                                        <select 
                                            value={frameRate}
                                            onChange={(e) => setFrameRate(Number(e.target.value))}
                                            className="w-full text-sm border border-gray-200 rounded p-1.5 focus:ring-1 focus:ring-rose-400 outline-none"
                                        >
                                            <option value={60}>60 إطار (سلاسة تامة)</option>
                                            <option value={30}>30 إطار (قياسي)</option>
                                            <option value={24}>24 إطار (سينمائي)</option>
                                        </select>
                                    </div>

                                    <button 
                                        onClick={handleDownloadVideo}
                                        className="w-full bg-emerald-500 hover:bg-emerald-600 text-white font-bold py-2 rounded shadow-md transition-colors"
                                    >
                                        بدء الإنشاء الآن
                                    </button>
                                </div>
                            </div>
                        )}
                    </div>

                    <button
                        onClick={handleDownloadPdf}
                        disabled={isDownloadingPdf}
                        className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-green-500 text-white font-bold py-2 px-6 rounded-lg hover:bg-green-600 transition duration-300 disabled:bg-green-300"
                    >
                        <DownloadIcon className="h-5 w-5" />
                        {isDownloadingPdf ? 'جارٍ...' : 'PDF'}
                    </button>
                </div>
            </div>

            <div id="story-content" className="flex flex-col gap-10">
                {storyPages.map((page, idx) => (
                    <div 
                        key={idx} 
                        className="story-page shadow-2xl rounded-lg overflow-hidden w-full aspect-[1/1.414] max-w-[600px] mx-auto border-4 border-white"
                        style={{ height: 'auto' }}
                    >
                        <StoryPage 
                            page={page} 
                            pageIndex={idx} 
                            totalPages={storyPages.length} 
                        />
                    </div>
                ))}
            </div>

            <div className="mt-8 text-center text-gray-400 text-sm">
                تحقق من القصة أعلاه، يمكنك قراءتها بشكل تفاعلي أو تحميلها كملف PDF فاخر أو فيديو لـ تيك توك.
            </div>
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { Story } from '../types';
import { getStoryPages, PageData } from '../utils/storyHelper';
import { StoryPage } from './StoryPage';

interface BookReaderProps {
    story: Story;
    onClose: () => void;
}

export const BookReader: React.FC<BookReaderProps> = ({ story, onClose }) => {
    const [pages, setPages] = useState<PageData[]>([]);
    const [currentPage, setCurrentPage] = useState(0);
    const [prevPage, setPrevPage] = useState<number | null>(null);
    const [direction, setDirection] = useState<'next' | 'prev'>('next');
    const [isPlaying, setIsPlaying] = useState(false);
    const [isAnimating, setIsAnimating] = useState(false);

    const audioRef = useRef<HTMLAudioElement | null>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const nextStepTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    // تهيئة الصفحات ونظام المؤثرات الصوتية
    useEffect(() => {
        setPages(getStoryPages(story));
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        audioContextRef.current = new AudioContextClass();

        return () => {
            stopEverything();
            if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
                audioContextRef.current.close();
            }
        };
    }, [story]);

    const stopEverything = () => {
        if (audioRef.current) {
            audioRef.current.pause();
            audioRef.current.onended = null;
            audioRef.current.src = "";
        }
        if (nextStepTimerRef.current) {
            clearTimeout(nextStepTimerRef.current);
            nextStepTimerRef.current = null;
        }
    };

    const playSoundEffect = (type: 'turn' | 'click') => {
        const ctx = audioContextRef.current;
        if (!ctx || ctx.state === 'closed') return;
        if (ctx.state === 'suspended') ctx.resume();

        const t = ctx.currentTime;
        if (type === 'turn') {
            const bufferSize = ctx.sampleRate * 0.3;
            const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
            const data = buffer.getChannelData(0);
            for (let i = 0; i < bufferSize; i++) data[i] = (Math.random() * 2 - 1) * 0.1 * (1 - i/bufferSize);
            const noise = ctx.createBufferSource();
            noise.buffer = buffer;
            const filter = ctx.createBiquadFilter();
            filter.type = 'lowpass';
            filter.frequency.setValueAtTime(1000, t);
            filter.frequency.exponentialRampToValueAtTime(200, t + 0.2);
            noise.connect(filter);
            filter.connect(ctx.destination);
            noise.start(t);
        }
    };

    // إدارة القراءة التلقائية: تبدأ فور تغير الصفحة
    useEffect(() => {
        if (!isPlaying || pages.length === 0) return;

        const currentPageData = pages[currentPage];
        const audio = audioRef.current;

        if (audio && currentPageData?.audioUrl) {
            // التحضير والتشغيل الفوري
            audio.pause();
            audio.src = currentPageData.audioUrl;
            audio.load();

            const playPromise = audio.play();
            if (playPromise !== undefined) {
                playPromise.catch(error => console.warn("Autoplay blocked:", error));
            }

            audio.onended = () => {
                if (isPlaying && currentPage < pages.length - 1) {
                    // فجوة صغيرة جداً بين الصفحات لإضفاء طابع طبيعي (200ms)
                    nextStepTimerRef.current = setTimeout(() => {
                        navigate('next');
                    }, 200);
                } else if (currentPage === pages.length - 1) {
                    setIsPlaying(false);
                }
            };
        } else if (isPlaying) {
            // إذا لم يوجد صوت، انتظر 4 ثواني ثم انتقل تلقائياً
            nextStepTimerRef.current = setTimeout(() => {
                if (currentPage < pages.length - 1) navigate('next');
                else setIsPlaying(false);
            }, 4000);
        }

        return () => {
            if (audio) audio.onended = null;
        };
    }, [currentPage, isPlaying, pages]);

    const navigate = (dir: 'next' | 'prev') => {
        if (isAnimating) return;

        const isNext = dir === 'next';
        if (isNext && currentPage >= pages.length - 1) return;
        if (!isNext && currentPage <= 0) return;

        // تنظيف القراءة الحالية قبل الانتقال
        if (nextStepTimerRef.current) clearTimeout(nextStepTimerRef.current);

        playSoundEffect('turn');
        setIsAnimating(true);
        setPrevPage(currentPage);
        setDirection(dir);
        setCurrentPage(prev => isNext ? prev + 1 : prev - 1);

        // مدة حركة قلب الصفحة
        setTimeout(() => {
            setIsAnimating(false);
        }, 800);
    };

    const togglePlay = () => {
        if (!isPlaying) {
            setIsPlaying(true);
        } else {
            setIsPlaying(false);
            stopEverything();
        }
    };

    const handleClose = () => {
        stopEverything();
        onClose();
    };

    return (
        <div className="fixed inset-0 z-50 bg-black/95 flex flex-col items-center justify-center p-2 sm:p-4 overflow-hidden" dir="rtl">
            <audio ref={audioRef} preload="auto" />

            {/* أزرار التحكم العلوية */}
            <div className="w-full max-w-lg flex justify-between items-center mb-4 text-white px-2 z-10">
                <button onClick={handleClose} className="hover:text-rose-400 transition p-2 bg-white/10 rounded-full">
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
                </button>

                <div className="flex items-center gap-4">
                    <span className="text-sm font-bold bg-white/10 px-3 py-1 rounded-full border border-white/5">
                        {currentPage + 1} / {pages.length}
                    </span>
                    <button onClick={togglePlay} className={`rounded-full p-3 transition shadow-lg ${isPlaying ? 'bg-rose-500 hover:bg-rose-600 scale-110' : 'bg-emerald-500 hover:bg-emerald-600'}`}>
                        {isPlaying ? (
                            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="white"><rect x="6" y="4" width="4" height="16"></rect><rect x="14" y="4" width="4" height="16"></rect></svg>
                        ) : (
                            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="white"><polygon points="5 3 19 12 5 21 5 3"></polygon></svg>
                        )}
                    </button>
                </div>
            </div>

            {/* عرض الكتاب */}
            <div className="relative w-full h-full max-h-[75vh] md:max-h-[85vh] aspect-[9/16] max-w-md perspective-2000">
                {/* تأثير العمود الفقري */}
                <div className="absolute right-[-4px] top-[2%] bottom-[2%] w-4 bg-black/20 rounded-r-lg blur-[1px] z-0"></div>

                <div className="relative w-full h-full transform-style-3d">
                    {/* الصفحة السابقة لضمان عدم ظهور فراغ أثناء الحركة */}
                    {prevPage !== null && (
                        <div className="absolute inset-0 bg-[#F9F5EF] rounded-xl shadow-inner overflow-hidden opacity-40">
                             <StoryPage 
                                page={pages[prevPage]} 
                                pageIndex={prevPage} 
                                totalPages={pages.length} 
                            />
                        </div>
                    )}

                    {/* الصفحة الحالية مع الأنيميشن */}
                    {pages[currentPage] && (
                        <div 
                            key={currentPage} 
                            className={`absolute inset-0 bg-white rounded-xl shadow-2xl overflow-hidden origin-right-spine transform-style-3d ${direction === 'next' ? 'animate-page-flip-next' : 'animate-page-flip-prev'}`}
                        >
                            <StoryPage 
                                page={pages[currentPage]} 
                                pageIndex={currentPage} 
                                totalPages={pages.length} 
                            />

                            {/* زر النهاية */}
                            {pages[currentPage].type === 'end' && (
                                <div className="absolute bottom-12 left-0 right-0 flex justify-center z-50">
                                     <button onClick={handleClose} className="px-10 py-4 bg-rose-600 text-white rounded-full font-bold hover:bg-rose-700 transition shadow-xl animate-bounce">
                                        تمت القصة بنجاح ✨
                                    </button>
                                </div>
                            )}
                        </div>
                    )}
                </div>
            </div>

            {/* أزرار التنقل اليدوي السفلي */}
            <div className="w-full max-w-lg flex justify-between items-center mt-6 px-4 z-10">
                 <button 
                    onClick={() => navigate('prev')} 
                    disabled={currentPage === 0 || isAnimating}
                    className="text-white bg-white/10 rounded-full p-3 disabled:opacity-10 hover:bg-white/20 transition-all active:scale-90"
                 >
                     <svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 18 9 12 15 6"></polyline></svg>
                 </button>

                 <div className="text-white/40 text-xs font-bold tracking-widest uppercase">
                    Interactive Mode
                 </div>

                 <button 
                    onClick={() => navigate('next')} 
                    disabled={currentPage === pages.length - 1 || isAnimating}
                    className="text-white bg-white/10 rounded-full p-3 disabled:opacity-10 hover:bg-white/20 transition-all active:scale-90"
                 >
                    <svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="9 18 15 12 9 6"></polyline></svg>
                 </button>
