import React, { useState, useEffect, useRef } from 'react';
import { Story } from '../types';
import { getStoryPages, PageData } from '../utils/storyHelper';
import { StoryPage } from './StoryPage';

interface BookReaderProps {
    story: Story;
    onClose: () => void;
}

export const BookReader: React.FC<BookReaderProps> = ({ story, onClose }) => {
    const [pages, setPages] = useState<PageData[]>([]);
    const [currentPage, setCurrentPage] = useState(0);
    const [prevPage, setPrevPage] = useState<number | null>(null);
    const [direction, setDirection] = useState<'next' | 'prev'>('next');
    const [isPlaying, setIsPlaying] = useState(false);
    const [isAnimating, setIsAnimating] = useState(false);

    const audioRef = useRef<HTMLAudioElement | null>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const nextStepTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    // معرّف فريد لمنع تداخل العمليات المتأخرة
    const activeExecutionId = useRef<number>(0);

    useEffect(() => {
        setPages(getStoryPages(story));
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        audioContextRef.current = new AudioContextClass();

        return () => {
            stopEverything();
            if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
                audioContextRef.current.close();
            }
        };
    }, [story]);

    const stopEverything = () => {
        activeExecutionId.current++; // زيادة المعرّف لإلغاء أي callbacks سابقة
        if (audioRef.current) {
            audioRef.current.onended = null;
            audioRef.current.pause();
            audioRef.current.src = "";
            audioRef.current.load();
        }
        if (nextStepTimerRef.current) {
            clearTimeout(nextStepTimerRef.current);
            nextStepTimerRef.current = null;
        }
    };

    const playSoundEffect = (type: 'turn' | 'click') => {
        const ctx = audioContextRef.current;
        if (!ctx || ctx.state === 'closed') return;
        if (ctx.state === 'suspended') ctx.resume();

        const t = ctx.currentTime;
        if (type === 'turn') {
            const bufferSize = ctx.sampleRate * 0.3;
            const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
            const data = buffer.getChannelData(0);
            for (let i = 0; i < bufferSize; i++) data[i] = (Math.random() * 2 - 1) * 0.08 * (1 - i/bufferSize);
            const noise = ctx.createBufferSource();
            noise.buffer = buffer;
            const filter = ctx.createBiquadFilter();
            filter.type = 'lowpass';
            filter.frequency.setValueAtTime(800, t);
            noise.connect(filter);
            filter.connect(ctx.destination);
            noise.start(t);
        }
    };

    // إدارة القراءة التلقائية الصارمة
    useEffect(() => {
        if (!isPlaying || pages.length === 0) return;

        const currentId = ++activeExecutionId.current;
        const currentPageData = pages[currentPage];
        const audio = audioRef.current;

        if (audio && currentPageData?.audioUrl) {
            // إيقاف أي صوت سابق فوراً
            audio.onended = null;
            audio.pause();
            audio.src = currentPageData.audioUrl;
            audio.load();

            audio.play().catch(error => console.warn("Audio play blocked:", error));

            audio.onended = () => {
                // التأكد أننا ما زلنا في نفس "سياق التنفيذ" ولم نغير الصفحة يدوياً
                if (currentId === activeExecutionId.current && isPlaying && currentPage < pages.length - 1) {
                    navigate('next');
                } else if (currentPage === pages.length - 1) {
                    setIsPlaying(false);
                }
            };
        } else if (isPlaying) {
            // مؤقت احتياطي للصفحات التي لا تحتوي على صوت
            nextStepTimerRef.current = setTimeout(() => {
                if (currentId === activeExecutionId.current) {
                    if (currentPage < pages.length - 1) navigate('next');
                    else setIsPlaying(false);
                }
            }, 4000);
        }

        return () => {
            if (audio) audio.onended = null;
        };
    }, [currentPage, isPlaying, pages]);

    const navigate = (dir: 'next' | 'prev') => {
        if (isAnimating) return;

        const isNext = dir === 'next';
        if (isNext && currentPage >= pages.length - 1) return;
        if (!isNext && currentPage <= 0) return;

        // خطوة حاسمة: إيقاف كل شيء قبل تغيير الصفحة
        stopEverything();

        playSoundEffect('turn');
        setIsAnimating(true);
        setPrevPage(currentPage);
        setDirection(dir);
        setCurrentPage(prev => isNext ? prev + 1 : prev - 1);

        setTimeout(() => {
            setIsAnimating(false);
        }, 750);
    };

    const togglePlay = () => {
        if (!isPlaying) {
            setIsPlaying(true);
        } else {
            setIsPlaying(false);
            stopEverything();
        }
    };

    const handleClose = () => {
        stopEverything();
        onClose();
    };

    return (
        <div className="fixed inset-0 z-50 bg-black/95 flex flex-col items-center justify-center p-2 sm:p-4 overflow-hidden" dir="rtl">
            <audio ref={audioRef} preload="auto" />

            <div className="w-full max-w-lg flex justify-between items-center mb-4 text-white px-2 z-10">
                <button onClick={handleClose} className="hover:text-rose-400 transition p-2 bg-white/10 rounded-full">
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
                </button>

                <div className="flex items-center gap-4">
                    <span className="text-sm font-bold bg-white/10 px-3 py-1 rounded-full border border-white/5">
                        {currentPage + 1} / {pages.length}
                    </span>
                    <button onClick={togglePlay} className={`rounded-full p-3 transition shadow-lg ${isPlaying ? 'bg-rose-500 hover:bg-rose-600 scale-110' : 'bg-emerald-500 hover:bg-emerald-600'}`}>
                        {isPlaying ? (
                            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="white"><rect x="6" y="4" width="4" height="16"></rect><rect x="14" y="4" width="4" height="16"></rect></svg>
                        ) : (
                            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="white"><polygon points="5 3 19 12 5 21 5 3"></polygon></svg>
                        )}
                    </button>
                </div>
            </div>

            <div className="relative w-full h-full max-h-[75vh] md:max-h-[85vh] aspect-[9/16] max-w-md perspective-2000">
                <div className="absolute right-[-4px] top-[2%] bottom-[2%] w-4 bg-black/20 rounded-r-lg blur-[1px] z-0"></div>

                <div className="relative w-full h-full transform-style-3d">
                    {prevPage !== null && (
                        <div className="absolute inset-0 bg-[#F9F5EF] rounded-xl shadow-inner overflow-hidden opacity-40">
                             <StoryPage page={pages[prevPage]} pageIndex={prevPage} totalPages={pages.length} />
                        </div>
                    )}

                    {pages[currentPage] && (
                        <div 
                            key={currentPage} 
                            className={`absolute inset-0 bg-white rounded-xl shadow-2xl overflow-hidden origin-right-spine transform-style-3d ${direction === 'next' ? 'animate-page-flip-next' : 'animate-page-flip-prev'}`}
                        >
                            <StoryPage page={pages[currentPage]} pageIndex={currentPage} totalPages={pages.length} />

                            {pages[currentPage].type === 'end' && (
                                <div className="absolute bottom-12 left-0 right-0 flex justify-center z-50">
                                     <button onClick={handleClose} className="px-10 py-4 bg-rose-600 text-white rounded-full font-bold hover:bg-rose-700 transition shadow-xl animate-bounce">
                                        تمت القصة بنجاح ✨
                                    </button>
                                </div>
                            )}
                        </div>
                    )}
                </div>
            </div>

            <div className="w-full max-w-lg flex justify-between items-center mt-6 px-4 z-10">
                 <button 
                    onClick={() => navigate('prev')} 
                    disabled={currentPage === 0 || isAnimating}
                    className="text-white bg-white/10 rounded-full p-3 disabled:opacity-10 hover:bg-white/20 transition-all active:scale-90"
                 >
                     <svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 18 9 12 15 6"></polyline></svg>
                 </button>

                 <div className="text-white/40 text-[10px] font-bold tracking-[0.2em] uppercase">
                    Continuous Narrative
                 </div>

                 <button 
                    onClick={() => navigate('next')} 
                    disabled={currentPage === pages.length - 1 || isAnimating}
                    className="text-white bg-white/10 rounded-full p-3 disabled:opacity-10 hover:bg-white/20 transition-all active:scale-90"
                 >
                    <svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="9 18 15 12 9 6"></polyline></svg>
                 </button>
             </div>

             <style>{`
                .perspective-2000 { perspective: 2500px; }
                .transform-style-3d { transform-style: preserve-3d; }
                .origin-right-spine { transform-origin: right center; }

                @keyframes pageFlipNext {
                    0% { transform: rotateY(90deg); filter: brightness(0.6); }
                    100% { transform: rotateY(0deg); filter: brightness(1); }
                }

                @keyframes pageFlipPrev {
                    0% { transform: rotateY(-90deg); filter: brightness(0.6); transform-origin: left center; }
                    100% { transform: rotateY(0deg); filter: brightness(1); transform-origin: left center; }
                }

                .animate-page-flip-next {
                    animation: pageFlipNext 0.75s cubic-bezier(0.1, 0.5, 0.2, 1) forwards;
                    backface-visibility: hidden;
                }

                .animate-page-flip-prev {
                    animation: pageFlipPrev 0.75s cubic-bezier(0.1, 0.5, 0.2, 1) forwards;
                    backface-visibility: hidden;
                }
             `}</style>
        </div>
    );
};

import React from 'react';
import { createRoot } from 'react-dom/client';
import { Story } from '../types';
import { getStoryPages, PageData } from './storyHelper';
import { StoryPage } from '../components/StoryPage';

declare const html2canvas: any;

const VIDEO_WIDTH = 1080; 
const VIDEO_HEIGHT = 1920;
const TRANSITION_DURATION_S = 0.8; 
const POST_AUDIO_DELAY_S = 0.5;
const ZOOM_FACTOR = 0.12; 

const BASE_DESIGN_WIDTH = 600;
const SCALE_FACTOR = VIDEO_WIDTH / BASE_DESIGN_WIDTH; 
const BASE_DESIGN_HEIGHT = VIDEO_HEIGHT / SCALE_FACTOR;

const getSupportedMimeType = () => {
    const types = [
        'video/webm;codecs=vp9,opus',
        'video/webm;codecs=vp8,opus',
        'video/webm',
        'video/mp4;codecs=avc1',
        'video/mp4'
    ];

    for (const type of types) {
        if (MediaRecorder.isTypeSupported(type)) {
            return type;
        }
    }
    return '';
};

const easeInOutCubic = (t: number): number => t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;

const setupBackgroundMusic = (audioContext: AudioContext, destination: AudioNode) => {
    const mainGain = audioContext.createGain();
    mainGain.gain.value = 0.04; 
    mainGain.connect(destination);

    const playNote = (freq: number, startTime: number) => {
        try {
            const osc = audioContext.createOscillator();
            const g = audioContext.createGain();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(freq, startTime);
            g.gain.setValueAtTime(0, startTime);
            g.gain.linearRampToValueAtTime(0.15, startTime + 0.5);
            g.gain.exponentialRampToValueAtTime(0.001, startTime + 4);
            osc.connect(g);
            g.connect(mainGain);
            osc.start(startTime);
            osc.stop(startTime + 4);
        } catch (e) {}
    };

    const melody = [440, 554, 659, 880, 659, 554];
    let time = audioContext.currentTime;
    for (let i = 0; i < 100; i++) {
        melody.forEach((note, idx) => {
            playNote(note, time + (i * 6) + (idx * 1));
        });
    }
};

const createTurnSoundBuffer = (audioContext: AudioContext): AudioBuffer => {
    const duration = 0.5;
    const buffer = audioContext.createBuffer(1, Math.max(1, audioContext.sampleRate * duration), audioContext.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < buffer.length; i++) {
        data[i] = (Math.random() * 2 - 1) * 0.05 * (1 - i / buffer.length);
    }
    return buffer;
};

const loadAudio = async (url: string, audioContext: AudioContext): Promise<AudioBuffer> => {
    if (!url) return audioContext.createBuffer(1, audioContext.sampleRate, audioContext.sampleRate);
    try {
        const response = await fetch(url);
        if (!response.ok) throw new Error("Fetch failed");
        const arrayBuffer = await response.arrayBuffer();
        return await audioContext.decodeAudioData(arrayBuffer);
    } catch (e) {
        console.warn("Audio load failed for URL:", url, e);
        return audioContext.createBuffer(1, audioContext.sampleRate, audioContext.sampleRate);
    }
};

const renderPageToImage = async (
    page: PageData, 
    index: number, 
    total: number, 
    container: HTMLElement, 
    root: any,
    textFontSize?: number
): Promise<HTMLImageElement | null> => {
    try {
        root.render(
            <div style={{ width: BASE_DESIGN_WIDTH, height: BASE_DESIGN_HEIGHT, backgroundColor: '#F9F5EF' }}>
                <StoryPage page={page} pageIndex={index} totalPages={total} fontSize={textFontSize} />
            </div>
        );
        await new Promise(r => setTimeout(r, 1500));

        const canvas = await html2canvas(container, {
            scale: SCALE_FACTOR, 
            width: BASE_DESIGN_WIDTH,
            height: BASE_DESIGN_HEIGHT,
            backgroundColor: '#F9F5EF',
            useCORS: true,
            logging: false,
            allowTaint: true
        });

        return new Promise((resolve) => {
            const img = new Image();
            img.onload = () => resolve(img);
            img.onerror = () => resolve(null);
            img.src = canvas.toDataURL('image/jpeg', 0.9);
        });
    } catch (err) {
        console.error("Error rendering page to image:", err);
        return null;
    }
};

export interface VideoConfig {
    fps: number;
    bitrate: number;
    textFontSize?: number;
    signal?: AbortSignal;
    isPaused?: () => boolean;
}

export const generateStoryVideo = async (
    story: Story, 
    onProgress: (msg: string, percent: number) => void,
    config: VideoConfig = { fps: 30, bitrate: 12000000, textFontSize: 18 }
): Promise<void> => {
    const { fps, bitrate, textFontSize, signal, isPaused } = config;
    const mimeType = getSupportedMimeType();

    if (!mimeType) {
        alert("عذراً، متصفحك لا يدعم تسجيل الفيديو.");
        return;
    }

    const checkStatus = async () => {
        if (signal?.aborted) throw new Error("CANCELLED");
        while (isPaused?.()) {
            if (signal?.aborted) throw new Error("CANCELLED");
            await new Promise(r => setTimeout(r, 200));
        }
    };

    onProgress("بدء تجهيز المحرك السحري...", 5);

    const container = document.createElement('div');
    container.style.position = 'fixed';
    container.style.left = '-9999px'; 
    container.style.top = '0';
    container.style.width = `${BASE_DESIGN_WIDTH}px`;
    container.style.height = `${BASE_DESIGN_HEIGHT}px`;
    document.body.appendChild(container);
    const root = createRoot(container);

    const canvas = document.createElement('canvas');
    canvas.width = VIDEO_WIDTH;
    canvas.height = VIDEO_HEIGHT;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
    const dest = audioContext.createMediaStreamDestination();
    setupBackgroundMusic(audioContext, dest);
    const turnSound = createTurnSoundBuffer(audioContext);

    const videoStream = canvas.captureStream(fps);
    const combinedStream = new MediaStream([
        ...videoStream.getVideoTracks(),
        ...dest.stream.getAudioTracks()
    ]);

    const recorder = new MediaRecorder(combinedStream, { 
        mimeType, 
        videoBitsPerSecond: bitrate 
    }); 

    const chunks: Blob[] = [];
    recorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunks.push(e.data);
    };

    return new Promise<void>(async (resolve, reject) => {
        recorder.onstop = () => {
            try {
                if (chunks.length === 0) {
                    throw new Error("No video chunks were recorded.");
                }
                const finalBlob = new Blob(chunks, { type: mimeType });
                const url = URL.createObjectURL(finalBlob);
                const extension = mimeType.includes('mp4') ? 'mp4' : 'webm';

                const a = document.createElement('a');
                a.href = url;
                const cleanTitle = story.title.replace(/[^\u0600-\u06FFa-zA-Z0-9]/g, '_');
                a.download = `Story_${cleanTitle}.${extension}`;
                document.body.appendChild(a);
                a.click();
                setTimeout(() => {
                    document.body.removeChild(a);
                    URL.revokeObjectURL(url);
                }, 100);

                onProgress("تم الحفظ بنجاح!", 100);
                cleanup();
                resolve();
            } catch (err) {
                console.error("Recording stop error:", err);
                cleanup();
                reject(err);
            }
        };

        const cleanup = () => {
            if (audioContext.state !== 'closed') audioContext.close();
            root.unmount();
            if (document.body.contains(container)) document.body.removeChild(container);
        };

        recorder.start();

        try {
            const pages = getStoryPages(story);
            await checkStatus();
            let currentImg = await renderPageToImage(pages[0], 0, pages.length, container, root, textFontSize);

            for (let i = 0; i < pages.length; i++) {
                await checkStatus();
                const isLast = i === pages.length - 1;
                const progressPercent = 10 + Math.floor((i / pages.length) * 80);
                onProgress(`جاري تسجيل المشهد ${i + 1}...`, progressPercent);

                if (!currentImg) continue;

                const audioBuf = await loadAudio(pages[i].audioUrl || '', audioContext);
                const source = audioContext.createBufferSource();
                source.buffer = audioBuf;
                source.connect(dest);
                source.start();

                const durationMs = (audioBuf.duration + POST_AUDIO_DELAY_S) * 1000;
                let elapsedMs = 0;
                let lastTime = Date.now();

                // تشغيل المشهد الحالي
                while (elapsedMs < durationMs) {
                    await checkStatus();
                    const now = Date.now();
                    elapsedMs += (now - lastTime);
                    lastTime = now;

                    const progress = Math.min(elapsedMs / durationMs, 1.0);
                    const currentScale = 1 + (progress * ZOOM_FACTOR);

                    const dw = VIDEO_WIDTH * currentScale;
                    const dh = VIDEO_HEIGHT * currentScale;
                    const dx = (VIDEO_WIDTH - dw) / 2;
                    const dy = (VIDEO_HEIGHT - dh) / 2;

                    ctx.fillStyle = '#F9F5EF';
                    ctx.fillRect(0, 0, VIDEO_WIDTH, VIDEO_HEIGHT);
                    ctx.drawImage(currentImg, dx, dy, dw, dh);

                    await new Promise(r => requestAnimationFrame(r));
                }

                // إيقاف الصوت الحالي تماماً قبل الانتقال
                source.stop();

                if (!isLast) {
                    await checkStatus();
                    const nextImg = await renderPageToImage(pages[i + 1], i + 1, pages.length, container, root, textFontSize);
                    if (nextImg) {
                        const turnSource = audioContext.createBufferSource();
                        turnSource.buffer = turnSound;
                        turnSource.connect(dest);
                        turnSource.start();

                        const transFrames = Math.ceil(TRANSITION_DURATION_S * fps);
                        for (let t = 0; t <= transFrames; t++) {
                            await checkStatus();
                            const p = t / transFrames;
                            const easeP = easeInOutCubic(p);

                            ctx.fillStyle = '#F9F5EF';
                            ctx.fillRect(0, 0, VIDEO_WIDTH, VIDEO_HEIGHT);

                            ctx.globalAlpha = 1 - easeP;
                            const oldScale = 1 + ZOOM_FACTOR;
                            ctx.drawImage(currentImg, ((VIDEO_WIDTH - (VIDEO_WIDTH * oldScale)) / 2) - (easeP * 400), (VIDEO_HEIGHT - (VIDEO_HEIGHT * oldScale)) / 2, VIDEO_WIDTH * oldScale, VIDEO_HEIGHT * oldScale);

                            ctx.globalAlpha = easeP;
                            const nextScale = 1.1 - (easeP * 0.1);
                            ctx.drawImage(nextImg, ((VIDEO_WIDTH - (VIDEO_WIDTH * nextScale)) / 2) + ((1 - easeP) * 400), (VIDEO_HEIGHT - (VIDEO_HEIGHT * nextScale)) / 2, VIDEO_WIDTH * nextScale, VIDEO_HEIGHT * nextScale);

                            ctx.globalAlpha = 1.0;
                            await new Promise(r => requestAnimationFrame(r));
                        }
                        currentImg = nextImg;
                        turnSource.stop(); // تنظيف صوت قلب الورقة
                    }
                }
            }

            onProgress("تم التسجيل! جاري معالجة الملف النهائي...", 95);
            recorder.stop();

        } catch (e: any) {
            if (recorder.state !== 'inactive') recorder.stop();
            cleanup();
            if (e.message === "CANCELLED") {
                onProgress("تم إلغاء العملية", 0);
                resolve();
            } else {
                reject(e);
            }
        }
    });
};

import React, { useState, useEffect, useRef } from 'react';
import { Story } from '../types';
import { getStoryPages, PageData } from '../utils/storyHelper';
import { StoryPage } from './StoryPage';

interface BookReaderProps {
    story: Story;
    onClose: () => void;
}

export const BookReader: React.FC<BookReaderProps> = ({ story, onClose }) => {
    const [pages, setPages] = useState<PageData[]>([]);
    const [currentPage, setCurrentPage] = useState(0);
    const [prevPage, setPrevPage] = useState<number | null>(null);
    const [direction, setDirection] = useState<'next' | 'prev'>('next');
    const [isPlaying, setIsPlaying] = useState(false);
    const [isAnimating, setIsAnimating] = useState(false);

    // المرجع الوحيد والمقدس للصوت الحالي
    const currentAudioRef = useRef<HTMLAudioElement | null>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const navigationLockRef = useRef<boolean>(false);

    useEffect(() => {
        setPages(getStoryPages(story));
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        audioContextRef.current = new AudioContextClass();

        return () => {
            stopAudioDirectly();
            if (audioContextRef.current && audioContextRef.current.state !== 'closed') {
                audioContextRef.current.close();
            }
        };
    }, [story]);

    // وظيفة لإيقاف وتدمير أي صوت نشط فوراً
    const stopAudioDirectly = () => {
        if (currentAudioRef.current) {
            currentAudioRef.current.pause();
            currentAudioRef.current.onended = null;
            currentAudioRef.current.oncanplaythrough = null;
            currentAudioRef.current.src = "";
            currentAudioRef.current.load(); // تفريغ الـ Buffer
            currentAudioRef.current = null;
        }
    };

    const playSoundEffect = (type: 'turn' | 'click') => {
        const ctx = audioContextRef.current;
        if (!ctx || ctx.state === 'closed') return;
        if (ctx.state === 'suspended') ctx.resume();
        const t = ctx.currentTime;
        if (type === 'turn') {
            const buffer = ctx.createBuffer(1, ctx.sampleRate * 0.3, ctx.sampleRate);
            const data = buffer.getChannelData(0);
            for (let i = 0; i < data.length; i++) data[i] = (Math.random() * 2 - 1) * 0.05 * (1 - i / data.length);
            const noise = ctx.createBufferSource();
            noise.buffer = buffer;
            const filter = ctx.createBiquadFilter();
            filter.type = 'lowpass'; filter.frequency.setValueAtTime(800, t);
            noise.connect(filter); filter.connect(ctx.destination);
            noise.start(t);
        }
    };

    // المحرك الأساسي للصوت والمزامنة
    useEffect(() => {
        if (!isPlaying || pages.length === 0) {
            stopAudioDirectly();
            return;
        }

        const page = pages[currentPage];
        if (!page?.audioUrl) return;

        // 1. تنظيف أي بقايا صوتية قبل البدء
        stopAudioDirectly();

        // 2. إنشاء كائن صوتي جديد تماماً
        const audio = new Audio(page.audioUrl);
        audio.preload = "auto";
        currentAudioRef.current = audio;

        // 3. المزامنة: يبدأ الصوت فوراً
        audio.play().catch(e => console.warn("Playback prevented:", e));

        // 4. الانتقال التلقائي الصارم
        audio.onended = () => {
            // نتحقق من أننا ما زلنا في وضع التشغيل ولم يتم تغيير الصفحة يدوياً
            if (isPlaying && currentAudioRef.current === audio && currentPage < pages.length - 1) {
                navigate('next');
            } else if (currentPage === pages.length - 1) {
                setIsPlaying(false);
            }
        };

        // تنظيف عند خروج المكون أو تغير الاعتماديات
        return () => stopAudioDirectly();
    }, [currentPage, isPlaying, pages]);

    const navigate = (dir: 'next' | 'prev') => {
        // منع التداخل إذا كان هناك حركة قائمة أو قفل
        if (isAnimating || navigationLockRef.current) return;

        const isNext = dir === 'next';
        if (isNext && currentPage >= pages.length - 1) return;
        if (!isNext && currentPage <= 0) return;

        // تفعيل القفل
        navigationLockRef.current = true;

        // إيقاف الصوت الحالي فوراً (قبل تحديث الحالة)
        stopAudioDirectly();

        playSoundEffect('turn');
        setIsAnimating(true);
        setPrevPage(currentPage);
        setDirection(dir);
        setCurrentPage(prev => isNext ? prev + 1 : prev - 1);

        // فتح القفل بعد انتهاء الأنيميشن
        setTimeout(() => {
            setIsAnimating(false);
            navigationLockRef.current = false;
        }, 750);
    };

    const togglePlay = () => {
        if (!isPlaying) {
            setIsPlaying(true);
        } else {
            setIsPlaying(false);
            stopAudioDirectly();
        }
    };

    return (
        <div className="fixed inset-0 z-50 bg-black flex flex-col items-center justify-center p-2 overflow-hidden" dir="rtl">
            <div className="w-full max-w-lg flex justify-between items-center mb-6 text-white px-4 z-10">
                <button onClick={() => { stopAudioDirectly(); onClose(); }} className="p-3 bg-white/10 rounded-full hover:bg-rose-500 transition-colors">
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
                </button>

                <div className="flex items-center gap-6">
                    <div className="text-lg font-bold bg-white/5 px-4 py-1.5 rounded-full border border-white/10">
                        {currentPage + 1} <span className="text-white/30 mx-1">/</span> {pages.length}
                    </div>
                    <button onClick={togglePlay} className={`rounded-full p-4 transition-all shadow-2xl active:scale-95 ${isPlaying ? 'bg-rose-500' : 'bg-emerald-500'}`}>
                        {isPlaying ? (
                            <svg xmlns="http://www.w3.org/2000/svg" width="28" height="28" viewBox="0 0 24 24" fill="white"><rect x="6" y="4" width="4" height="16"></rect><rect x="14" y="4" width="4" height="16"></rect></svg>
                        ) : (
                            <svg xmlns="http://www.w3.org/2000/svg" width="28" height="28" viewBox="0 0 24 24" fill="white"><polygon points="5 3 19 12 5 21 5 3"></polygon></svg>
                        )}
                    </button>
                </div>
            </div>

            <div className="relative w-full h-full max-h-[75vh] md:max-h-[85vh] aspect-[9/16] max-w-md perspective-2000">
                <div className="absolute right-[-2px] top-[1%] bottom-[1%] w-3 bg-white/5 rounded-r-lg blur-[1px] z-0"></div>

                <div className="relative w-full h-full transform-style-3d">
                    {prevPage !== null && (
                        <div className="absolute inset-0 bg-[#F9F5EF] rounded-xl shadow-inner overflow-hidden opacity-30">
                             <StoryPage page={pages[prevPage]} pageIndex={prevPage} totalPages={pages.length} />
                        </div>
                    )}

                    {pages[currentPage] && (
                        <div 
                            key={currentPage} 
                            className={`absolute inset-0 bg-white rounded-xl shadow-2xl overflow-hidden origin-right-spine transform-style-3d ${direction === 'next' ? 'animate-page-flip-next' : 'animate-page-flip-prev'}`}
                        >
                            <StoryPage page={pages[currentPage]} pageIndex={currentPage} totalPages={pages.length} />

                            {pages[currentPage].type === 'end' && (
                                <div className="absolute bottom-16 left-0 right-0 flex justify-center z-50">
                                     <button onClick={() => { stopAudioDirectly(); onClose(); }} className="px-12 py-4 bg-rose-600 text-white rounded-full font-bold hover:bg-rose-700 transition shadow-2xl animate-pulse">
                                        إغلاق الكتاب ✨
                                    </button>
                                </div>
                            )}
                        </div>
                    )}
                </div>
            </div>

            <div className="w-full max-w-lg flex justify-between items-center mt-8 px-6 z-10">
                 <button 
                    onClick={() => navigate('prev')} 
                    disabled={currentPage === 0 || isAnimating}
                    className="text-white bg-white/5 rounded-full p-4 disabled:opacity-5 hover:bg-white/20 transition-all active:scale-90"
                 >
                     <svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 18 9 12 15 6"></polyline></svg>
                 </button>

                 <div className="text-white/20 text-[10px] font-black tracking-[0.4em] uppercase select-none">
                    Studio Quality Sync
                 </div>

                 <button 
                    onClick={() => navigate('next')} 
                    disabled={currentPage === pages.length - 1 || isAnimating}
                    className="text-white bg-white/5 rounded-full p-4 disabled:opacity-5 hover:bg-white/20 transition-all active:scale-90"
                 >
                    <svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"><polyline points="9 18 15 12 9 6"></polyline></svg>
                 </button>
             </div>

             <style>{`
                .perspective-2000 { perspective: 3000px; }
                .transform-style-3d { transform-style: preserve-3d; }
                .origin-right-spine { transform-origin: right center; }

                @keyframes pageFlipNext {
                    0% { transform: rotateY(90deg); filter: brightness(0.4); }
                    100% { transform: rotateY(0deg); filter: brightness(1); }
                }

                @keyframes pageFlipPrev {
                    0% { transform: rotateY(-90deg); filter: brightness(0.4); transform-origin: left center; }
                    100% { transform: rotateY(0deg); filter: brightness(1); transform-origin: left center; }
                }

                .animate-page-flip-next {
                    animation: pageFlipNext 0.75s cubic-bezier(0.2, 0, 0.2, 1) forwards;
                    backface-visibility: hidden;
                }

                .animate-page-flip-prev {
                    animation: pageFlipPrev 0.75s cubic-bezier(0.2, 0, 0.2, 1) forwards;
                    backface-visibility: hidden;
                }
             `}</style>
        </div>
    );
};

import { GoogleGenAI, Modality, Type } from "@google/genai";
import { FormData, Story, Scene, Chapter } from '../types';
import { base64ToWav } from '../utils/audioHelper';

if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable not set");
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

async function retryOperation<T>(
    operation: () => Promise<T>,
    retries: number = 4,
    initialDelay: number = 6000,
    operationName: string = "Operation"
): Promise<T> {
    let currentDelay = initialDelay;
    for (let i = 0; i < retries; i++) {
        try {
            return await operation();
        } catch (error: any) {
            const isRateLimit = 
                error?.status === 429 || 
                error?.code === 429 || 
                error?.status === 'RESOURCE_EXHAUSTED' ||
                (error?.message && (
                    error.message.includes('429') || 
                    error.message.includes('quota') || 
                    error.message.includes('RESOURCE_EXHAUSTED')
                ));

            if (isRateLimit) {
                await wait(currentDelay);
                currentDelay *= 1.5;
                continue;
            }
            throw error;
        }
    }
    throw new Error(`${operationName} failed`);
}

const analyzeChildImage = async (imageBase64: string, mimeType: string): Promise<string> => {
    return await retryOperation(async () => {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: {
                parts: [
                    { inlineData: { mimeType, data: imageBase64 } },
                    { text: "Describe this child's main features (hair, eyes, skin) concisely for a cartoon character." }
                ]
            },
        });
        return response.text || "A happy child";
    }, 3, 3000, "Analyze Image");
};

const generateStoryText = async (formData: FormData, characterDescription: string): Promise<Story> => {
    const { age, language, storyPrompt, numChapters, scenesPerChapter, childName } = formData;
    const prompt = `Create an exciting, fast-paced story for a ${age}-year-old named "${childName}" in ${language}. Tone: Adventurous and high energy. Theme: ${storyPrompt}. Character: ${characterDescription}. EXACTLY ${numChapters} chapters, ${scenesPerChapter} scenes each.`;

    return retryOperation(async () => {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        title: { type: Type.STRING },
                        chapters: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    chapter_number: { type: Type.INTEGER },
                                    title: { type: Type.STRING },
                                    scenes: {
                                        type: Type.ARRAY,
                                        items: {
                                            type: Type.OBJECT,
                                            properties: {
                                                scene_number: { type: Type.INTEGER },
                                                text: { type: Type.STRING },
                                                image_prompt: { type: Type.STRING },
                                            },
                                            required: ["scene_number", "text", "image_prompt"]
                                        },
                                    },
                                },
                                required: ["chapter_number", "title", "scenes"]
                            },
                        },
                    },
                    required: ["title", "chapters"]
                },
            },
        });
        return JSON.parse(response.text) as Story;
    }, 3, 5000, "Generate Story");
};

const generateImageForScene = async (prompt: string, baseImg: string, mime: string): Promise<string> => {
    try {
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: { parts: [{ inlineData: { data: baseImg, mimeType: mime } }, { text: prompt }] },
            config: { responseModalities: [Modality.IMAGE] },
        });
        const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
        return part ? `data:${part.inlineData.mimeType};base64,${part.inlineData.data}` : "";
    } catch (e) { return ""; }
};

const generateAudioSegment = async (text: string, voiceName: string): Promise<string | undefined> => {
    if (!text.trim()) return undefined;
    // إضافة تعليمات السرعة والحماس للراوي
    const fastPacedPrompt = `In an energetic, enthusiastic, and fast-paced storytelling voice suitable for a viral social media video, say: ${text}`;

    try {
        return await retryOperation(async () => {
            const response = await ai.models.generateContent({
                model: "gemini-2.5-flash-preview-tts",
                contents: { parts: [{ text: fastPacedPrompt }] },
                config: {
                    responseModalities: [Modality.AUDIO],
                    speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName } } },
                },
            });
            const base64 = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData)?.inlineData?.data;
            if (!base64) return undefined;
            return URL.createObjectURL(base64ToWav(base64, 24000));
        }, 1, 2000, "Generate Audio");
    } catch { return undefined; }
};

export const generateStoryWorkflow = async (formData: FormData, imageData: any, updateStep: any): Promise<Story> => {
    updateStep("تحليل البطل...");
    const charDesc = await analyzeChildImage(imageData.data, imageData.mimeType);
    updateStep("كتابة السيناريو المشوق...");
    const story = await generateStoryText(formData, charDesc);
    const chapters: Chapter[] = [];

    updateStep("تسجيل المقدمة الحماسية...");
    const titleAudio = await generateAudioSegment(`مرحباً بكم في مغامرة جديدة! بطلنا اليوم هو ${formData.childName} في قصة: ${story.title}`, formData.voiceName);

    for (const ch of story.chapters) {
        const scenes: Scene[] = [];
        for (const sc of ch.scenes) {
            updateStep(`جاري صنع المشهد ${sc.scene_number}...`);
            const [img, aud] = await Promise.all([
                generateImageForScene(sc.image_prompt, imageData.data, imageData.mimeType),
                generateAudioSegment(sc.text, formData.voiceName)
            ]);
            scenes.push({ ...sc, imageUrl: img, audioUrl: aud });
        }
        chapters.push({ ...ch, scenes });
    }

    return { ...story, chapters, titleAudioUrl: titleAudio };
};

import React from 'react';
import { createRoot } from 'react-dom/client';
import { Story } from '../types';
import { getStoryPages, PageData } from './storyHelper';

declare const html2canvas: any;

const VIDEO_WIDTH = 1080; 
const VIDEO_HEIGHT = 1920;
const FAST_TRANSITION_S = 0.3; 
const ZOOM_SPEED = 0.25; // زووم أسرع وأكثر وضوحاً

const getSupportedMimeType = () => {
    const types = ['video/webm;codecs=vp9,opus', 'video/webm', 'video/mp4'];
    for (const type of types) if (MediaRecorder.isTypeSupported(type)) return type;
    return '';
};

const drawTikTokStyleText = (ctx: CanvasRenderingContext2D, text: string, fontSize: number) => {
    const words = text.split(' ');
    const maxWidth = VIDEO_WIDTH * 0.8;
    const lineHeight = fontSize * 1.3;
    const lines = [];
    let currentLine = '';

    ctx.font = `bold ${fontSize}px 'Cairo', sans-serif`;

    for (const word of words) {
        const testLine = currentLine + word + ' ';
        if (ctx.measureText(testLine).width > maxWidth && currentLine !== '') {
            lines.push(currentLine);
            currentLine = word + ' ';
        } else {
            currentLine = testLine;
        }
    }
    lines.push(currentLine);

    const totalHeight = lines.length * lineHeight;
    let y = (VIDEO_HEIGHT * 0.8) - (totalHeight / 2); // وضع النص في الجزء السفلي بوضوح

    lines.forEach(line => {
        const x = VIDEO_WIDTH / 2;
        // رسم الظل القوي (TikTok Style)
        ctx.shadowColor = 'rgba(0,0,0,0.8)';
        ctx.shadowBlur = 15;
        ctx.strokeStyle = 'black';
        ctx.lineWidth = 8;
        ctx.strokeText(line.trim(), x, y);

        ctx.fillStyle = 'white';
        ctx.textAlign = 'center';
        ctx.shadowBlur = 0;
        ctx.fillText(line.trim(), x, y);
        y += lineHeight;
    });
};

const loadAudio = async (url: string, audioContext: AudioContext): Promise<AudioBuffer> => {
    if (!url) return audioContext.createBuffer(1, 44100, 44100);
    const res = await fetch(url);
    const buf = await res.arrayBuffer();
    return await audioContext.decodeAudioData(buf);
};

export const generateStoryVideo = async (
    story: Story, 
    onProgress: (msg: string, percent: number) => void,
    config: any
): Promise<void> => {
    const { fps = 30, bitrate = 15000000, textFontSize = 60 } = config;
    const mimeType = getSupportedMimeType();

    onProgress("تجهيز محرك الترند...", 5);

    const canvas = document.createElement('canvas');
    canvas.width = VIDEO_WIDTH;
    canvas.height = VIDEO_HEIGHT;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
    const dest = audioContext.createMediaStreamDestination();

    const videoStream = canvas.captureStream(fps);
    const combinedStream = new MediaStream([...videoStream.getVideoTracks(), ...dest.stream.getAudioTracks()]);
    const recorder = new MediaRecorder(combinedStream, { mimeType, videoBitsPerSecond: bitrate }); 

    const chunks: Blob[] = [];
    recorder.ondataavailable = (e) => chunks.push(e.data);

    return new Promise(async (resolve, reject) => {
        recorder.onstop = () => {
            const blob = new Blob(chunks, { type: mimeType });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `Trend_Story_${Date.now()}.mp4`;
            a.click();
            audioContext.close();
            resolve();
        };

        recorder.start();
        const pages = getStoryPages(story);

        try {
            for (let i = 0; i < pages.length; i++) {
                const page = pages[i];
                onProgress(`جاري دمج اللقطة ${i + 1}...`, 10 + (i / pages.length) * 80);

                const audioBuf = await loadAudio(page.audioUrl || '', audioContext);
                const source = audioContext.createBufferSource();
                source.buffer = audioBuf;
                source.connect(dest);
                source.start();

                const img = new Image();
                if (page.imageUrl) {
                    img.src = page.imageUrl;
                    await new Promise(r => img.onload = r);
                }

                const durationMs = audioBuf.duration * 1000;
                let elapsed = 0;
                let lastTime = Date.now();

                while (elapsed < durationMs) {
                    const now = Date.now();
                    elapsed += (now - lastTime);
                    lastTime = now;

                    const p = Math.min(elapsed / durationMs, 1);
                    const scale = 1 + (p * ZOOM_SPEED);

                    // رسم الخلفية المضببة (TikTok Style for portrait)
                    ctx.fillStyle = '#111';
                    ctx.fillRect(0, 0, VIDEO_WIDTH, VIDEO_HEIGHT);

                    if (page.imageUrl) {
                        const dw = VIDEO_WIDTH * scale;
                        const dh = (VIDEO_WIDTH * (img.height / img.width)) * scale;
                        ctx.drawImage(img, (VIDEO_WIDTH - dw) / 2, (VIDEO_HEIGHT - dh) / 2, dw, dh);
                    }

                    // رسم النص بأسلوب الترند
                    if (page.text || page.title) {
                        drawTikTokStyleText(ctx, page.text || page.title || '', textFontSize * 2.5);
                    }

                    await new Promise(r => requestAnimationFrame(r));
                    if (config.signal?.aborted) throw new Error("CANCELLED");
                }
                source.stop();
            }
            recorder.stop();
        } catch (e) {
            recorder.stop();
            reject(e);
        }
    });
};

