interface StoryPreviewProps {
    story: Story;
}

export const StoryPreview: React.FC<StoryPreviewProps> = ({ story }) => {
    const [isDownloadingPdf, setIsDownloadingPdf] = useState(false);
    const [isGeneratingVideo, setIsGeneratingVideo] = useState(false);
    const [isVideoPaused, setIsVideoPaused] = useState(false);
    const [videoProgress, setVideoProgress] = useState('');
    const [videoPercent, setVideoPercent] = useState(0);
    const [isBookMode, setIsBookMode] = useState(false);
    const [showVideoOptions, setShowVideoOptions] = useState(false);
    const [showPdfOptions, setShowPdfOptions] = useState(false);

    // إعدادات الـ PDF التي يتحكم بها المستخدم يدوياً
    const [pdfSettings, setPdfSettings] = useState<PdfSettings>({
        fontFamily: 'Cairo',
        fontSize: 28, // الحجم المطلوب
        fontColor: '#1a1a1a',
        lineHeight: 2.0, // تباعد الأسطر المطلوب
        margins: 50,
        textAlign: 'right',
        pageSize: 'a4',
        direction: 'rtl',
        backgroundColor: '#ffffff'
    });

    const [videoQuality, setVideoQuality] = useState(12000000);
    const [frameRate, setFrameRate] = useState(30);

    const abortControllerRef = useRef<AbortController | null>(null);
    const isVideoPausedRef = useRef(false);

    const handleDownloadPdf = async () => {
        setIsDownloadingPdf(true);
        setShowPdfOptions(false);
        try {
            await generatePdf(story.title, pdfSettings.pageSize);
        } catch (error) {
            console.error("Failed to generate PDF", error);
            alert("حدث خطأ أثناء إنشاء ملف PDF.");
        } finally {
            setIsDownloadingPdf(false);
        }
    };

    const handleDownloadVideo = async () => {
        if (isGeneratingVideo) return;
        setIsGeneratingVideo(true);
        setIsVideoPaused(false);
        isVideoPausedRef.current = false;
        setVideoPercent(0);
        setShowVideoOptions(false);
        abortControllerRef.current = new AbortController();

        try {
            await generateStoryVideo(story, (msg, percent) => {
                setVideoProgress(msg);
                setVideoPercent(percent);
            }, { 
                bitrate: videoQuality, 
                fps: frameRate,
                signal: abortControllerRef.current.signal,
                isPaused: () => isVideoPausedRef.current
            });
        } catch (error) {
            console.error("Video generation error:", error);
        } finally {
            setIsGeneratingVideo(false);
            setVideoProgress('');
            setVideoPercent(0);
            abortControllerRef.current = null;
        }
    };

    const storyPages = getStoryPages(story);

    return (
        <div className="bg-white p-4 md:p-8 rounded-2xl shadow-lg border border-rose-100">
            {isBookMode && <BookReader story={story} onClose={() => setIsBookMode(false)} />}

            {isGeneratingVideo && (
                <div className="fixed inset-0 z-[60] bg-black/85 flex flex-col items-center justify-center text-white p-6 text-center backdrop-blur-md">
                    <div className="relative mb-8">
                        <div className={`animate-spin rounded-full h-24 w-24 border-t-4 border-b-4 border-rose-500`}></div>
                        <div className="absolute inset-0 flex items-center justify-center font-bold text-lg text-rose-500">
                            {videoPercent}%
                        </div>
                    </div>
                    <h2 className="text-2xl font-bold mb-2">جاري إنشاء الفيديو السحري</h2>
                    <p className="text-lg text-gray-200 mb-10">{videoProgress}</p>
                </div>
            )}

            <div className="flex flex-col sm:flex-row justify-between items-center mb-6 border-b-2 border-rose-200 pb-4">
                <div className="flex items-center gap-3 mb-4 sm:mb-0">
                    <BookOpenIcon className="h-8 w-8 text-rose-500" />
                    <h2 className="text-3xl font-bold text-rose-800 font-storybook">{story.title}</h2>
                </div>
                <div className="flex flex-wrap gap-2 w-full sm:w-auto justify-center items-center">
                    <button onClick={() => setIsBookMode(true)} className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-gradient-to-r from-purple-500 to-rose-500 text-white font-bold py-2 px-6 rounded-lg hover:from-purple-600 hover:to-rose-600 shadow-md transition transform hover:scale-105">
                        <span>قراءة</span>
                    </button>

                    <div className="relative">
                         <button onClick={() => { setShowVideoOptions(!showVideoOptions); setShowPdfOptions(false); }} className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-blue-500 text-white font-bold py-2 px-6 rounded-lg hover:bg-blue-600 transition">
                            <VideoIcon className="h-5 w-5" />
                            <span>فيديو</span>
                        </button>
                        {showVideoOptions && (
                            <div className="absolute top-full mt-2 left-0 right-0 sm:right-auto sm:w-72 bg-white border border-rose-100 shadow-2xl rounded-xl p-5 z-50 text-right">
                                <h4 className="font-bold text-rose-800 mb-3 border-b pb-2">إعدادات الفيديو</h4>
                                <button onClick={handleDownloadVideo} className="w-full bg-emerald-500 hover:bg-emerald-600 text-white font-bold py-2 rounded shadow-md transition-colors">بدء الإنشاء</button>
                            </div>
                        )}
                    </div>

                    <div className="relative">
                        <button onClick={() => { setShowPdfOptions(!showPdfOptions); setShowVideoOptions(false); }} disabled={isDownloadingPdf} className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-green-500 text-white font-bold py-2 px-6 rounded-lg hover:bg-green-600 transition">
                            <DownloadIcon className="h-5 w-5" />
                            <span>PDF</span>
                        </button>
                        {showPdfOptions && (
                            <div className="absolute top-full mt-2 right-0 sm:left-0 sm:right-auto w-full sm:w-80 bg-white border border-rose-100 shadow-2xl rounded-xl p-6 z-50 text-right animate-in fade-in slide-in-from-top-2">
                                <h4 className="font-bold text-rose-800 mb-4 border-b pb-2 text-lg">تنسيق الـ PDF المخصص</h4>
                                <div className="space-y-4 max-h-[60vh] overflow-y-auto px-1">
                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 mb-1">نوع الخط</label>
                                        <select value={pdfSettings.fontFamily} onChange={(e) => setPdfSettings({...pdfSettings, fontFamily: e.target.value as any})} className="w-full text-sm border rounded p-2 outline-none focus:ring-1 focus:ring-rose-500">
                                            <option value="Cairo">خط كايرو (عصري)</option>
                                            <option value="Amiri">خط أميري (كلاسيكي)</option>
                                            <option value="Lalezar">خط لولزار (مرح)</option>
                                        </select>
                                    </div>
                                    <div className="grid grid-cols-2 gap-3">
                                        <div>
                                            <label className="block text-xs font-bold text-gray-500 mb-1">حجم الخط</label>
