                                        </div>
                                        <div>
                                            <label className="block text-xs font-bold text-gray-500 mb-1">اللون</label>
                                            <input type="color" value={pdfSettings.fontColor} onChange={(e) => setPdfSettings({...pdfSettings, fontColor: e.target.value})} className="w-full h-10 p-1 border rounded" />
                                        </div>
                                    </div>
                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 mb-1 flex justify-between">
                                            <span>تباعد الأسطر</span>
                                            <span>{pdfSettings.lineHeight}</span>
                                        </label>
                                        <input type="range" min="1" max="4" step="0.1" value={pdfSettings.lineHeight} onChange={(e) => setPdfSettings({...pdfSettings, lineHeight: Number(e.target.value)})} className="w-full h-1.5 bg-gray-200 rounded-lg accent-rose-500" />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 mb-1">الهوامش (بكسل)</label>
                                        <input type="number" value={pdfSettings.margins} onChange={(e) => setPdfSettings({...pdfSettings, margins: Number(e.target.value)})} className="w-full text-sm border rounded p-2 outline-none focus:ring-1 focus:ring-rose-500" />
