declare const jspdf: any;
declare const html2canvas: any;

/**
 * وظيفة للتحقق من أن الخط المختار محمل وجاهز للاستخدام في المتصفح.
 * إذا لم يكن الخط جاهزاً، يتم إيقاف العملية كما طلب المستخدم.
 */
const checkFontsReady = async (fontFamily: string): Promise<boolean> => {
    try {
        await document.fonts.ready;
        // التحقق من وجود الخط في الذاكرة
        const isLoaded = document.fonts.check(`12px ${fontFamily}`);
        return isLoaded;
    } catch (e) {
        return false;
    }
};

const waitForImagesToLoad = (element: HTMLElement): Promise<void[]> => {
    const images = Array.from(element.getElementsByTagName('img'));
    const promises = images.map(img => {
        return new Promise<void>((resolve, reject) => {
            if (img.complete) return resolve();
            img.onload = () => resolve();
            img.onerror = () => reject(new Error(`Could not load image: ${img.src.substring(0, 50)}`));
            setTimeout(resolve, 10000); // Fail-safe 10s
        });
    });
    return Promise.all(promises);
};

/**
 * إنشاء ملف PDF مطابق تماماً لإعدادات المستخدم.
 * يتم إيقاف التصدير فوراً إذا لم يتم التحقق من مطابقة الإعدادات.
 */
export const generatePdf = async (
    storyTitle: string, 
    pageSize: 'a4' | 'a5' | 'letter' = 'a4',
    fontFamily: string = 'Cairo'
) => {
    // التحقق الإلزامي من الخط قبل البدء
    const isFontReady = await checkFontsReady(fontFamily);
    if (!isFontReady) {
        console.error(`CRITICAL ERROR: Selected font "${fontFamily}" is not applied. Aborting PDF generation.`);
        throw new Error("تعذر تطبيق إعدادات الخط المحددة بدقة. تم إيقاف التصدير.");
    }

    const { jsPDF } = jspdf;
    const pdf = new jsPDF({
        orientation: 'p',
        unit: 'px',
        format: pageSize,
        hotfixes: ['px_scaling'],
    });

    const storyContent = document.getElementById('story-content');
    if (!storyContent) return;

    try {
        await waitForImagesToLoad(storyContent);

        const storyPages = document.querySelectorAll('.story-page') as NodeListOf<HTMLElement>;
        const pdfWidth = pdf.internal.pageSize.getWidth();
        const pdfHeight = pdf.internal.pageSize.getHeight();

        for (let i = 0; i < storyPages.length; i++) {
            const page = storyPages[i];

            // التقاط الصفحة بدقة فائقة لضمان ثبات الخطوط والأحجام والألوان
            const canvas = await html2canvas(page, {
                scale: 4, 
                useCORS: true,
                logging: false,
                backgroundColor: null,
                width: page.offsetWidth,
                height: page.offsetHeight,
                onclone: (clonedDoc) => {
                    // التأكد من أن النسخة المستنسخة لا تحتوي على أي تنسيقات افتراضية متداخلة
                    const clonedPage = clonedDoc.querySelector('.story-page') as HTMLElement;
                    if (clonedPage) {
                        clonedPage.style.fontFamily = fontFamily;
                    }
                }
            });

            const imgData = canvas.toDataURL('image/jpeg', 1.0);

            if (i > 0) pdf.addPage(pageSize, 'p');

            pdf.addImage(imgData, 'JPEG', 0, 0, pdfWidth, pdfHeight, undefined, 'FAST');
        }

        const fileName = `${storyTitle.replace(/\s+/g, '_')}_Manual_Settings.pdf`;
        pdf.save(fileName);
    } catch (error) {
        console.error("PDF generation failed:", error);
        throw error;
    }
};

