declare const jspdf: any;
declare const html2canvas: any;

/**
 * وظيفة محسنة للتحقق من جاهزية الخطوط.
 * بدلاً من مجرد الفحص، تحاول الوظيفة الآن تحميل الخط المختار بشكل صريح
 * لضمان توفره في ذاكرة المتصفح قبل البدء في الرسم على الـ Canvas.
 */
const checkFontsReady = async (fontFamily: string): Promise<boolean> => {
    try {
        // ننتظر أولاً جاهزية واجهة الخطوط في المتصفح
        await document.fonts.ready;

        // محاولة تحميل الخط بشكل صريح. مواصفة 12px كافية للتحقق من وجود العائلة.
        // نستخدم الكوتيشن للأسماء التي قد تحتوي على مسافات
        const fontSpec = `12px "${fontFamily}"`;

        // إذا كان الخط محملاً بالفعل، نعود فوراً
        if (document.fonts.check(fontSpec)) {
            return true;
        }

        // محاولة تحميل الخط
        const loadedFonts = await document.fonts.load(fontSpec);

        // نتحقق مما إذا كان قد تم تحميل الخط بنجاح
        return loadedFonts.length > 0 || document.fonts.check(fontSpec);
    } catch (e) {
        console.error("Font loading verification failed:", e);
        return false;
    }
};

const waitForImagesToLoad = (element: HTMLElement): Promise<void[]> => {
    const images = Array.from(element.getElementsByTagName('img'));
    const promises = images.map(img => {
        return new Promise<void>((resolve, reject) => {
            if (img.complete) return resolve();
            img.onload = () => resolve();
            img.onerror = () => reject(new Error(`Could not load image: ${img.src.substring(0, 50)}`));
            setTimeout(resolve, 10000); // Fail-safe 10s
        });
    });
    return Promise.all(promises);
};

/**
 * إنشاء ملف PDF مطابق تماماً لإعدادات المستخدم.
 * يتم إيقاف التصدير فوراً إذا لم يتم التحقق من مطابقة الإعدادات.
 */
export const generatePdf = async (
    storyTitle: string, 
    pageSize: 'a4' | 'a5' | 'letter' = 'a4',
    fontFamily: string = 'Cairo'
) => {
    // التحقق الإلزامي والصارم من الخط قبل البدء
    const isFontReady = await checkFontsReady(fontFamily);

    if (!isFontReady) {
        // محاولة أخيرة قصيرة المدى (Race condition mitigation)
        await new Promise(r => setTimeout(r, 500));
        const retryReady = await checkFontsReady(fontFamily);

        if (!retryReady) {
            console.error(`CRITICAL ERROR: Selected font "${fontFamily}" is not active in browser memory. Aborting PDF generation to maintain 100% accuracy.`);
            throw new Error(`تعذر تطبيق إعدادات الخط "${fontFamily}" بدقة. تم إيقاف التصدير لضمان الجودة.`);
        }
    }

    const { jsPDF } = jspdf;
    const pdf = new jsPDF({
        orientation: 'p',
        unit: 'px',
        format: pageSize,
        hotfixes: ['px_scaling'],
    });

    const storyContent = document.getElementById('story-content');
    if (!storyContent) return;

    try {
        await waitForImagesToLoad(storyContent);

        const storyPages = document.querySelectorAll('.story-page') as NodeListOf<HTMLElement>;
        const pdfWidth = pdf.internal.pageSize.getWidth();
        const pdfHeight = pdf.internal.pageSize.getHeight();

        for (let i = 0; i < storyPages.length; i++) {
            const page = storyPages[i];

            // التقاط الصفحة بدقة فائقة لضمان ثبات الخطوط والأحجام والألوان
            const canvas = await html2canvas(page, {
                scale: 4, 
                useCORS: true,
                logging: false,
                backgroundColor: null,
                width: page.offsetWidth,
                height: page.offsetHeight,
                onclone: (clonedDoc) => {
                    // التأكد من أن النسخة المستنسخة تلتزم بالخط المختار بشكل قاطع
                    const clonedPage = clonedDoc.querySelector('.story-page') as HTMLElement;
                    if (clonedPage) {
                        clonedPage.style.fontFamily = `"${fontFamily}", sans-serif`;
                    }
                }
            });

            const imgData = canvas.toDataURL('image/jpeg', 1.0);

            if (i > 0) pdf.addPage(pageSize, 'p');

            pdf.addImage(imgData, 'JPEG', 0, 0, pdfWidth, pdfHeight, undefined, 'FAST');
        }

        const fileName = `${storyTitle.replace(/\s+/g, '_')}_Manual_Settings.pdf`;
        pdf.save(fileName);
    } catch (error) {
        console.error("PDF generation failed:", error);
        throw error;
    }
};

import { GoogleGenAI, Modality, Type } from "@google/genai";
import { FormData, Story, Scene, Chapter } from '../types';
import { base64ToWav } from '../utils/audioHelper';

const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

async function retryOperation<T>(
    operation: () => Promise<T>,
    retries: number = 4,
    initialDelay: number = 6000,
    operationName: string = "Operation"
): Promise<T> {
    let currentDelay = initialDelay;
    for (let i = 0; i < retries; i++) {
        try {
            return await operation();
        } catch (error: any) {
            const isRateLimit = 
                error?.status === 429 || 
                error?.code === 429 || 
                error?.status === 'RESOURCE_EXHAUSTED' ||
                (error?.message && (
                    error.message.includes('429') || 
                    error.message.includes('quota') || 
                    error.message.includes('RESOURCE_EXHAUSTED')
                ));

            if (isRateLimit) {
                await wait(currentDelay);
                currentDelay *= 1.5;
                continue;
            }
            throw error;
        }
    }
    throw new Error(`${operationName} failed`);
}

const generateStoryText = async (formData: FormData): Promise<Story> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const { age, language, storyPrompt, numChapters, scenesPerChapter, childName } = formData;
    const prompt = `Create an exciting, fast-paced story for a ${age}-year-old named "${childName}" in ${language}. Tone: Adventurous and high energy. Theme: ${storyPrompt}. IMPORTANT: The child is the main hero. EXACTLY ${numChapters} chapters, ${scenesPerChapter} scenes each.`;

    return retryOperation(async () => {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        title: { type: Type.STRING },
                        chapters: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    chapter_number: { type: Type.INTEGER },
                                    title: { type: Type.STRING },
                                    scenes: {
                                        type: Type.ARRAY,
                                        items: {
                                            type: Type.OBJECT,
                                            properties: {
                                                scene_number: { type: Type.INTEGER },
                                                text: { type: Type.STRING },
                                                image_prompt: { type: Type.STRING },
                                            },
                                            required: ["scene_number", "text", "image_prompt"]
                                        },
                                    },
                                },
                                required: ["chapter_number", "title", "scenes"]
                            },
                        },
                    },
                    required: ["title", "chapters"]
                },
            },
        });
        return JSON.parse(response.text) as Story;
    }, 3, 5000, "Generate Story");
};

const generateImageForScene = async (prompt: string, baseImg: string, mime: string): Promise<string> => {
    // استخدام Nano Banana Pro (gemini-3-pro-image-preview) كما طلب المستخدم
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const editingPrompt = `CRITICAL MANDATORY RULE: YOU MUST NOT CHANGE THE CHILD'S FACE, HAIR, CLOTHES (unless necessary for the scene), OR PHYSICAL FEATURES. 
    KEEP THE EXACT IDENTITY AND REALISTIC LOOK OF THE CHILD FROM THE ATTACHED PHOTO. 
    DO NOT CARTOONIZE. DO NOT ILLUSTRATE. 
    Perform professional photorealistic editing using Nano Banana Pro technology to place THIS EXACT CHILD into this environment: ${prompt}. 
    The child's face and original shape must remain 100% IDENTICAL to the source image. 
    Only edit the background and integrate the child naturally into the scene with cinematic lighting.`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-image-preview',
            contents: { 
                parts: [
                    { inlineData: { data: baseImg, mimeType: mime } }, 
                    { text: editingPrompt }
                ] 
            },
            config: {
                imageConfig: {
                    aspectRatio: "1:1",
                    imageSize: "1K"
                }
            }
        });

        const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
        if (part && part.inlineData) {
            return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
        return "";
    } catch (e) { 
        console.error("Image generation failed with Nano Banana Pro", e);
        return ""; 
    }
};

const generateAudioSegment = async (text: string, voiceName: string): Promise<string | undefined> => {
    if (!text.trim()) return undefined;
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const fastPacedPrompt = `Speak this very energetically, quickly, and with high enthusiasm for a viral video: ${text}`;

    try {
        return await retryOperation(async () => {
            const response = await ai.models.generateContent({
                model: "gemini-2.5-flash-preview-tts",
                contents: { parts: [{ text: fastPacedPrompt }] },
                config: {
                    responseModalities: [Modality.AUDIO],
                    speechConfig: { 
                        voiceConfig: { 
                            prebuiltVoiceConfig: { 
                                voiceName: voiceName 
                            } 
                        } 
                    },
                },
            });
            const base64 = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData)?.inlineData?.data;
            if (!base64) return undefined;
            return URL.createObjectURL(base64ToWav(base64, 24000));
        }, 1, 2000, "Generate Audio");
    } catch { return undefined; }
};

export const generateStoryWorkflow = async (formData: FormData, imageData: any, updateStep: any): Promise<Story> => {
    updateStep("تجهيز سيناريو القصة...");
    const story = await generateStoryText(formData);
    const chapters: Chapter[] = [];

    updateStep("تسجيل المقدمة الحماسية...");
    const titleAudio = await generateAudioSegment(`إليكم قصة مذهلة! بعنوان: ${story.title}. بطلنا اليوم هو ${formData.childName}!`, formData.voiceName);

    for (const ch of story.chapters) {
        const scenes: Scene[] = [];
        for (const sc of ch.scenes) {
            updateStep(`جاري دمج الطفل في المشهد ${sc.scene_number} بواسطة Nano Banana Pro...`);
            const [img, aud] = await Promise.all([
                generateImageForScene(sc.image_prompt, imageData.data, imageData.mimeType),
                generateAudioSegment(sc.text, formData.voiceName)
            ]);
            scenes.push({ ...sc, imageUrl: img, audioUrl: aud });
        }
        chapters.push({ ...ch, scenes });
    }

    return { ...story, chapters, titleAudioUrl: titleAudio };
};

