import React, { useState, useRef } from 'react';
import { Story, PdfSettings } from '../types';
import { BookOpenIcon } from './icons/BookOpenIcon';
import { DownloadIcon } from './icons/DownloadIcon';
import { VideoIcon } from './icons/VideoIcon';
import { generatePdf } from '../utils/pdfHelper';
import { BookReader } from './BookReader';
import { generateStoryVideo } from '../utils/videoGenerator';
import { getStoryPages } from '../utils/storyHelper';
import { StoryPage } from './StoryPage';

interface StoryPreviewProps {
    story: Story;
}

export const StoryPreview: React.FC<StoryPreviewProps> = ({ story }) => {
    const [isDownloadingPdf, setIsDownloadingPdf] = useState(false);
    const [isGeneratingVideo, setIsGeneratingVideo] = useState(false);
    const [videoProgress, setVideoProgress] = useState('');
    const [videoPercent, setVideoPercent] = useState(0);
    const [isBookMode, setIsBookMode] = useState(false);
    const [showVideoOptions, setShowVideoOptions] = useState(false);
    const [showPdfOptions, setShowPdfOptions] = useState(false);

    // إعدادات الـ PDF التي يتحكم بها المستخدم يدوياً بالكامل
    const [pdfSettings, setPdfSettings] = useState<PdfSettings>({
        fontFamily: 'Cairo',
        fontSize: 28, 
        fontColor: '#1a1a1a',
        lineHeight: 1.8, 
        margins: 50,
        textAlign: 'right',
        pageSize: 'a4',
        direction: 'rtl',
        backgroundColor: '#ffffff'
    });

    const abortControllerRef = useRef<AbortController | null>(null);

    const handleDownloadPdf = async () => {
        setIsDownloadingPdf(true);
        setShowPdfOptions(false);
        try {
            // إرسال الإعدادات لضمان التطابق 100%
            await generatePdf(story.title, pdfSettings.pageSize, pdfSettings.fontFamily);
        } catch (error: any) {
            console.error("Failed to generate PDF", error);
            alert(error.message || "حدث خطأ أثناء إنشاء ملف PDF.");
        } finally {
            setIsDownloadingPdf(false);
        }
    };

    const handleDownloadVideo = async () => {
        if (isGeneratingVideo) return;
        setIsGeneratingVideo(true);
        setVideoPercent(0);
        setShowVideoOptions(false);
        abortControllerRef.current = new AbortController();

        try {
            await generateStoryVideo(story, (msg, percent) => {
                setVideoProgress(msg);
                setVideoPercent(percent);
            }, { 
                bitrate: 12000000, 
                fps: 30,
                signal: abortControllerRef.current.signal
            });
        } catch (error) {
            console.error("Video generation error:", error);
        } finally {
            setIsGeneratingVideo(false);
            setVideoProgress('');
            setVideoPercent(0);
            abortControllerRef.current = null;
        }
    };

    const storyPages = getStoryPages(story);

    const getMarginLabel = (m: number) => {
        if (m <= 25) return 'ضيقة جداً';
        if (m <= 40) return 'ضيقة';
        if (m <= 65) return 'افتراضية';
        if (m <= 90) return 'واسعة';
        return 'واسعة جداً';
    };

    return (
        <div className="bg-white p-4 md:p-8 rounded-3xl shadow-xl border border-rose-100">
            {isBookMode && <BookReader story={story} onClose={() => setIsBookMode(false)} />}

            {isGeneratingVideo && (
                <div className="fixed inset-0 z-[60] bg-black/90 flex flex-col items-center justify-center text-white p-6 text-center backdrop-blur-xl">
                    <div className="relative mb-8">
                        <div className="animate-spin rounded-full h-24 w-24 border-t-4 border-rose-500"></div>
                        <div className="absolute inset-0 flex items-center justify-center font-bold text-lg">
                            {videoPercent}%
                        </div>
                    </div>
                    <h2 className="text-2xl font-bold mb-2">جاري صنع الفيديو السحري</h2>
                    <p className="text-gray-300">{videoProgress}</p>
                </div>
            )}

            <div className="flex flex-col sm:flex-row justify-between items-center mb-10 border-b-2 border-rose-50 pb-6">
                <div className="flex items-center gap-4 mb-4 sm:mb-0">
                    <div className="p-3 bg-rose-50 rounded-2xl">
                        <BookOpenIcon className="h-8 w-8 text-rose-500" />
                    </div>
                    <div>
                        <h2 className="text-3xl font-bold text-rose-900 font-storybook">{story.title}</h2>
                        <p className="text-rose-400 text-sm">جاهزة للقراءة والتحميل</p>
                    </div>
                </div>

                <div className="flex flex-wrap gap-3 w-full sm:w-auto justify-center">
                    <button onClick={() => setIsBookMode(true)} className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-rose-500 text-white font-bold py-3 px-8 rounded-2xl hover:bg-rose-600 shadow-lg shadow-rose-100 transition-all active:scale-95">
                        <span>قراءة سحرية</span>
                    </button>

                    <div className="relative group">
                         <button onClick={() => { setShowPdfOptions(!showPdfOptions); setShowVideoOptions(false); }} className="flex-1 sm:flex-none flex items-center justify-center gap-2 bg-emerald-500 text-white font-bold py-3 px-8 rounded-2xl hover:bg-emerald-600 shadow-lg shadow-emerald-100 transition-all">
                            <DownloadIcon className="h-5 w-5" />
                            <span>تصميم PDF</span>
                        </button>

                        {showPdfOptions && (
                            <div className="absolute top-full mt-4 left-0 sm:right-0 w-full sm:w-96 bg-white border border-rose-100 shadow-2xl rounded-3xl p-6 z-50 text-right animate-in fade-in slide-in-from-top-4">
                                <div className="flex justify-between items-center mb-6 border-b pb-3">
                                    <h4 className="font-bold text-rose-800 text-lg">استوديو تصميم PDF</h4>
                                    <button onClick={() => setShowPdfOptions(false)} className="text-gray-400 hover:text-rose-500">
                                        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
                                    </button>
                                </div>

                                <div className="space-y-5 max-h-[70vh] overflow-y-auto px-1 custom-scrollbar">
                                    {/* التحكم في الخط */}
                                    <div className="grid grid-cols-2 gap-4">
                                        <div>
                                            <label className="block text-xs font-black text-gray-400 uppercase mb-2">نوع الخط</label>
                                            <select 
                                                value={pdfSettings.fontFamily} 
                                                onChange={(e) => setPdfSettings({...pdfSettings, fontFamily: e.target.value as any})}
                                                className="w-full bg-gray-50 border-none rounded-xl p-3 text-sm font-bold focus:ring-2 focus:ring-rose-500"
                                            >
                                                <option value="Cairo">Cairo (عصري)</option>
                                                <option value="Amiri">Amiri (كلاسيكي)</option>
                                                <option value="Lalezar">Lalezar (مرح)</option>
                                            </select>
                                        </div>
                                        <div>
                                            <label className="block text-xs font-black text-gray-400 uppercase mb-2">حجم الخط</label>
                                            <div className="flex items-center bg-gray-50 rounded-xl px-3">
                                                <input 
                                                    type="number" 
                                                    value={pdfSettings.fontSize} 
                                                    onChange={(e) => setPdfSettings({...pdfSettings, fontSize: Number(e.target.value)})}
                                                    className="w-full bg-transparent border-none p-3 text-sm font-bold outline-none" 
                                                />
                                                <span className="text-xs text-gray-400">px</span>
                                            </div>
                                        </div>
                                    </div>

                                    {/* التحكم في الألوان */}
                                    <div className="grid grid-cols-2 gap-4">
                                        <div>
                                            <label className="block text-xs font-black text-gray-400 uppercase mb-2">لون الخط</label>
                                            <div className="flex items-center gap-3 bg-gray-50 p-2 rounded-xl">
                                                <input 
                                                    type="color" 
                                                    value={pdfSettings.fontColor} 
                                                    onChange={(e) => setPdfSettings({...pdfSettings, fontColor: e.target.value})}
                                                    className="w-8 h-8 rounded-lg overflow-hidden border-none p-0 cursor-pointer" 
                                                />
                                                <span className="text-[10px] font-mono text-gray-500 uppercase">{pdfSettings.fontColor}</span>
                                            </div>
                                        </div>
                                        <div>
                                            <label className="block text-xs font-black text-gray-400 uppercase mb-2">لون الخلفية</label>
                                            <div className="flex items-center gap-3 bg-gray-50 p-2 rounded-xl">
                                                <input 
                                                    type="color" 
                                                    value={pdfSettings.backgroundColor} 
                                                    onChange={(e) => setPdfSettings({...pdfSettings, backgroundColor: e.target.value})}
                                                    className="w-8 h-8 rounded-lg overflow-hidden border-none p-0 cursor-pointer" 
                                                />
                                                <span className="text-[10px] font-mono text-gray-500 uppercase">{pdfSettings.backgroundColor}</span>
                                            </div>
                                        </div>
                                    </div>

                                    {/* تباعد الأسطر */}
                                    <div>
                                        <div className="flex justify-between items-center mb-2">
                                            <label className="text-xs font-black text-gray-400 uppercase">تباعد الأسطر</label>
                                            <span className="text-xs font-bold text-rose-500">{pdfSettings.lineHeight}x</span>
                                        </div>
                                        <input 
