import { GoogleGenAI, Modality, Type } from "@google/genai";
import { FormData, Story, Scene, Chapter } from '../types';
import { base64ToWav } from '../utils/audioHelper';

const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

async function retryOperation<T>(
    operation: () => Promise<T>,
    retries: number = 4,
    initialDelay: number = 6000,
    operationName: string = "Operation"
): Promise<T> {
    let currentDelay = initialDelay;
    for (let i = 0; i < retries; i++) {
        try {
            return await operation();
        } catch (error: any) {
            const isRateLimit = 
                error?.status === 429 || 
                error?.code === 429 || 
                error?.status === 'RESOURCE_EXHAUSTED' ||
                (error?.message && (
                    error.message.includes('429') || 
                    error.message.includes('quota') || 
                    error.message.includes('RESOURCE_EXHAUSTED')
                ));

            if (isRateLimit) {
                await wait(currentDelay);
                currentDelay *= 1.5;
                continue;
            }
            throw error;
        }
    }
    throw new Error(`${operationName} failed after retries`);
}

const generateStoryText = async (formData: FormData): Promise<Story> => {
    // إنشاء كائن AI جديد باستخدام المفتاح الحالي (قد يكون المفتاح المدفوع الذي أدخله المستخدم)
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const { age, language, storyPrompt, numChapters, scenesPerChapter, childName } = formData;
    const prompt = `Create an exciting, fast-paced story for a ${age}-year-old named "${childName}" in ${language}. Tone: Adventurous and high energy. Theme: ${storyPrompt}. IMPORTANT: The child is the main hero. EXACTLY ${numChapters} chapters, ${scenesPerChapter} scenes each. Output JSON only.`;

    return retryOperation(async () => {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        title: { type: Type.STRING },
                        chapters: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    chapter_number: { type: Type.INTEGER },
                                    title: { type: Type.STRING },
                                    scenes: {
                                        type: Type.ARRAY,
                                        items: {
                                            type: Type.OBJECT,
                                            properties: {
                                                scene_number: { type: Type.INTEGER },
                                                text: { type: Type.STRING },
                                                image_prompt: { type: Type.STRING },
                                            },
                                            required: ["scene_number", "text", "image_prompt"]
                                        },
                                    },
                                },
                                required: ["chapter_number", "title", "scenes"]
                            },
                        },
                    },
                    required: ["title", "chapters"]
                },
            },
        });
        return JSON.parse(response.text) as Story;
    }, 3, 5000, "Generate Story Script");
};

const generateImageForScene = async (prompt: string, baseImg: string, mime: string): Promise<string> => {
    // استخدام نموذج Pro للصور الذي يتطلب مفتاح API مدفوع (Nano Banana Pro)
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const editingPrompt = `CRITICAL MANDATORY RULE: YOU MUST NOT CHANGE THE CHILD'S FACE, HAIR, CLOTHES (unless necessary for the scene), OR PHYSICAL FEATURES. 
    KEEP THE EXACT IDENTITY AND REALISTIC LOOK OF THE CHILD FROM THE ATTACHED PHOTO. 
    Perform professional photorealistic editing using Nano Banana Pro technology to place THIS EXACT CHILD into this environment: ${prompt}. 
    The child's face and original shape must remain 100% IDENTICAL to the source image. 
    Only edit the background and integrate the child naturally into the scene with cinematic lighting.`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-image-preview',
            contents: { 
                parts: [
                    { inlineData: { data: baseImg, mimeType: mime } }, 
                    { text: editingPrompt }
                ] 
            },
            config: {
                imageConfig: {
                    aspectRatio: "1:1",
                    imageSize: "1K" // جودة عالية جداً
                }
            }
        });

        const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
        if (part && part.inlineData) {
            return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
        return "";
    } catch (e) { 
        console.error("Image generation failed with Nano Banana Pro", e);
        return ""; 
    }
};

const generateAudioSegment = async (text: string, voiceName: string): Promise<string | undefined> => {
    if (!text.trim()) return undefined;
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const fastPacedPrompt = `Speak this very energetically and clearly for a child's story: ${text}`;

    try {
        return await retryOperation(async () => {
            const response = await ai.models.generateContent({
                model: "gemini-2.5-flash-preview-tts",
                contents: { parts: [{ text: fastPacedPrompt }] },
                config: {
                    responseModalities: [Modality.AUDIO],
                    speechConfig: { 
                        voiceConfig: { 
                            prebuiltVoiceConfig: { 
                                voiceName: voiceName 
                            } 
                        } 
                    },
                },
            });
            const base64 = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData)?.inlineData?.data;
            if (!base64) return undefined;
            return URL.createObjectURL(base64ToWav(base64, 24000));
        }, 1, 2000, "Generate TTS Audio");
    } catch { return undefined; }
};

export const generateStoryWorkflow = async (formData: FormData, imageData: any, updateStep: any): Promise<Story> => {
    updateStep("تجهيز سيناريو القصة السحري...");
    const story = await generateStoryText(formData);
    const chapters: Chapter[] = [];

    updateStep("تسجيل المقدمة الحماسية بصوت الراوي...");
    const titleAudio = await generateAudioSegment(`إليكم قصة مذهلة بعنوان: ${story.title}. بطلنا اليوم هو ${formData.childName}!`, formData.voiceName);

    for (const ch of story.chapters) {
        const scenes: Scene[] = [];
        for (const sc of ch.scenes) {
            updateStep(`جاري دمج الطفل في المشهد ${sc.scene_number} باستخدام Nano Banana Pro...`);
            const [img, aud] = await Promise.all([
                generateImageForScene(sc.image_prompt, imageData.data, imageData.mimeType),
                generateAudioSegment(sc.text, formData.voiceName)
            ]);
            scenes.push({ ...sc, imageUrl: img, audioUrl: aud });
        }
        chapters.push({ ...ch, scenes });
    }

    return { ...story, chapters, titleAudioUrl: titleAudio };
};

import React, { useState, useCallback, useEffect } from 'react';
import { StoryForm } from './components/StoryForm';
import { StoryPreview } from './components/StoryPreview';
import { LoadingIndicator } from './components/LoadingIndicator';
import { MagicWandIcon } from './components/icons/MagicWandIcon';
import { BookOpenIcon } from './components/icons/BookOpenIcon';
import { FormData, Story } from './types';
import { generateStoryWorkflow } from './services/geminiService';
import { saveStoryToDB, getAllStoriesFromDB, deleteStoryFromDB } from './services/storageService';
import { StoryArchive } from './components/StoryArchive';

type AppView = 'create' | 'archive' | 'view-story';

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }
  interface Window {
    aistudio?: AIStudio;
  }
}

const App: React.FC = () => {
    const [view, setView] = useState<AppView>('create');
    const [story, setStory] = useState<Story | null>(null);
    const [archive, setArchive] = useState<Story[]>([]);
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [loadingStep, setLoadingStep] = useState<string>('');
    const [error, setError] = useState<string | null>(null);
    const [needsApiKey, setNeedsApiKey] = useState<boolean>(false);

    useEffect(() => {
        loadArchive();
        checkApiKey();
    }, []);

    const checkApiKey = async () => {
        if (window.aistudio) {
            const hasKey = await window.aistudio.hasSelectedApiKey();
            setNeedsApiKey(!hasKey);
        }
    };

    const handleOpenKeySelector = async () => {
        if (window.aistudio) {
            await window.aistudio.openSelectKey();
            // بعد فتح النافذة، نفترض النجاح للمتابعة
            setNeedsApiKey(false);
        }
    };

    const loadArchive = async () => {
        try {
            const stories = await getAllStoriesFromDB();
            setArchive(stories);
        } catch (err) {
            console.error("Failed to load archive", err);
        }
    };

    const handleStoryGeneration = useCallback(async (formData: FormData, imageData: { data: string; mimeType: string; }) => {
        // التحقق من وجود مفتاح قبل البدء (ضروري لنماذج Pro)
        if (window.aistudio) {
            const hasKey = await window.aistudio.hasSelectedApiKey();
            if (!hasKey) {
                setNeedsApiKey(true);
                return;
            }
        }

        setIsLoading(true);
        setError(null);
        setStory(null);

        const updateStep = (step: string) => {
            setLoadingStep(String(step));
        };

        try {
            const generatedStory = await generateStoryWorkflow(formData, imageData, updateStep);

            const storyToSave: Story = {
                ...generatedStory,
                id: crypto.randomUUID(),
                timestamp: Date.now()
            };

            await saveStoryToDB(storyToSave);

            setStory(storyToSave);
            setView('view-story');
            loadArchive();
        } catch (err: any) {
            console.error('Error generating story:', err);
            let errorMessage = 'حدث خطأ غير متوقع أثناء إنشاء القصة. يرجى المحاولة مرة أخرى.';
            const errorStr = String(err?.message || err || '');

            if (errorStr.includes('429') || errorStr.includes('quota')) {
                errorMessage = 'لقد تجاوزت الحد المسموح للاستخدام حالياً. يرجى الانتظار قليلاً أو التأكد من رصيد مفتاحك المدفوع.';
            } else if (errorStr.includes('Requested entity was not found')) {
                errorMessage = 'حدثت مشكلة في مفتاح API المختار. يرجى إعادة اختيار مفتاح صالح وفعال.';
                setNeedsApiKey(true);
            }

            setError(errorMessage);
        } finally {
            setIsLoading(false);
            setLoadingStep('');
        }
    }, []);

    const handleViewStory = (selectedStory: Story) => {
        setStory(selectedStory);
        setView('view-story');
    };

    const handleDeleteFromArchive = async (id: string) => {
        try {
            await deleteStoryFromDB(id);
            setArchive(prev => prev.filter(s => s.id !== id));
            if (story?.id === id) {
                setStory(null);
                setView('create');
            }
        } catch (err) {
            alert("فشل حذف القصة من الأرشيف.");
        }
    };

    return (
        <div className="min-h-screen bg-rose-50 text-gray-800 pb-12" dir="rtl">
            <header className="bg-white shadow-md sticky top-0 z-40">
                <div className="container mx-auto px-4 py-3 flex flex-col sm:flex-row items-center justify-between gap-4">
                    <div className="flex items-center gap-3 cursor-pointer" onClick={() => setView('create')}>
                        <MagicWandIcon className="h-8 w-8 text-rose-500" />
                        <h1 className="text-xl md:text-2xl font-bold text-rose-800">صانع قصص الأطفال</h1>
                    </div>

                    <nav className="flex items-center bg-rose-50 p-1 rounded-xl border border-rose-100">
                        <button 
                            onClick={() => setView('create')}
                            className={`px-6 py-2 rounded-lg font-bold transition flex items-center gap-2 ${view === 'create' || view === 'view-story' ? 'bg-white text-rose-600 shadow-sm' : 'text-gray-500 hover:text-rose-600'}`}
                        >
                            <MagicWandIcon className="h-4 w-4" />
                            <span>إنشاء قصة</span>
                        </button>
                        <button 
                            onClick={() => setView('archive')}
                            className={`px-6 py-2 rounded-lg font-bold transition flex items-center gap-2 ${view === 'archive' ? 'bg-white text-rose-600 shadow-sm' : 'text-gray-500 hover:text-rose-600'}`}
                        >
                            <BookOpenIcon className="h-4 w-4" />
                            <span>أرشيفي ({archive.length})</span>
                        </button>
                    </nav>
                </div>
            </header>

            <main className="container mx-auto p-4 md:p-8">
                {needsApiKey ? (
                    <div className="max-w-xl mx-auto bg-white p-10 rounded-3xl shadow-2xl text-center border-4 border-rose-100">
                        <div className="w-20 h-20 bg-amber-50 rounded-full flex items-center justify-center mx-auto mb-6">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-amber-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 7a2 2 0 012 2m4 0a6 6 0 01-7.743 5.743L11 17H9v2H7v2H4a1 1 0 01-1-1v-2.586a1 1 0 01.293-.707l5.964-5.964A6 6 0 1121 9z" />
                            </svg>
                        </div>
                        <h2 className="text-2xl font-bold text-gray-800 mb-4">تفعيل تقنية Nano Banana Pro المدفوعة</h2>
                        <p className="text-gray-600 mb-8 leading-relaxed">
                            للحصول على صور بجودة فائقة ودمج ملامح طفلك بدقة 100%، يرجى تفعيل استخدام مفتاح الـ API الخاص بك أدناه.
                        </p>
                        <button 
                            onClick={handleOpenKeySelector}
                            className="w-full bg-rose-500 text-white font-bold py-4 rounded-2xl hover:bg-rose-600 shadow-lg shadow-rose-100 transition-all active:scale-95 mb-4 flex items-center justify-center gap-3"
                        >
                            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M21 2l-2 2m-7.61 7.61a5.5 5.5 0 1 1-7.778 7.778 5.5 5.5 0 0 1 7.777-7.777zm0 0L15.5 7.5m0 0l3 3m-3-3l-2.25-2.25"/></svg>
                            <span>استخدام مفتاح API الخاص بي</span>
                        </button>
                        <p className="text-xs text-rose-400">
                            ملاحظة: سيتم استخدام المفتاح فقط لهذه الجلسة ولن يتم تخزينه خارج جهازك.
                        </p>
                    </div>
                ) : (
                    view === 'archive' ? (
                        <div className="max-w-4xl mx-auto">
                            <div className="flex items-center gap-3 mb-8">
                                <BookOpenIcon className="h-8 w-8 text-rose-500" />
                                <h2 className="text-3xl font-bold text-rose-800 font-storybook">أرشيف مغامراتي</h2>
                            </div>
                            <StoryArchive stories={archive} onViewStory={handleViewStory} onDeleteStory={handleDeleteFromArchive} />
                        </div>
                    ) : (
                        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                            <div className="lg:col-span-4">
                                <StoryForm onSubmit={handleStoryGeneration} isLoading={isLoading} />
                            </div>
                            <div className="lg:col-span-8">
                                {isLoading && <LoadingIndicator step={loadingStep} />}
                                {error && (
                                    <div className="bg-red-50 border-l-4 border-red-500 text-red-700 p-6 rounded-2xl shadow-sm" role="alert">
                                        <div className="flex items-center gap-3 mb-2 font-bold text-lg">
                                            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
                                            <span>تنبيه</span>
                                        </div>
                                        <p className="text-base">{String(error)}</p>
                                        <button onClick={() => setError(null)} className="mt-4 text-xs font-bold underline">إغلاق التنبيه</button>
                                    </div>
                                )}
                                {story && !isLoading && !error && <div className="animate-in fade-in slide-in-from-bottom-4 duration-500"><StoryPreview story={story} /></div>}
                                {!story && !isLoading && !error && (
                                     <div className="flex flex-col items-center justify-center h-full bg-white rounded-3xl p-12 shadow-xl border-2 border-dashed border-rose-100 min-h-[500px] text-center">
                                        <div className="w-32 h-32 bg-rose-50 rounded-full flex items-center justify-center mb-8 animate-bounce">
                                            <MagicWandIcon className="h-16 w-16 text-rose-400" />
                                        </div>
                                        <h2 className="text-3xl font-bold text-rose-800 mb-4 font-storybook">جاهز للبدء؟</h2>
                                        <p className="text-gray-500 max-w-sm leading-relaxed text-lg">ارفع صورة طفلك الآن لنقوم بتحويله إلى بطل حقيقي في عالم سحري باستخدام Nano Banana Pro.</p>
                                    </div>
                                )}
                            </div>
                        </div>
                    )
                )}
            </main>
        </div>
    );
};

