import React from 'react';
import { Story } from '../types';
import { getStoryPages } from './storyHelper';

const VIDEO_WIDTH = 1080; 
const VIDEO_HEIGHT = 1920;
const TRANSITION_MS = 300; // وقت الانتقال بين اللقطات بالملي ثانية
const ZOOM_START = 1.0;
const ZOOM_END = 1.25;

const getSupportedMimeType = () => {
    const types = ['video/webm;codecs=vp9,opus', 'video/webm', 'video/mp4'];
    for (const type of types) if (MediaRecorder.isTypeSupported(type)) return type;
    return '';
};

const drawCinematicOverlay = (ctx: CanvasRenderingContext2D) => {
    // 1. Vignette Effect (أطراف داكنة لتركيز الانتباه)
    const gradient = ctx.createRadialGradient(
        VIDEO_WIDTH / 2, VIDEO_HEIGHT / 2, VIDEO_WIDTH / 3,
        VIDEO_WIDTH / 2, VIDEO_HEIGHT / 2, VIDEO_HEIGHT * 0.8
    );
    gradient.addColorStop(0, 'rgba(0,0,0,0)');
    gradient.addColorStop(1, 'rgba(0,0,0,0.5)');
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, VIDEO_WIDTH, VIDEO_HEIGHT);

    // 2. Subtle Grain (حبيبات فيلم خفيفة جداً للواقعية)
    ctx.globalAlpha = 0.03;
    for (let i = 0; i < 50; i++) {
        const x = Math.random() * VIDEO_WIDTH;
        const y = Math.random() * VIDEO_HEIGHT;
        const size = Math.random() * 2;
        ctx.fillStyle = 'white';
        ctx.fillRect(x, y, size, size);
    }
    ctx.globalAlpha = 1.0;
};

const drawTikTokCaptions = (ctx: CanvasRenderingContext2D, text: string, fontSize: number) => {
    if (!text) return;
    const words = text.split(' ');
    const maxWidth = VIDEO_WIDTH * 0.8;
    const lineHeight = fontSize * 1.4;
    const lines = [];
    let currentLine = '';

    ctx.font = `bold ${fontSize}px 'Cairo', sans-serif`;

    for (const word of words) {
        const testLine = currentLine + word + ' ';
        if (ctx.measureText(testLine).width > maxWidth && currentLine !== '') {
            lines.push(currentLine.trim());
            currentLine = word + ' ';
        } else {
            currentLine = testLine;
        }
    }
    lines.push(currentLine.trim());

    const totalHeight = lines.length * lineHeight;
    let y = (VIDEO_HEIGHT * 0.8) - (totalHeight / 2);

    lines.forEach(line => {
        const textWidth = ctx.measureText(line).width;
        const x = VIDEO_WIDTH / 2;

        // رسم صندوق خلفية النص (TikTok Style Box)
        ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
        const boxPadding = fontSize * 0.4;
        const boxWidth = textWidth + boxPadding * 2;
        const boxHeight = lineHeight * 0.9;

        // رسم مستطيل بزوايا مستديرة خلف النص
        const radius = 15;
        ctx.beginPath();
        ctx.roundRect(x - boxWidth / 2, y - boxHeight * 0.75, boxWidth, boxHeight, radius);
        ctx.fill();

        // رسم النص
        ctx.fillStyle = 'white';
        ctx.textAlign = 'center';
        ctx.fillText(line, x, y);
        y += lineHeight;
    });
};

const loadAudio = async (url: string, audioContext: AudioContext): Promise<AudioBuffer> => {
    if (!url) return audioContext.createBuffer(1, 44100, 44100);
    const res = await fetch(url);
    const buf = await res.arrayBuffer();
    return await audioContext.decodeAudioData(buf);
};

export const generateStoryVideo = async (
    story: Story, 
    onProgress: (msg: string, percent: number) => void,
    config: any
): Promise<void> => {
    const { fps = 30, bitrate = 18000000, textFontSize = 60, signal } = config;
    const mimeType = getSupportedMimeType();

    onProgress("بدء الإنتاج السينمائي...", 5);

    const canvas = document.createElement('canvas');
    canvas.width = VIDEO_WIDTH;
    canvas.height = VIDEO_HEIGHT;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
    const dest = audioContext.createMediaStreamDestination();

    const videoStream = canvas.captureStream(fps);
    const combinedStream = new MediaStream([...videoStream.getVideoTracks(), ...dest.stream.getAudioTracks()]);
    const recorder = new MediaRecorder(combinedStream, { 
        mimeType, 
        videoBitsPerSecond: bitrate 
    }); 

    const chunks: Blob[] = [];
    recorder.ondataavailable = (e) => chunks.push(e.data);

    return new Promise(async (resolve, reject) => {
        recorder.onstop = () => {
            const blob = new Blob(chunks, { type: mimeType });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `Kids_Hero_Story_${Date.now()}.mp4`;
            a.click();
            audioContext.close();
            resolve();
        };

        recorder.start();
        const pages = getStoryPages(story);

        try {
            for (let i = 0; i < pages.length; i++) {
                if (signal?.aborted) throw new Error("CANCELLED");
                const page = pages[i];
                onProgress(`جاري دمج المشهد ${i + 1} بأعلى جودة...`, 10 + (i / pages.length) * 80);

                const audioBuf = await loadAudio(page.audioUrl || '', audioContext);
                const source = audioContext.createBufferSource();
                source.buffer = audioBuf;
                source.connect(dest);
                source.start();

                const img = new Image();
                if (page.imageUrl) {
                    img.src = page.imageUrl;
                    await new Promise(r => img.onload = r);
                }

                // تحديد اتجاه حركة الكاميرا عشوائياً لكل مشهد
                const panDirection = i % 2 === 0 ? 1 : -1; 
                const durationMs = audioBuf.duration * 1000;
                const startTime = performance.now();

                while (true) {
                    const elapsed = performance.now() - startTime;
                    if (elapsed >= durationMs) break;

                    const p = elapsed / durationMs;

                    // تحريك الكاميرا (Ken Burns Effect)
                    const scale = ZOOM_START + (p * (ZOOM_END - ZOOM_START));
                    const panX = (panDirection * p * 50); // تحرك أفقي بسيط

                    // تنظيف الإطار
                    ctx.fillStyle = '#050505';
                    ctx.fillRect(0, 0, VIDEO_WIDTH, VIDEO_HEIGHT);

                    if (page.imageUrl) {
                        // حساب أبعاد الصورة لتغطي الشاشة بالكامل (Object-fit: cover)
                        const imgRatio = img.width / img.height;
                        const canvasRatio = VIDEO_WIDTH / VIDEO_HEIGHT;

                        let drawW, drawH;
                        if (imgRatio > canvasRatio) {
                            drawH = VIDEO_HEIGHT;
                            drawW = VIDEO_HEIGHT * imgRatio;
                        } else {
                            drawW = VIDEO_WIDTH;
                            drawH = VIDEO_WIDTH / imgRatio;
                        }

                        const finalW = drawW * scale;
                        const finalH = drawH * scale;

                        ctx.save();
                        ctx.translate(VIDEO_WIDTH / 2 + panX, VIDEO_HEIGHT / 2);
                        ctx.drawImage(img, -finalW / 2, -finalH / 2, finalW, finalH);
                        ctx.restore();
                    } else {
                        // صفحات العناوين
                        const grad = ctx.createLinearGradient(0, 0, 0, VIDEO_HEIGHT);
                        grad.addColorStop(0, '#f43f5e');
                        grad.addColorStop(1, '#881337');
                        ctx.fillStyle = grad;
                        ctx.fillRect(0, 0, VIDEO_WIDTH, VIDEO_HEIGHT);
                    }

                    // إضافة التأثيرات السينمائية
                    drawCinematicOverlay(ctx);

                    // رسم النصوص بأسلوب الترند
                    const currentText = page.text || page.title || "";
                    drawTikTokCaptions(ctx, currentText, textFontSize);

                    // تأثير التلاشي عند النهاية (Fade out at transition)
                    if (elapsed > durationMs - TRANSITION_MS) {
                        const fadeAlpha = (durationMs - elapsed) / TRANSITION_MS;
                        ctx.fillStyle = `rgba(0,0,0,${1 - fadeAlpha})`;
                        ctx.fillRect(0, 0, VIDEO_WIDTH, VIDEO_HEIGHT);
                    }

                    await new Promise(r => requestAnimationFrame(r));
                }

                source.stop();
            }
            recorder.stop();
        } catch (e) {
            if (recorder.state !== 'inactive') recorder.stop();
            reject(e);
        }
    });
};

import { GoogleGenAI, Modality, Type } from "@google/genai";
import { FormData, Story, Scene, Chapter } from '../types';
import { base64ToWav } from '../utils/audioHelper';

const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

async function retryOperation<T>(
    operation: () => Promise<T>,
    retries: number = 4,
    initialDelay: number = 6000,
    operationName: string = "Operation"
): Promise<T> {
    let currentDelay = initialDelay;
    for (let i = 0; i < retries; i++) {
        try {
            return await operation();
        } catch (error: any) {
            const isRateLimit = 
                error?.status === 429 || 
                error?.code === 429 || 
                error?.status === 'RESOURCE_EXHAUSTED' ||
                (error?.message && (
                    error.message.includes('429') || 
                    error.message.includes('quota') || 
                    error.message.includes('RESOURCE_EXHAUSTED')
                ));

            if (isRateLimit) {
                await wait(currentDelay);
                currentDelay *= 1.5;
                continue;
            }
            throw error;
        }
    }
    throw new Error(`${operationName} failed after retries`);
}

const generateStoryText = async (formData: FormData): Promise<Story> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const { age, language, storyPrompt, numChapters, scenesPerChapter, childName } = formData;
    const prompt = `Create an exciting story for a ${age}-year-old named "${childName}" in ${language}. Theme: ${storyPrompt}. IMPORTANT: The child is the main hero. EXACTLY ${numChapters} chapters, ${scenesPerChapter} scenes each. Output JSON only.`;

    return retryOperation(async () => {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        title: { type: Type.STRING },
                        chapters: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    chapter_number: { type: Type.INTEGER },
                                    title: { type: Type.STRING },
                                    scenes: {
                                        type: Type.ARRAY,
                                        items: {
                                            type: Type.OBJECT,
                                            properties: {
                                                scene_number: { type: Type.INTEGER },
                                                text: { type: Type.STRING },
                                                image_prompt: { type: Type.STRING },
                                            },
                                            required: ["scene_number", "text", "image_prompt"]
                                        },
                                    },
                                },
                                required: ["chapter_number", "title", "scenes"]
                            },
                        },
                    },
                    required: ["title", "chapters"]
                },
            },
        });
        return JSON.parse(response.text) as Story;
    }, 3, 5000, "Generate Story Script");
};

const generateImageForScene = async (prompt: string, baseImg: string, mime: string): Promise<string> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // أوامر تعديل صور احترافية سينمائية فائقة الواقعية
    const editingPrompt = `You are a world-class cinematic photo editor.
    TASK: INTEGRATE THE CHILD FROM THE PHOTO INTO A NEW SCENE WITH 100% PHOTOREALISM.

    MANDATORY PHOTOREALISM RULES:
    1. ZERO STYLIZATION: Do NOT convert the child to a cartoon, anime, drawing, or illustration.
    2. TOTAL AUTHENTICITY: The child's face, hair texture, skin tone, and unique features must remain IDENTICAL to the original photo.
    3. SEAMLESS INTEGRATION: Place the REAL child naturally into this scene: ${prompt}.
    4. LIGHTING & SHADOWS: Apply volumetric cinematic lighting that matches the environment (e.g. golden hour, dappled forest light) to the child's face and body.
    5. QUALITY: 8k resolution, cinematic action movie style, realistic depth of field, sharp focus on the child.

    The final image must look like a real photograph of this specific child in a magical/action setting.`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: { 
                parts: [
                    { inlineData: { data: baseImg, mimeType: mime } }, 
                    { text: editingPrompt }
                ] 
            },
            config: {
                imageConfig: {
                    aspectRatio: "1:1"
                }
            }
        });

        const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
        if (part && part.inlineData) {
            return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
        return "";
    } catch (e) { 
        console.error("Image generation failed", e);
        return ""; 
    }
};

const generateAudioSegment = async (text: string, voiceName: string): Promise<string | undefined> => {
    if (!text.trim()) return undefined;
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
        return await retryOperation(async () => {
            const response = await ai.models.generateContent({
                model: "gemini-2.5-flash-preview-tts",
                contents: { parts: [{ text: text }] },
                config: {
                    responseModalities: [Modality.AUDIO],
                    speechConfig: { 
                        voiceConfig: { 
                            prebuiltVoiceConfig: { 
                                voiceName: voiceName 
                            } 
                        } 
                    },
                },
            });
            const base64 = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData)?.inlineData?.data;
            if (!base64) return undefined;
            return URL.createObjectURL(base64ToWav(base64, 24000));
        }, 1, 2000, "Generate TTS Audio");
    } catch { return undefined; }
};

export const generateStoryWorkflow = async (formData: FormData, imageData: any, updateStep: any): Promise<Story> => {
    updateStep("جاري كتابة مغامرتك السحرية...");
    const story = await generateStoryText(formData);
    const chapters: Chapter[] = [];

    updateStep("جاري تحضير صوت الراوي...");
    const titleAudio = await generateAudioSegment(`قصة ${story.title}. بطلنا هو ${formData.childName}!`, formData.voiceName);

    for (const ch of story.chapters) {
        const scenes: Scene[] = [];
        for (const sc of ch.scenes) {
            updateStep(`جاري دمج بطلنا في المشهد ${sc.scene_number}...`);
            const [img, aud] = await Promise.all([
                generateImageForScene(sc.image_prompt, imageData.data, imageData.mimeType),
                generateAudioSegment(sc.text, formData.voiceName)
            ]);
            scenes.push({ ...sc, imageUrl: img, audioUrl: aud });
        }
        chapters.push({ ...ch, scenes });
    }

    return { ...story, chapters, titleAudioUrl: titleAudio };
};

import React from 'react';
import { Story } from '../types';
import { getStoryPages } from './storyHelper';

const VIDEO_WIDTH = 1080; 
const VIDEO_HEIGHT = 1920;
const TRANSITION_MS = 400; // وقت الانتقال بين اللقطات
const ZOOM_START = 1.0;
const ZOOM_END = 1.3;

const getSupportedMimeType = () => {
    const types = ['video/webm;codecs=vp9,opus', 'video/webm', 'video/mp4'];
    for (const type of types) if (MediaRecorder.isTypeSupported(type)) return type;
    return '';
};

const drawCinematicOverlay = (ctx: CanvasRenderingContext2D) => {
    // 1. Vignette Effect (عمق سينمائي)
    const gradient = ctx.createRadialGradient(
        VIDEO_WIDTH / 2, VIDEO_HEIGHT / 2, VIDEO_WIDTH / 4,
        VIDEO_WIDTH / 2, VIDEO_HEIGHT / 2, VIDEO_HEIGHT * 0.7
    );
    gradient.addColorStop(0, 'rgba(0,0,0,0)');
    gradient.addColorStop(1, 'rgba(0,0,0,0.6)');
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, VIDEO_WIDTH, VIDEO_HEIGHT);

    // 2. High-End Color Correction (لمسة دافئة خفيفة)
    ctx.globalCompositeOperation = 'overlay';
    ctx.fillStyle = 'rgba(255, 150, 50, 0.05)';
    ctx.fillRect(0, 0, VIDEO_WIDTH, VIDEO_HEIGHT);
    ctx.globalCompositeOperation = 'source-over';

    // 3. Subtle Film Grain
    ctx.globalAlpha = 0.02;
    for (let i = 0; i < 40; i++) {
        const x = Math.random() * VIDEO_WIDTH;
        const y = Math.random() * VIDEO_HEIGHT;
        ctx.fillStyle = 'white';
        ctx.fillRect(x, y, 2, 2);
    }
    ctx.globalAlpha = 1.0;
};

const drawTikTokCaptions = (ctx: CanvasRenderingContext2D, text: string, fontSize: number) => {
    if (!text) return;
    const words = text.split(' ');
    const maxWidth = VIDEO_WIDTH * 0.85;
    const lineHeight = fontSize * 1.5;
    const lines = [];
    let currentLine = '';

    ctx.font = `bold ${fontSize}px 'Cairo', sans-serif`;

    for (const word of words) {
        const testLine = currentLine + word + ' ';
        if (ctx.measureText(testLine).width > maxWidth && currentLine !== '') {
            lines.push(currentLine.trim());
            currentLine = word + ' ';
        } else {
            currentLine = testLine;
        }
    }
    lines.push(currentLine.trim());

    const totalHeight = lines.length * lineHeight;
    let y = (VIDEO_HEIGHT * 0.82) - (totalHeight / 2);

    lines.forEach(line => {
        const textWidth = ctx.measureText(line).width;
        const x = VIDEO_WIDTH / 2;

        // TikTok Style Background Box
        ctx.fillStyle = 'rgba(0, 0, 0, 0.75)';
        const paddingH = fontSize * 0.5;
        const paddingV = fontSize * 0.2;
        const boxWidth = textWidth + paddingH * 2;
        const boxHeight = lineHeight * 0.9;

        ctx.beginPath();
        ctx.roundRect(x - boxWidth / 2, y - boxHeight * 0.78, boxWidth, boxHeight, 12);
        ctx.fill();

        // Glow effect for text
        ctx.shadowColor = 'rgba(255,255,255,0.2)';
        ctx.shadowBlur = 10;
        ctx.fillStyle = 'white';
        ctx.textAlign = 'center';
        ctx.fillText(line, x, y);
        ctx.shadowBlur = 0;

        y += lineHeight;
    });
};

const loadAudio = async (url: string, audioContext: AudioContext): Promise<AudioBuffer> => {
    if (!url) return audioContext.createBuffer(1, 44100, 44100);
    const res = await fetch(url);
    const buf = await res.arrayBuffer();
    return await audioContext.decodeAudioData(buf);
};

export const generateStoryVideo = async (
    story: Story, 
    onProgress: (msg: string, percent: number) => void,
    config: any
): Promise<void> => {
    const { fps = 30, bitrate = 20000000, textFontSize = 65, signal } = config;
    const mimeType = getSupportedMimeType();

    onProgress("تجهيز الاستوديو السينمائي...", 5);

    const canvas = document.createElement('canvas');
    canvas.width = VIDEO_WIDTH;
    canvas.height = VIDEO_HEIGHT;
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) return;

    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
    const dest = audioContext.createMediaStreamDestination();

    const videoStream = canvas.captureStream(fps);
    const combinedStream = new MediaStream([...videoStream.getVideoTracks(), ...dest.stream.getAudioTracks()]);
    const recorder = new MediaRecorder(combinedStream, { 
        mimeType, 
        videoBitsPerSecond: bitrate 
    }); 

    const chunks: Blob[] = [];
    recorder.ondataavailable = (e) => chunks.push(e.data);

    return new Promise(async (resolve, reject) => {
        recorder.onstop = () => {
            const blob = new Blob(chunks, { type: mimeType });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `Trend_Story_${Date.now()}.mp4`;
            a.click();
            audioContext.close();
            resolve();
        };

        recorder.start();
        const pages = getStoryPages(story);

        try {
            for (let i = 0; i < pages.length; i++) {
                if (signal?.aborted) throw new Error("CANCELLED");
                const page = pages[i];
                onProgress(`إخراج المشهد ${i + 1} بجودة 4K...`, 10 + (i / pages.length) * 85);

                const audioBuf = await loadAudio(page.audioUrl || '', audioContext);
                const source = audioContext.createBufferSource();
                source.buffer = audioBuf;
                source.connect(dest);
                source.start();

                const img = new Image();
                if (page.imageUrl) {
                    img.src = page.imageUrl;
                    await new Promise(r => img.onload = r);
                }

                const panDirectionX = (i % 3 - 1) * 40; 
                const panDirectionY = (i % 2 === 0 ? 1 : -1) * 30;
                const durationMs = audioBuf.duration * 1000;
                const startTime = performance.now();

                while (true) {
                    const elapsed = performance.now() - startTime;
                    if (elapsed >= durationMs) break;

                    const p = elapsed / durationMs;

                    // Ultra-Smooth Camera Motion
                    const scale = ZOOM_START + (p * (ZOOM_END - ZOOM_START));
                    const currentPanX = p * panDirectionX;
                    const currentPanY = p * panDirectionY;

                    ctx.fillStyle = '#000';
                    ctx.fillRect(0, 0, VIDEO_WIDTH, VIDEO_HEIGHT);

                    if (page.imageUrl) {
                        const imgRatio = img.width / img.height;
                        const canvasRatio = VIDEO_WIDTH / VIDEO_HEIGHT;

                        let drawW, drawH;
                        if (imgRatio > canvasRatio) {
                            drawH = VIDEO_HEIGHT;
                            drawW = VIDEO_HEIGHT * imgRatio;
                        } else {
                            drawW = VIDEO_WIDTH;
                            drawH = VIDEO_WIDTH / imgRatio;
                        }

                        const finalW = drawW * scale;
                        const finalH = drawH * scale;

                        ctx.save();
                        ctx.translate(VIDEO_WIDTH / 2 + currentPanX, VIDEO_HEIGHT / 2 + currentPanY);
                        ctx.drawImage(img, -finalW / 2, -finalH / 2, finalW, finalH);
                        ctx.restore();
                    } else {
                        const grad = ctx.createLinearGradient(0, 0, 0, VIDEO_HEIGHT);
                        grad.addColorStop(0, '#e11d48');
                        grad.addColorStop(1, '#4c0519');
                        ctx.fillStyle = grad;
                        ctx.fillRect(0, 0, VIDEO_WIDTH, VIDEO_HEIGHT);
                    }

                    drawCinematicOverlay(ctx);
                    drawTikTokCaptions(ctx, page.text || page.title || "", textFontSize);

                    // Smooth Transition Fade
                    if (elapsed > durationMs - TRANSITION_MS) {
                        const fade = (durationMs - elapsed) / TRANSITION_MS;
                        ctx.fillStyle = `rgba(0,0,0,${1 - fade})`;
                        ctx.fillRect(0, 0, VIDEO_WIDTH, VIDEO_HEIGHT);
                    }
                    if (elapsed < TRANSITION_MS && i > 0) {
                        const fade = elapsed / TRANSITION_MS;
                        ctx.fillStyle = `rgba(0,0,0,${1 - fade})`;
                        ctx.fillRect(0, 0, VIDEO_WIDTH, VIDEO_HEIGHT);
                    }

                    await new Promise(r => requestAnimationFrame(r));
                }

                source.stop();
            }
            recorder.stop();
        } catch (e) {
            if (recorder.state !== 'inactive') recorder.stop();
            reject(e);
        }
    });
};

